-- RT-L2 Module 2 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip DR — flat panel detector', '{"slides":[{"heading":"Apa itu DR","body":"Digital Radiography (DR) merekam gambar langsung pada flat panel detector (FPD) tanpa film maupun imaging plate terpisah. Radiasi yang lolos benda uji langsung dikonversi menjadi sinyal listrik di detektor, lalu ditampilkan sebagai gambar digital dalam hitungan detik. Inilah pembeda utama DR vs CR: DR = direct/real-time, sedangkan CR memakai imaging plate berfosfor (PSP) yang harus dipindai laser di scanner terpisah setelah eksposur."},{"heading":"Direct vs indirect conversion","body":"Indirect (a-Si): sintilator (CsI:Tl atau Gd2O2S) mengubah sinar-X jadi cahaya tampak, lalu fotodioda amorphous silicon (a-Si) mengubah cahaya jadi muatan. Direct (a-Se): photoconductor amorphous selenium (a-Se) langsung mengubah sinar-X jadi muatan tanpa tahap cahaya, sehingga blur lateral minimal dan ketajaman lebih tinggi. CsI berstruktur kolom (needle-like) menyalurkan cahaya seperti serat optik untuk menjaga resolusi."},{"heading":"Struktur panel & TFT array","body":"Di bawah lapisan konversi terdapat matriks TFT (thin film transistor) yang membaca muatan per piksel. Ukuran piksel (pixel pitch) tipikal 100-200 µm; pitch kecil = resolusi spasial lebih tinggi tapi noise per piksel cenderung meningkat. Panel umum 14x17 inci (35x43 cm). Setiap eksposur menghasilkan citra dengan kedalaman 12-16 bit (4096-65536 gray level)."},{"heading":"Kenapa DR untuk volume tinggi","body":"DR unggul di produksi serial/volume tinggi: tidak ada film consumable, tidak ada kamar gelap/proses kimia, review instan, dan arsip langsung digital. Trade-off: harga panel mahal (~$50k+), panel rentan rusak mekanis serta degradasi radiasi kumulatif, dan butuh manajemen kalibrasi rutin. Untuk transisi bertahap atau kerja lapangan, CR sering lebih ekonomis dan fleksibel."}]}', 460, NULL),
  (2, 'reading', 'Metrik kualitas citra digital', '{"slides":[{"heading":"Basic spatial resolution (SRb)","body":"SRb adalah ukuran ketajaman efektif sistem digital, diukur dengan duplex wire IQI (ASTM E2002 / ISO 19232-5) dan dinyatakan dalam µm; nilainya = setengah dari jarak pasangan kawat terkecil yang masih terlihat terpisah (separuh unsharpness terbaca). SRb menggantikan konsep ''unsharpness film''. Kombinasi geometric unsharpness Ug = F x OFD / SOD dan inherent unsharpness detektor menentukan total ketajaman. SRb kecil (mis. 80-100 µm) = sistem lebih tajam."},{"heading":"SNR, CNR & normalisasi","body":"Signal-to-Noise Ratio (SNR) = sinyal rata-rata / standar deviasi noise. ISO 17636-2 mensyaratkan SNR ternormalisasi (SNRnorm) ke basic spatial resolution acuan agar perbandingan adil antar sistem dengan pixel pitch berbeda. Contrast-to-Noise Ratio (CNR) menentukan apakah defect kontras-rendah terdeteksi di atas noise. Frame averaging menaikkan SNR sekitar akar(N) untuk N frame yang dirata-rata."},{"heading":"DQE, dynamic range & gray level","body":"DQE (Detective Quantum Efficiency) mengukur efisiensi detektor mengubah dosis radiasi jadi informasi citra berguna; DQE tinggi = SNR baik pada dosis lebih rendah. Dynamic range DR jauh melebihi film: satu eksposur dapat menangkap rentang ketebalan lebar tanpa over/under-exposure. Kedalaman 16-bit (65536 gray level) memberi ruang windowing kontras yang luas tanpa kehilangan data."},{"heading":"Lag, ghosting & bad pixel","body":"Image lag (sisa muatan dari eksposur sebelumnya) dan ghosting menurunkan kontras citra berikutnya; dikelola dengan delay/refresh. Bad pixel (dead/hot) dipetakan dan dikoreksi via interpolasi; jumlah & ukuran cluster bad pixel dibatasi standar. Offset/gain calibration (flat-field) wajib rutin untuk menyeragamkan respons piksel dan menghilangkan fixed-pattern noise."}]}', 500, NULL),
  (3, 'reading', 'Real-time imaging & kalibrasi DR', '{"slides":[{"heading":"Real-time / online imaging","body":"DR memungkinkan radioskopi real-time: benda bergerak/diputar di depan panel sambil operator mengamati citra live (mis. weld, casting, jalur produksi). Frame rate tipikal 1-30 fps. Untuk objek diam, frame averaging/integration meningkatkan SNR; untuk objek bergerak, frame rate tinggi mengurangi motion blur — keduanya saling trade-off."},{"heading":"Kalibrasi flat-field (offset/gain/bad pixel)","body":"Tiga langkah wajib secara berurutan: (1) Offset/dark-field — baca panel tanpa radiasi untuk koreksi arus gelap; (2) Gain/flat-field — eksposur seragam tanpa benda untuk menyeragamkan sensitivitas piksel; (3) Bad pixel map — identifikasi & interpolasi piksel cacat. Kalibrasi diulang sesuai jadwal QC atau saat kVp/filter berubah signifikan."},{"heading":"Post-processing yang sah","body":"DR mengizinkan windowing (brightness/contrast/level-window), zoom/pan, dan filter (edge enhancement, noise reduction). Penting: post-processing untuk interpretasi tidak boleh menghapus/menyembunyikan indikasi. Citra mentah (raw) wajib diarsip; enhancement bersifat tampilan saja. Per ISO 17636-2 & ASME V, parameter pemrosesan harus terdokumentasi dan dapat direproduksi."},{"heading":"QC harian sistem DR","body":"QC harian: cek SRb dengan duplex wire, verifikasi SNRnorm pada step wedge/IQI, periksa bad pixel baru, dan konfirmasi sensitivitas IQI (wire ASTM E747 / hole-type ASTM E1025) tercapai. Density film tidak relevan untuk DR — digantikan oleh SNR & gray-value linearity. Dokumentasikan baseline agar drift detektor terpantau."}]}', 480, NULL),
  (4, 'reading', 'Kode, IQI & penerapan DR', '{"slides":[{"heading":"ASME V Article 2 untuk digital","body":"ASME Section V Article 2 mengatur RT; appendiks digital (ketentuan untuk DR/CR) menetapkan persyaratan SRb, SNR, dan demonstrasi sistem. T-274 (source/teknik), T-276 (penempatan IQI), T-282 (kualitas citra). Untuk digital, IQI sensitivity tetap acuan utama selain SRb — keduanya harus dipenuhi, bukan salah satu."},{"heading":"IQI pada DR","body":"Wire-type IQI per ASTM E747 / ISO 19232 atau hole-type (plaque) per ASTM E1025 (lubang 1T/2T/4T) tetap dipakai untuk membuktikan sensitivitas. Target umum 2-2T (~2% sensitivitas) tergantung kode/ketebalan. Duplex wire (ASTM E2002) khusus untuk mengukur SRb — fungsinya berbeda dari IQI sensitivitas, jangan tertukar."},{"heading":"ISO 17636-2 (digital) vs 17636-1 (film)","body":"ISO 17636-1 mengatur RT film; ISO 17636-2 mengatur teknik digital (DR/CR) dengan kelas A (basic) dan kelas B (improved) yang menetapkan SNRnorm minimum dan SRb maksimum per ketebalan. Memilih kelas B menuntut SNR lebih tinggi & SRb lebih halus. AWS D1.1 Clause 8 dan API 1104 juga mengakui digital dengan kualifikasi teknik tersendiri."},{"heading":"Kapan pilih DR","body":"Pilih DR untuk: produksi volume tinggi, kebutuhan hasil instan/real-time, geometri stabil & berulang, dan saat budget capex tersedia. Hindari DR jika: akses lapangan sulit/panel rentan, anggaran terbatas (pertimbangkan CR), atau ketebalan sangat tinggi yang menuntut sumber Co-60 (1.17 & 1.33 MeV, t½≈5.27 tahun) dengan handling khusus. ALARA tetap berlaku: review digital cepat justru menurunkan re-shoot dan dosis kumulatif."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Digital Radiography (DR)', '{"description":"8 soal: prinsip flat panel detector, metrik kualitas citra digital (SRb, SNR, DQE), real-time imaging, kalibrasi flat-field, dan penerapan kode/IQI untuk DR.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 2
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 2 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Apa pembeda fundamental Digital Radiography (DR) dibanding Computed Radiography (CR)?',
   '["DR merekam citra langsung pada flat panel detector tanpa langkah scan terpisah, sedangkan CR memerlukan imaging plate berfosfor yang dipindai laser setelah eksposur","DR menggunakan film basah sedangkan CR menggunakan film kering","DR hanya untuk material magnetik, CR untuk non-magnetik","DR memakai sumber gamma sedangkan CR memakai sinar-X saja"]', 0,
   'DR (direct/real-time) mengonversi radiasi menjadi sinyal listrik langsung di flat panel detector dan menampilkan citra dalam hitungan detik. CR menggunakan imaging plate berfosfor (PSP) yang harus dipindai laser di scanner terpisah setelah eksposur, jadi tidak real-time. Tidak ada kaitan dengan sifat magnetik material atau jenis sumber radiasi.', 'Prinsip DR', 'easy'),
  ('Pada flat panel detector tipe indirect conversion berbasis a-Si, apa urutan konversi sinyal yang benar?',
   '["Sinar-X langsung menjadi muatan listrik di amorphous selenium","Sinar-X menjadi cahaya tampak di sintilator (CsI/Gd2O2S), lalu cahaya menjadi muatan di fotodioda a-Si yang dibaca array TFT","Sinar-X menjadi panas, lalu panas menjadi tegangan di TFT","Sinar-X menjadi muatan di TFT, lalu muatan menjadi cahaya di sintilator"]', 1,
   'Indirect (a-Si): sintilator seperti CsI:Tl atau Gd2O2S mengubah sinar-X menjadi cahaya tampak, kemudian fotodioda amorphous silicon mengubah cahaya menjadi muatan listrik yang dibaca array TFT. Konversi langsung sinar-X ke muatan tanpa tahap cahaya adalah ciri detektor direct a-Se.', 'Prinsip DR', 'medium'),
  ('Basic Spatial Resolution (SRb) pada sistem digital diukur menggunakan apa, dan apa artinya bila nilainya kecil?',
   '["Diukur dengan hole-type IQI; nilai kecil berarti kontras rendah","Diukur dengan densitometer; nilai kecil berarti density film tinggi","Diukur dengan duplex wire IQI (ASTM E2002 / ISO 19232-5); nilai kecil (mis. ~80 µm) berarti sistem lebih tajam","Diukur dengan step wedge; nilai kecil berarti dynamic range sempit"]', 2,
   'SRb diukur dengan duplex wire IQI per ASTM E2002 / ISO 19232-5 dan dinyatakan dalam µm (setengah jarak pasangan kawat terkecil yang masih terpisah). SRb merepresentasikan ketajaman efektif sistem digital (pengganti konsep unsharpness film); nilai SRb yang lebih kecil berarti resolusi spasial lebih tinggi / citra lebih tajam.', 'Kualitas citra digital', 'medium'),
  ('Mengapa ISO 17636-2 menggunakan SNR ternormalisasi (SNRnorm) dan bukan SNR mentah saja?',
   '["Karena SNR mentah tidak bisa dihitung pada sistem digital","Karena SNRnorm sama dengan density film pada RT digital","Karena normalisasi menghilangkan kebutuhan akan IQI","Agar perbandingan adil antar sistem dengan menormalkan SNR terhadap basic spatial resolution/ketebalan acuan"]', 3,
   'SNRnorm menormalkan SNR terukur terhadap basic spatial resolution agar sistem dengan resolusi/pixel pitch berbeda dapat dibandingkan secara adil. ISO 17636-2 menetapkan SNRnorm minimum per kelas (A/B) sehingga kualitas citra terjamin lintas peralatan. SNR mentah tetap dapat dihitung, dan IQI tetap diperlukan.', 'Kualitas citra digital', 'hard'),
  ('Sebuah objek diam difoto dengan DR dan SNR terlalu rendah. Teknik mana yang paling tepat menaikkan SNR tanpa menambah blur?',
   '["Menaikkan frame rate setinggi mungkin","Frame averaging/integration beberapa frame, yang menaikkan SNR sekitar akar(N)","Mengaktifkan edge enhancement filter maksimum","Memperbesar pixel pitch detektor"]', 1,
   'Untuk objek diam, merata-ratakan N frame menaikkan SNR sekitar akar(N) tanpa menambah motion blur (karena objek tidak bergerak). Frame rate tinggi justru untuk objek bergerak; edge enhancement tidak menambah informasi sinyal nyata; memperbesar pixel pitch malah menurunkan resolusi.', 'Real-time imaging', 'medium'),
  ('Manakah urutan langkah kalibrasi flat-field yang benar beserta tujuannya pada DR?',
   '["Densitometry harian untuk verifikasi density 2.0-4.0","Offset/dark-field (koreksi arus gelap), gain/flat-field (menyeragamkan sensitivitas piksel), lalu bad pixel map (interpolasi piksel cacat)","Hanya bad pixel map; untuk menaikkan kVp","Hanya gain calibration; untuk menambah dynamic range detektor"]', 1,
   'Kalibrasi flat-field DR terdiri dari offset/dark-field (mengoreksi arus gelap tanpa radiasi), gain/flat-field (eksposur seragam tanpa benda untuk menyeragamkan respons piksel dan menghapus fixed-pattern noise), dan bad pixel map (memetakan serta menginterpolasi piksel dead/hot). Density film tidak relevan untuk DR.', 'Kalibrasi DR', 'medium'),
  ('Pada interpretasi citra DR, apa aturan penting terkait post-processing menurut praktik ASME V / ISO 17636-2?',
   '["Citra raw boleh dihapus setelah versi enhancement disimpan","Edge enhancement wajib dimaksimalkan agar semua indikasi terlihat","Windowing kontras dilarang karena mengubah data citra","Post-processing tidak boleh menghapus/menyembunyikan indikasi; citra raw wajib diarsip dan parameter pemrosesan harus terdokumentasi serta dapat direproduksi"]', 3,
   'Windowing, zoom, dan filter diperbolehkan untuk membantu interpretasi, tetapi tidak boleh menghilangkan atau menutupi indikasi. Citra mentah (raw) wajib diarsip karena enhancement bersifat tampilan saja, dan semua parameter pemrosesan harus terdokumentasi agar hasil dapat direproduksi dan diaudit.', 'Kode & interpretasi DR', 'medium'),
  ('Untuk membuktikan sensitivitas (~2%) pada radiografi DR, IQI mana yang dipakai, dan apa peran berbeda dari duplex wire?',
   '["Duplex wire untuk sensitivitas 2-2T; wire/hole-type untuk SRb","Wire-type (ASTM E747) atau hole-type (ASTM E1025, lubang 1T/2T/4T) untuk sensitivitas; duplex wire (ASTM E2002) khusus mengukur SRb","Densitometer untuk sensitivitas; duplex wire untuk density","Hanya step wedge untuk keduanya"]', 1,
   'Sensitivitas dibuktikan dengan wire-type IQI (ASTM E747 / ISO 19232) atau hole-type plaque (ASTM E1025 dengan lubang 1T/2T/4T), target umum 2-2T (~2%). Duplex wire IQI (ASTM E2002) berbeda fungsinya: ia mengukur basic spatial resolution (SRb), bukan sensitivitas kontras. Pada DR keduanya harus dipenuhi.', 'Kode & interpretasi DR', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 2 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 3 — Computed Radiography (CR) (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip CR & Imaging Plate (PSP)', '{"slides":[{"heading":"Apa itu Computed Radiography","body":"CR adalah teknik radiografi digital tidak langsung (indirect): radiasi direkam dahulu pada Imaging Plate (IP) berbahan photostimulable phosphor (PSP), lalu plate dipindai (scan) oleh laser untuk membaca citra. Berbeda dengan DR (direct, flat-panel a-Si/a-Se) yang menghasilkan citra mendekati real-time tanpa langkah scanning terpisah. CR menjadi jembatan transisi favorit dari film karena workflow paling mirip film (kaset + plate fleksibel) namun tanpa proses kimia darkroom."},{"heading":"Mekanisme PSP","body":"Lapisan fosfor (umumnya BaFBr:Eu2+ atau BaFI:Eu) menyerap energi sinar-X/gamma dan menyimpan elektron dalam color centers (perangkap energi metastabil) — disebut latent image. Saat dipindai laser merah (~633-680 nm), elektron terangsang keluar (photostimulated luminescence/PSL) memancarkan cahaya biru (~390-400 nm) yang ditangkap photomultiplier tube (PMT) dan didigitalisasi. Intensitas PSL sebanding dengan dosis radiasi lokal yang diterima IP."},{"heading":"Dynamic range superior","body":"Keunggulan utama PSP adalah dynamic range / latitude sangat lebar — respon mendekati linier terhadap dosis mencakup ~4-5 dekade (10^4-10^5), jauh melebihi film (~2 dekade pada rentang densitas berguna). Satu exposure CR dapat menampilkan rentang ketebalan luas (mis. step/wedge atau pipa multi-thickness) yang pada film akan over/under-exposed. Ini mengurangi retake akibat salah eksposur."},{"heading":"Karakteristik praktis IP","body":"IP fleksibel (dapat ditekuk mengikuti pipa), reusable ribuan kali, dan tersedia dalam ukuran film standar. Latent image meluruh (fading) seiring waktu — sebaiknya dipindai dalam ~10-30 menit hingga maksimal sekitar 1 jam setelah eksposur (fading dapat mencapai ~25% dalam 8 jam tergantung jenis plate). Setelah scan, IP dihapus (erase) dengan flood lamp intensitas tinggi agar siap dipakai ulang."}]}', 460, NULL),
  (2, 'reading', 'Scanner & Parameter Kualitas Citra', '{"slides":[{"heading":"Alur kerja scanner","body":"Scanner CR memindai IP baris demi baris dengan laser fokus presisi, mengumpulkan PSL via light guide ke PMT, lalu ADC mengubah sinyal analog ke nilai digital. Parameter scan utama: laser spot size & scan pitch (menentukan resolusi spasial), gain/sensitivity PMT, dan kedalaman bit (12-16 bit = 4.096-65.536 gray level). Setelah dibaca, IP otomatis melewati erase unit sebelum dipakai kembali."},{"heading":"Basic Spatial Resolution (SRb)","body":"Metrik resolusi spasial kunci CR per ISO 17636-2 adalah Basic Spatial Resolution (SRb), bukan sekadar lp/mm. SRb diukur dengan duplex wire IQI (ASTM E2002 / ISO 19232-5) — terkait setengah nilai unsharpness pada pasangan kawat terkecil yang masih ter-resolve. SRb dipengaruhi laser spot, scan pitch, ukuran kristal fosfor, dan scatter cahaya dalam plate. Plate kelas resolusi tinggi (IP fine) + scan pitch halus = SRb lebih kecil (citra lebih tajam)."},{"heading":"SNR dan gray level","body":"ISO 17636-2 mensyaratkan Signal-to-Noise Ratio ternormalisasi (SNRn) minimum sesuai kelas teknik (Class A vs Class B yang lebih ketat). SNR naik dengan menambah dosis (mAs lebih tinggi atau waktu eksposur lebih lama). Trade-off klasik: SNR tinggi butuh dosis lebih besar, sementara SRb halus butuh plate/scan khusus — Level II harus menyeimbangkan keduanya sesuai kelas teknik yang dipersyaratkan code/prosedur."},{"heading":"Faktor degradasi","body":"Sumber penurunan kualitas khas CR: fading (tunda scan terlalu lama), scatter/halasi cahaya laser di dalam plate, dead/dirty pixel & goresan pada plate, erase tidak sempurna (ghost image / residual latent), serta light leak yang menyebabkan fogging. QC rutin: cek artefak dan ghosting, serta verifikasi SRb scanner dengan duplex wire IQI secara berkala."}]}', 480, NULL),
  (3, 'reading', 'Eksposur, IQI & Code untuk CR', '{"slides":[{"heading":"Geometri tetap berlaku","body":"Hukum fisika radiografi tidak berubah pada CR. Geometric unsharpness Ug = F x OFD / SOD tetap dihitung (F = ukuran focal-spot/sumber, OFD = jarak objek ke detektor/IP, SOD = jarak sumber ke objek) — gunakan SOD memadai dan OFD minimum. Inverse-square law I proporsional 1/d^2 tetap dipakai menyesuaikan jarak/waktu. Yang berubah: latitude lebar membuat pemilihan kV/teknik lebih toleran, dan tidak ada densitas film — kualitas dinilai lewat SNR + gray-level window, bukan densitas 1.8-4.0."},{"heading":"IQI dan sensitivitas","body":"IQI tetap wajib: wire-type per ASTM E747/ISO 19232 atau hole-type (plaque) per ASTM E1025 dengan lubang 1T/2T/4T. Sensitivitas esensial ~2% (2-2T) tetap menjadi target. Tambahan khas CR/digital: duplex wire IQI (ASTM E2002) untuk verifikasi SRb (interpretasi citra). IQI ditempatkan di sisi sumber bila memungkinkan, sama seperti pada film."},{"heading":"Code & kelas teknik","body":"Acuan CR: ISO 17636-2 (radiografi digital — CR & DR) yang mendefinisikan Class A (basic) dan Class B (improved, lebih ketat pada SRb/SNR). ASME Section V Article 2 mengatur CR melalui mandatory appendix untuk computed radiography (persyaratan SRb, IQI, kalibrasi). Kriteria penerimaan (acceptance) cacat tetap mengikuti construction code (mis. ASME VIII, AWS D1.1 Clause 8, API 1104)."},{"heading":"Post-processing terkendali","body":"Citra CR boleh diolah: window/level (brightness/contrast), zoom, edge enhancement, dan filter noise. Aturan kunci Level II: setiap post-processing harus terdokumentasi dan tidak boleh menyembunyikan maupun menciptakan indikasi palsu. Citra raw / ''for the record'' wajib disimpan tanpa modifikasi. Window/level menggantikan praktik high-low density film (dua kali eksposur) tanpa perlu retake."}]}', 470, NULL),
  (4, 'reading', 'Workflow Transisi Film ke CR', '{"slides":[{"heading":"Mengapa CR untuk transisi","body":"CR dipilih sebagai langkah transisi dari film karena: kaset & plate berperilaku seperti film (drop-in pada teknik existing), fleksibel untuk pipa/geometri kompleks, biaya per-exposure rendah (plate reusable), dan tanpa darkroom/kimia. DR lebih cepat namun panelnya kaku & mahal (~$50k+ per panel) serta kurang fleksibel untuk geometri lapangan. Banyak shop memulai dari CR sebelum beralih ke DR."},{"heading":"Langkah workflow CR","body":"1) Muat IP ke kaset di ruang gelap/aman. 2) Eksposur seperti film (atur kV, mAs/waktu, SOD, OFD). 3) Scan IP sesegera mungkin untuk menghindari fading. 4) Review pada monitor terkalibrasi di lingkungan pencahayaan rendah. 5) Atur window/level, ukur indikasi. 6) Simpan citra raw + report. 7) Erase IP agar siap dipakai ulang."},{"heading":"Validasi & perubahan SDM","body":"Transisi membutuhkan: kualifikasi/validasi prosedur digital (technique sheet baru dengan target SRb & SNR), kalibrasi monitor (luminance, kurva grayscale DICOM/GSDF), dan pelatihan ulang interpreter — membaca citra digital pada layar berbeda dari viewing film di lightbox. Level II bertanggung jawab menulis prosedur dan melatih Level I pada workflow baru."},{"heading":"Arsip digital & audit trail","body":"Citra disimpan dalam format standar (mis. DICONDE / DICOM-NDT atau TIFF 16-bit tanpa kompresi lossy) lengkap dengan metadata: parameter eksposur, ID plate/scanner, operator, tanggal, serta IQI/SRb yang dicapai. Retensi mengikuti code/klien. Audit trail mencatat setiap langkah post-processing. Arsip digital menggantikan lemari film — hemat ruang dan mudah retrieval, namun memerlukan backup serta jaminan integritas data."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Computed Radiography (CR)', '{"description":"7 soal: prinsip PSP, scanner & SRb/SNR, IQI digital, geometri, dan workflow transisi film-ke-CR.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 3
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 3 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Material apa yang umum digunakan sebagai lapisan photostimulable phosphor (PSP) pada Imaging Plate CR?',
   '["Amorphous silicon (a-Si)","Barium fluorohalide doped europium (mis. BaFBr:Eu2+)","Cadmium telluride (CdTe)","Gadolinium oxysulfide intensifying screen"]', 1,
   'Imaging Plate CR menggunakan photostimulable phosphor berbasis barium fluorohalide yang didoping europium, mis. BaFBr:Eu2+ atau BaFI:Eu, yang menyimpan latent image dalam color centers. a-Si dan CdTe adalah material detektor DR (direct), sedangkan gadolinium oxysulfide adalah lead/rare-earth screen untuk film, bukan PSP.', 'CR Principles', 'medium'),
  ('Pada pembacaan CR, panjang gelombang cahaya yang dipancarkan plate (PSL) saat dirangsang laser merah dibandingkan laser perangsang adalah:',
   '["Lebih panjang (bergeser ke merah)","Sama persis dengan laser perangsang","Lebih pendek (cahaya biru ~390-400 nm) sehingga dapat dipisahkan dari laser","Tidak ada cahaya; pembacaan bersifat listrik langsung"]', 2,
   'Laser perangsang berwarna merah (~633-680 nm), sedangkan photostimulated luminescence yang dipancarkan plate berwarna biru (~390-400 nm). Karena panjang gelombangnya lebih pendek dan berbeda dari laser, cahaya PSL dapat difilter secara optik dan ditangkap PMT secara terpisah dari pantulan laser.', 'CR Principles', 'hard'),
  ('Mengapa Imaging Plate sebaiknya dipindai segera setelah eksposur (dalam menit hingga sekitar 1 jam)?',
   '["Karena latent image meluruh (fading) sehingga sinyal/SNR menurun seiring waktu","Karena plate akan terbakar secara fisik bila terlalu lama disimpan","Karena scatter radiasi terus bertambah di dalam plate setelah eksposur","Karena densitas film akan melebihi 4.0 bila pembacaan ditunda"]', 0,
   'Latent image pada PSP mengalami fading — elektron terperangkap perlahan lepas, sehingga sinyal melemah (mis. ~25% dalam 8 jam tergantung plate). Penundaan menurunkan SNR dan kualitas citra. CR tidak memiliki densitas film, dan scatter terjadi saat eksposur berlangsung, bukan terus bertambah sesudahnya.', 'CR Workflow', 'medium'),
  ('Metrik kualitas citra spasial utama untuk CR menurut ISO 17636-2, yang diverifikasi dengan duplex wire IQI (ASTM E2002 / ISO 19232-5), adalah:',
   '["Half-Value Layer (HVL)","Densitas film optik (1.8-4.0)","Basic Spatial Resolution (SRb)","Equivalent Penetrameter Sensitivity (EPS)"]', 2,
   'Basic Spatial Resolution (SRb) adalah metrik resolusi spasial kunci untuk radiografi digital/CR, diverifikasi dengan duplex wire IQI per ASTM E2002 / ISO 19232-5. HVL adalah parameter atenuasi; densitas optik adalah konsep film (tidak berlaku di CR); EPS adalah konsep sensitivitas penetrameter, bukan metrik resolusi scanner.', 'Image Quality', 'medium'),
  ('Keunggulan dynamic range (latitude) PSP CR dibandingkan film adalah:',
   '["Latitude lebih sempit, sehingga kontras lebih tinggi pada satu ketebalan","Latitude jauh lebih lebar (~4-5 dekade) sehingga rentang ketebalan luas terekam dalam satu eksposur","Latitude sebanding film, yaitu sekitar 2 dekade","Tidak memiliki latitude karena respons bersifat biner (hitam/putih)"]', 1,
   'PSP memiliki respons mendekati linier terhadap dosis selama ~4-5 dekade (10^4-10^5), jauh lebih lebar dari film (~2 dekade pada rentang densitas berguna). Ini memungkinkan satu eksposur menangkap rentang ketebalan luas tanpa over/under-exposure, sehingga mengurangi retake — keunggulan besar dalam transisi ke CR.', 'Image Quality', 'easy'),
  ('Saat menaikkan SNR (Signal-to-Noise Ratio) citra CR agar memenuhi Class B ISO 17636-2, trade-off utamanya adalah:',
   '["Resolusi spasial (SRb) otomatis ikut membaik tanpa biaya tambahan","Fading latent image menjadi jauh lebih lambat","Dosis radiasi (mAs / waktu eksposur) harus dinaikkan","Ukuran focal spot mengecil dengan sendirinya"]', 2,
   'SNR meningkat dengan menambah dosis (mAs lebih tinggi atau waktu eksposur lebih lama). Class B lebih ketat daripada Class A pada SRb dan SNR. Menaikkan SNR tidak otomatis memperbaiki resolusi (SRb dipengaruhi plate/scan pitch/laser spot), tidak mengubah laju fading, dan tidak memengaruhi ukuran focal spot.', 'Image Quality', 'hard'),
  ('Aturan post-processing citra CR yang benar untuk seorang Level II adalah:',
   '["Boleh meng-edit citra secara bebas asalkan hasil akhir lulus IQI","Window/level dan enhancement boleh, tetapi harus terdokumentasi dan citra raw asli wajib disimpan tanpa modifikasi","Post-processing dilarang sama sekali pada semua citra digital NDT","Citra harus dicetak ke film terlebih dahulu sebelum boleh diolah"]', 1,
   'Post-processing seperti window/level, zoom, dan edge enhancement diperbolehkan untuk membantu interpretasi, tetapi harus didokumentasikan (audit trail) dan tidak boleh menyembunyikan atau menciptakan indikasi. Citra raw ''for the record'' wajib disimpan tanpa modifikasi demi integritas data dan keterlacakan.', 'CR Workflow', 'medium'),
  ('Mengapa CR sering dipilih sebagai langkah transisi dari film dibandingkan langsung ke DR?',
   '["CR memberikan citra real-time yang lebih cepat daripada DR","DR tidak memerlukan IQI sedangkan CR memerlukannya","Plate CR fleksibel, drop-in pada teknik film existing, dan berbiaya per-exposure rendah (reusable) tanpa panel kaku yang mahal","CR selalu menghasilkan resolusi spasial lebih tinggi daripada DR"]', 2,
   'CR berperilaku mirip film (kaset + plate fleksibel mengikuti pipa, drop-in pada workflow existing) dengan plate reusable berbiaya rendah dan tanpa darkroom kimia. DR justru lebih cepat (mendekati real-time) namun panelnya kaku dan mahal (~$50k+), sehingga kurang ideal untuk geometri lapangan. Keduanya tetap memerlukan IQI.', 'Film-to-Digital Transition', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 3 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 4 — Real-time Imaging (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip Real-time Radiography (RTR)', '{"slides":[{"heading":"Apa itu RTR / fluoroskopi digital","body":"Real-time Radiography (RTR) menampilkan citra radiografi secara langsung di monitor tanpa proses film. Radiasi melewati objek, mengenai detektor (image intensifier atau flat-panel DR a-Si/a-Se), lalu dikonversi menjadi sinyal video/digital pada laju 25-30 frame per detik (fps). Operator melihat indikasi seketika dan dapat memutar atau menggeser objek untuk mendapatkan sudut pandang terbaik (dynamic imaging) — tidak mungkin dilakukan dengan film statis."},{"heading":"Online vs offline inspection","body":"Online (in-line) RTR diintegrasikan ke jalur produksi: objek bergerak melalui zona pancaran dan diperiksa 100% pada kecepatan produksi (contoh: las pipa spiral, casting roda, ban). Offline RTR adalah stasiun manual/semi-otomatis untuk evaluasi per komponen. Online menuntut throughput tinggi sehingga SNR per frame rendah — di sinilah frame averaging menjadi kunci untuk memenuhi sensitivitas IQI."},{"heading":"Geometri tetap berlaku","body":"Hukum geometri film tetap berlaku pada RTR. Ketajaman geometri Ug = F x OFD / SOD, dengan F = ukuran focal-spot/sumber, OFD = jarak objek-detektor, SOD = jarak sumber-objek. Pada RTR, image intensifier sering tebal sehingga OFD efektif besar; gunakan micro-focus tube (F kecil, 0,4-1,0 mm atau bahkan <0,1 mm) dan minimalkan OFD untuk menjaga Ug rendah. Hukum kuadrat terbalik I proporsional 1/d^2 mengatur intensitas pada detektor: menggandakan jarak menurunkan intensitas menjadi seperempat."},{"heading":"Image intensifier vs flat-panel","body":"Image intensifier (II) klasik: input phosphor -> fotokatoda -> percepatan elektron -> output phosphor -> kamera CCD. Kelebihan: gain tinggi, dosis rendah, real-time mulus. Kekurangan: distorsi geometri (pincushion/S-distortion), veiling glare, resolusi terbatas. Flat-panel DR menggantikan II: tidak ada distorsi geometri, dynamic range 12-16 bit, resolusi spasial lebih baik (SRb lebih kecil), tetapi lebih mahal dan refresh rate perlu diperhatikan untuk dynamic imaging."}]}', 460, NULL),
  (2, 'reading', 'Frame Averaging & Pengelolaan Noise', '{"slides":[{"heading":"Mengapa frame averaging diperlukan","body":"Citra real-time tunggal didominasi quantum noise (mottle) karena foton per frame sedikit pada laju 25-30 fps. SNR satu frame sering tidak cukup untuk melihat 2-2T (sensitivitas IQI ~2%). Frame averaging menjumlahkan N frame berurutan dan membaginya, sehingga sinyal tetap sementara random noise berkurang sesuai akar N: SNR meningkat sebesar akar-N. Contoh: rata-rata 16 frame menaikkan SNR ~4x; 64 frame ~8x."},{"heading":"Trade-off averaging vs throughput & gerak","body":"Averaging hanya valid bila objek dan geometri DIAM relatif terhadap detektor selama N frame. Pada inspeksi statis (offline), N besar (32-256 frame) memberi citra sangat bersih. Pada online inspection objek bergerak, averaging banyak frame menimbulkan motion blur — komprominya: kurangi kecepatan jalur, gunakan recursive/running average dengan bobot, atau pakai detektor dosis-efisien (DQE tinggi) sehingga lebih sedikit frame dibutuhkan untuk SNR target."},{"heading":"Recursive averaging & noise filtering","body":"Recursive (running) averaging: frame_tampil = alfa x frame_sekarang + (1-alfa) x frame_sebelumnya. Nilai alfa kecil = penghalusan kuat tetapi lag/ghosting tinggi saat ada gerak; alfa besar = responsif tetapi lebih berisik. Selain temporal averaging, filter spasial (median, low-pass) menekan noise dalam satu frame namun menurunkan resolusi. Praktik Level II: utamakan temporal averaging untuk objek diam, batasi filter spasial agar tidak merusak SRb/deteksi defect halus."},{"heading":"Verifikasi sensitivitas, bukan tampilan","body":"Penampakan ''bersih'' di monitor tidak menjamin compliance. Buktikan sensitivitas dengan IQI: wire-type per ASTM E747 / ISO 19232 atau hole-type plaque per ASTM E1025 (lubang 1T/2T/4T). Target umum 2-2T (~2%). Pada sistem digital, ukur SNR/CNR dan basic spatial resolution (SRb) sebagai parameter QC kuantitatif. Bila kawat/lubang IQI esensial tidak terbaca pada parameter averaging produksi, teknik tidak qualified meski citra terlihat halus."}]}', 480, NULL),
  (3, 'reading', 'Motion Analysis & Dynamic Imaging', '{"slides":[{"heading":"Manipulasi sebagai alat diagnostik","body":"Keunggulan unik RTR adalah memutar/menggeser objek sambil mengamati citra live. Perubahan tampilan indikasi saat sudut berubah membantu memisahkan defect nyata dari artefak geometri/superposisi. Cacat planar (crack, lack of fusion) sangat sensitif sudut — bisa hilang/muncul tergantung orientasi berkas terhadap bidang cacat; cacat volumetrik (porosity, slag) relatif konsisten saat dirotasi. Manipulasi terkendali = karakterisasi lebih cepat daripada multiple exposure film."},{"heading":"Motion blur & batas kecepatan","body":"Pada objek bergerak, blur gerak ditentukan oleh kecepatan objek x waktu integrasi detektor (dan jumlah frame yang dirata-rata). Untuk menjaga ketajaman, blur gerak harus jauh lebih kecil dari unsharpness total (Ug + detektor). Strategi online: turunkan kecepatan jalur di zona kritis, sinkronkan trigger akuisisi dengan posisi objek, atau gunakan pulsed exposure (snapshot pendek) untuk ''membekukan'' gerak — analog shutter cepat pada fotografi."},{"heading":"Motion detection otomatis","body":"Sistem online modern memakai analisis gerak/visi mesin: frame-differencing dan thresholding mendeteksi area yang berubah antar frame untuk memicu alarm atau menandai region of interest. Ini mempercepat 100% inspection volume tinggi. Namun ADR (Automatic Defect Recognition) bersifat alat bantu — Level II tetap bertanggung jawab atas keputusan accept/reject akhir, kalibrasi threshold, dan validasi terhadap reference standard."},{"heading":"Dynamic range & windowing","body":"Detektor digital 12-16 bit memberi 4.096-65.536 gray level, jauh melampaui ~256 level yang bisa dibedakan mata pada satu tampilan. Karena itu windowing (atur window width/level/brightness-contrast) digunakan saat live untuk menyorot rentang ketebalan tertentu tanpa re-exposure — ekuivalen ''multiple film density'' dalam satu akuisisi. Dynamic range lebar inilah yang membuat RTR digital unggul pada komponen dengan variasi ketebalan besar."}]}', 460, NULL),
  (4, 'reading', 'Aplikasi, QC & Code RTR', '{"slides":[{"heading":"Aplikasi industri tipikal","body":"RTR online: las pipa (ERW/spiral) pada laju produksi, casting otomotif (roda, blok mesin) untuk porosity/shrinkage, inspeksi ban dan komponen aerospace, security screening. RTR offline: pemeriksaan weld pressure equipment, valve casting, electronics/PCB (BGA voids). Pilih RTR ketika throughput, akses berulang, dan manipulasi dinamis lebih bernilai daripada resolusi maksimum film butir-halus (ultra-fine grain)."},{"heading":"Sumber radiasi untuk RTR","body":"RTR umumnya memakai X-ray tube karena output dapat distabilkan/dimodulasi dan dimatikan (keselamatan + konsistensi dosis per frame). Gamma jarang untuk online karena tak bisa di-shutter cepat dan luruh seiring waktu: Ir-192 t-1/2 ~74 hari (~0,3-0,6 MeV rerata), Se-75 t-1/2 ~120 hari (baja tipis, ~0,2 MeV), Co-60 t-1/2 ~5,27 tahun (penetrasi tinggi, 1,17 & 1,33 MeV). Untuk X-ray, kV mengatur penetrasi/kontras, mA mengatur dosis (foton/frame) yang langsung memengaruhi SNR dan kebutuhan averaging."},{"heading":"QC sistem RTR digital","body":"QC kuantitatif rutin: SNR/CNR, basic spatial resolution (SRb via duplex wire IQI), dan untuk image intensifier — cek distorsi geometri serta veiling glare. Bad-pixel map dan kalibrasi flat-field (offset/gain) WAJIB pada flat-panel DR untuk menghilangkan fixed-pattern noise dan kolom mati. Verifikasi IQI 2-2T pada parameter produksi aktual (kV, mA, fps, jumlah averaging). Dokumentasikan semua parameter dalam written technique."},{"heading":"Code & acceptance","body":"ASME V Article 2 mengatur RT termasuk lampiran sistem digital/real-time (penempatan IQI per T-276, sensitivitas, demonstrasi sistem). ISO 17636-2 khusus teknik digital (kelas SRb & SNR minimum), sedangkan 17636-1 untuk film. AWS D1.1 Clause 8 dan API 1104 mendefinisikan acceptance las struktural/pipeline. Prinsip Level II: RTR harus didemonstrasikan setara/lebih baik dari film dalam mendeteksi IQI esensial sebelum dipakai untuk acceptance — ALARA & batas dosis okupasi 20 mSv/tahun (rerata, ICRP) tetap berlaku."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Real-time Imaging', '{"description":"8 soal: prinsip & geometri RTR, frame averaging, motion analysis/dynamic imaging, dan QC/code real-time radiography.","questionCount":8,"passingScore":75}', 680, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 4
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 4 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada frame averaging untuk objek yang diam, bagaimana rasio sinyal-terhadap-noise (SNR) meningkat ketika N frame dirata-ratakan?',
   '["SNR meningkat linier sebesar N","SNR meningkat sebesar akar-N (akar dari N)","SNR meningkat sebesar N kuadrat","SNR tidak terpengaruh oleh jumlah frame"]', 1,
   'Random (quantum) noise berkurang sebesar akar-N saat N frame dijumlahkan, sementara sinyal tetap, sehingga SNR naik akar-N. Merata-ratakan 16 frame menaikkan SNR ~4x; 64 frame ~8x. Kenaikan ini hanya valid bila objek diam selama akuisisi.', 'Frame Averaging', 'medium'),
  ('Pada RTR, geometri tetap berlaku. Manakah pernyataan yang benar tentang ketajaman geometri Ug = F x OFD / SOD?',
   '["Memperbesar focal-spot (F) dan memperbesar OFD keduanya menurunkan Ug","Memperkecil focal-spot (F) dan meminimalkan OFD keduanya menurunkan Ug","Ug hanya bergantung pada tegangan tabung (kV), bukan geometri","Menambah SOD memperbesar Ug sehingga citra makin kabur"]', 1,
   'Ug = F x OFD / SOD. Ug mengecil bila F (ukuran focal-spot/sumber) kecil dan OFD (jarak objek-detektor) kecil; karena SOD berada di penyebut, menambah SOD justru menurunkan Ug. Pada RTR dipakai micro-focus tube (F kecil) dan OFD diminimalkan untuk menjaga ketajaman.', 'Prinsip RTR', 'medium'),
  ('Mengapa frame averaging dengan N besar bermasalah pada online (in-line) inspection objek yang bergerak?',
   '["Menurunkan dynamic range detektor menjadi 8-bit","Membuat hukum kuadrat terbalik tidak berlaku","Menimbulkan motion blur karena objek berpindah selama N frame diakuisisi","Meningkatkan ukuran focal-spot sehingga Ug membesar"]', 2,
   'Averaging valid hanya jika objek diam relatif terhadap detektor selama N frame. Pada objek bergerak, perpindahan antar frame menimbulkan motion blur. Solusinya: kurangi kecepatan jalur, gunakan recursive averaging berbobot, detektor DQE tinggi, atau pulsed exposure untuk membekukan gerak.', 'Frame Averaging', 'medium'),
  ('Seorang operator melihat citra RTR yang tampak sangat ''bersih'' di monitor setelah averaging berat. Apa cara yang benar untuk membuktikan teknik memenuhi sensitivitas yang disyaratkan?',
   '["Cukup menilai secara visual bahwa noise sudah hilang di layar","Memastikan brightness monitor diset maksimum","Menghitung jumlah gray level yang ditampilkan kamera","Memverifikasi keterbacaan IQI (mis. 2-2T wire/hole) pada parameter produksi aktual"]', 3,
   'Tampilan halus tidak menjamin compliance. Sensitivitas harus dibuktikan dengan IQI — wire-type (ASTM E747/ISO 19232) atau hole-type plaque (ASTM E1025, lubang 1T/2T/4T), target tipikal 2-2T — diuji pada parameter produksi aktual (kV, mA, fps, jumlah averaging), didukung SNR dan SRb kuantitatif.', 'QC & Code', 'medium'),
  ('Saat objek dirotasi secara live di RTR, indikasi tipe mana yang paling sensitif terhadap perubahan sudut berkas (bisa muncul/hilang)?',
   '["Porosity (cacat volumetrik bulat)","Cacat planar seperti crack dan lack of fusion","Slag inclusion volumetrik","Variasi ketebalan dinding yang merata"]', 1,
   'Cacat planar (crack, lack of fusion) sangat tergantung orientasi berkas terhadap bidang cacat — bisa hilang jika berkas tidak sejajar bidangnya dan muncul jelas saat sejajar. Cacat volumetrik (porosity, slag) tampak relatif konsisten saat dirotasi. Inilah nilai dynamic imaging untuk karakterisasi.', 'Motion Analysis', 'medium'),
  ('Pada recursive (running) averaging dengan rumus frame_tampil = alfa x frame_sekarang + (1 - alfa) x frame_sebelumnya, apa efek memilih nilai alfa yang sangat kecil?',
   '["Penghalusan noise kuat tetapi muncul lag/ghosting saat ada gerak","Responsif terhadap gerak tetapi citra sangat berisik","Menghapus distorsi geometri image intensifier","Meningkatkan resolusi spasial dasar (SRb) detektor"]', 0,
   'alfa kecil memberi bobot besar pada frame-frame lama, menghasilkan penghalusan noise kuat namun lag dan ghosting ketika objek bergerak. alfa besar lebih responsif terhadap gerak tetapi lebih berisik. Pilihan alfa adalah trade-off antara penekanan noise temporal dan ketajaman gerak.', 'Frame Averaging', 'hard'),
  ('Mengapa X-ray tube lebih disukai daripada sumber gamma untuk online real-time radiography?',
   '["Gamma menghasilkan resolusi spasial yang selalu lebih baik","X-ray tidak mematuhi hukum kuadrat terbalik sehingga dosis konstan","Outputnya dapat distabilkan/dimodulasi dan dimatikan (di-shutter), serta tidak meluruh seperti gamma","Gamma tidak dapat menembus baja sehingga tak berguna"]', 2,
   'X-ray tube dapat distabilkan, dimodulasi (kV/mA), dan dimatikan untuk keselamatan dan konsistensi dosis per frame. Sumber gamma tidak bisa di-shutter cepat dan terus meluruh (Ir-192 t-1/2 ~74 hari, Se-75 t-1/2 ~120 hari, Co-60 t-1/2 ~5,27 tahun), membuat dosis per frame tidak stabil untuk online.', 'Prinsip RTR', 'medium'),
  ('Pada flat-panel DR untuk RTR, prosedur QC mana yang WAJIB dilakukan untuk menghilangkan fixed-pattern noise dan piksel/kolom mati?',
   '["Menaikkan kV hingga maksimum untuk membakar noise","Kalibrasi flat-field (offset/gain) dan pembuatan bad-pixel map","Mengganti X-ray tube dengan sumber Co-60","Menambah OFD agar Ug meningkat dan noise tersamarkan"]', 1,
   'Flat-panel DR memerlukan kalibrasi flat-field (koreksi offset/gain) dan bad-pixel map untuk menghapus fixed-pattern noise serta menutup piksel/kolom mati. Tanpa ini, artefak tetap muncul dan dapat disalahartikan sebagai indikasi. Menaikkan kV atau OFD justru menurunkan kualitas citra.', 'QC & Code', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 4 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 5 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Dari exposure chart ke perhitungan kuantitatif', '{"slides":[{"heading":"Mengapa Level II harus hitung, bukan baca chart","body":"Level I cukup mengikuti exposure chart yang sudah dikalibrasi untuk material dan ketebalan baku. Level II harus mengembangkan teknik untuk ketebalan/material baru, mengoreksi peluruhan sumber, dan men-justify dosis. Itu menuntut kalkulasi kuantitatif: inverse-square law, peluruhan aktivitas (decay), dan exposure factor (Ci-menit untuk gamma, mA-menit untuk X-ray)."},{"heading":"Exposure factor — satuan kerja","body":"Exposure E dinyatakan sebagai produk: untuk gamma E = aktivitas x waktu (Ci-menit), untuk X-ray E = arus x waktu (mA-menit). Contoh gamma: E = 30 Ci x 4 menit = 120 Ci-menit pada SFD tertentu. Mengubah satu variabel (jarak, aktivitas, ketebalan, density target) menuntut perhitungan ulang, bukan sekadar menggeser pointer pada chart."},{"heading":"Inverse-square law sebagai fondasi","body":"Intensitas I berbanding terbalik dengan kuadrat jarak: I proporsional 1/d^2, sehingga I1 x d1^2 = I2 x d2^2. Untuk mempertahankan exposure yang sama saat jarak naik dari 600 mm ke 900 mm, waktu harus dikali (900/600)^2 = 2.25. Hukum yang sama juga menjadi inti perhitungan dosis pada penetapan batas area radiografi (radiation safety boundary)."},{"heading":"Density sebagai output yang dikontrol","body":"Target akhir kalkulasi adalah film density (atau gray level digital) dalam rentang code. ASME V single-film viewing: X-ray 1.8-4.0, gamma 2.0-4.0. Setiap perubahan exposure menggeser density mengikuti kurva karakteristik film (H&D curve); Level II memakai kurva ini untuk konversi density-ke-exposure yang bersifat logaritmik, bukan linear."}]}', 460, NULL),
  (2, 'reading', 'Kerma, dosis serap, dan dosis ekuivalen', '{"slides":[{"heading":"Kerma — energi yang ditransfer","body":"Kerma (Kinetic Energy Released per unit MAss) mengukur energi kinetik yang dilepas foton ke partikel bermuatan per satuan massa, satuan gray (Gy = J/kg). Air-kerma rate (laju kerma di udara) adalah besaran praktis untuk gamma source. Untuk Ir-192 konstanta air-kerma rate sekitar 0.11-0.13 microGy/jam per MBq pada 1 m (setara RHM sekitar 0.46-0.5 R/jam per Ci pada 1 m)."},{"heading":"Kerma vs dosis serap (absorbed dose)","body":"Absorbed dose D = energi yang benar-benar terserap per satuan massa (juga Gy). Pada kondisi charged-particle equilibrium dan energi RT yang umum, kerma di udara hampir sama dengan absorbed dose di udara. Perbedaan kecil muncul saat sebagian energi sekunder lolos sebagai bremsstrahlung; untuk Ir-192/Co-60 fraksi ini kecil sehingga K(udara) mendekati D(udara)."},{"heading":"Dosis ekuivalen dan satuan sievert","body":"Dosis ekuivalen H = D x wR (radiation weighting factor). Untuk foton X dan gamma wR = 1, jadi 1 Gy setara 1 Sv. Inilah besaran yang dipakai untuk batas pekerja radiasi. Batas dosis okupasi ICRP: 20 mSv/tahun rata-rata selama 5 tahun, dengan maksimum 50 mSv dalam satu tahun. Level II perlu mampu mengonversi laju kerma menjadi laju dosis untuk menetapkan stay time dan barrier."},{"heading":"Contoh hitung stay time","body":"Sumber Ir-192 50 Ci, laju dosis pendekatan = 0.5 R/jam per Ci pada 1 m, jadi 25 R/jam pada 1 m. Pada 5 m: 25 / 5^2 = 1 R/jam (kira-kira 10 mSv/jam). Jika dosis yang diizinkan per entri adalah 0.1 mSv, maka stay time aman = 0.1 mSv / 10 mSv per jam = 0.01 jam = 36 detik. Prinsip ALARA: utamakan tambah jarak atau gunakan collimator/shielding, bukan memperpanjang waktu pajanan."}]}', 480, NULL),
  (3, 'reading', 'Peluruhan sumber & koreksi exposure', '{"slides":[{"heading":"Hukum peluruhan radioaktif","body":"Aktivitas A(t) = A0 x e^(-lambda x t), dengan lambda = ln2 / t-setengah = 0.693 / t-setengah. Karena aktivitas turun, waktu pajanan harus dinaikkan agar exposure (Ci-menit) tetap. Half-life referensi: Ir-192 sekitar 74 hari, Co-60 sekitar 5.27 tahun, Se-75 sekitar 120 hari. Co-60 stabil sangat lama; Ir-192 butuh koreksi mingguan bahkan harian."},{"heading":"Decay factor praktis untuk Ir-192","body":"Karena t-setengah Ir-192 = 74 hari, dalam 30 hari faktor = e^(-0.693 x 30/74) = e^(-0.281) = 0.755. Sumber 100 Ci menjadi sekitar 75.5 Ci. Untuk density yang sama, waktu baru = waktu lama / 0.755 = waktu lama x 1.32. Tabel decay harian biasanya disediakan vendor, tetapi Level II wajib memverifikasinya dengan rumus."},{"heading":"Kombinasi peluruhan + inverse-square + ketebalan","body":"Untuk teknik baru, gabungkan tiga koreksi: (1) decay menentukan aktivitas aktual, (2) inverse-square menyesuaikan perubahan SFD, (3) ketebalan dihitung via HVL/TVL. Contoh: pindah dari 25 mm ke 38 mm baja dengan Ir-192 (TVL baja sekitar 13 mm), tambahan 13 mm = 1 TVL = exposure x10. Kalikan lagi dengan faktor decay 1.32 dan faktor jarak 2.25 bila SFD juga berubah."},{"heading":"HVL dan TVL — attenuation logaritmik","body":"HVL (half-value layer) menurunkan intensitas menjadi 50%, TVL (tenth-value layer) menjadi 10%, dengan TVL = HVL x 3.32. Setiap satu TVL baja menambah faktor 10 pada exposure. Untuk Co-60 (energi 1.17 & 1.33 MeV) TVL baja sekitar 22 mm sehingga Co-60 lebih efisien menembus baja tebal; untuk Ir-192 TVL baja sekitar 13 mm. Pemilihan sumber langsung memengaruhi exposure factor total."}]}', 500, NULL),
  (4, 'reading', 'Multi-source compositing & dose mapping area kerja', '{"slides":[{"heading":"Apa itu multi-source compositing","body":"Pada panorama atau inspeksi banyak joint, beberapa pajanan (atau beberapa sumber) dapat berkontribusi ke satu area. Laju dosis total di satu titik = penjumlahan kontribusi tiap sumber: D_total = jumlah dari D_i. Karena dosis bersifat aditif, tiap sumber dihitung sendiri via inverse-square lalu dijumlahkan untuk menetapkan boundary dan stay time."},{"heading":"Perhitungan dose mapping (radiation survey)","body":"Boundary high-radiation area sering ditetapkan pada 2 mR/jam (kira-kira 0.02 mSv/jam) atau sesuai regulasi lokal. Dari laju dosis sumber, jarak boundary dihitung: d = akar(I_1m / I_batas). Contoh 25 R/jam pada 1 m terhadap batas 2 mR/jam (= 0.002 R/jam): d = akar(25/0.002) = akar(12500) = sekitar 112 m tanpa shielding. Collimator atau shielding memperkecil radius ini drastis."},{"heading":"Compositing eksposur film panorama","body":"Pada panoramic exposure (sumber di tengah pipa, satu pajanan 360 derajat), satu pajanan mengekspos seluruh keliling sekaligus, efisien tetapi SFD = jari-jari pipa sehingga Ug bisa besar (Ug = F x OFD / SOD). Pada teknik double-wall double-image, exposure dihitung untuk dua dinding sehingga ketebalan efektif = 2x wall; perhitungan attenuation memakai total lintasan baja, bukan single wall."},{"heading":"Integrasi ke ALARA dan justifikasi teknik","body":"Setiap teknik baru harus lulus tiga uji Level II: density/IQI dalam rentang code, Ug di bawah batas code (Ug = F x OFD / SOD), dan dosis kolektif minimum. Compositing membantu menjadwalkan urutan pajanan agar overlap dosis pekerja ditekan. Dokumentasikan aktivitas, decay factor, SFD, waktu pajanan, dan hasil survey pada technique sheet."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Advanced Exposure Calculation', '{"description":"7 soal kuantitatif: kerma/dosis, inverse-square, peluruhan sumber, HVL/TVL, dan multi-source compositing.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 5
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 5 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Sumber Ir-192 memberikan laju dosis 25 R/jam pada jarak 1 m. Berapa laju dosis pada jarak 5 m (tanpa shielding)?',
   '["5 R/jam","0.2 R/jam","1 R/jam","12.5 R/jam"]', 2,
   'Inverse-square law: I proporsional 1/d^2, sehingga I1 x d1^2 = I2 x d2^2. Pada 5 m: 25 / 5^2 = 25 / 25 = 1 R/jam. Distraktor 5 R/jam keliru karena membagi linear (25/5), bukan kuadrat.', 'Inverse-Square Law', 'easy'),
  ('Aktivitas Ir-192 awal 100 Ci. Setelah 74 hari (kira-kira satu half-life), berapa aktivitasnya?',
   '["100 Ci","50 Ci","75 Ci","25 Ci"]', 1,
   'Setelah satu half-life (t-setengah Ir-192 sekitar 74 hari) aktivitas turun menjadi setengah: 100 Ci menjadi 50 Ci. Dari A = A0 x e^(-0.693 x t/t-setengah), saat t = t-setengah faktornya tepat 0.5.', 'Source Decay', 'easy'),
  ('Untuk foton X dan gamma, hubungan antara dosis serap (Gy) dan dosis ekuivalen (Sv) adalah:',
   '["1 Gy = 20 Sv karena wR = 20","1 Gy = 0.1 Sv","1 Gy = 1 Sv karena radiation weighting factor wR = 1","Tidak ada hubungan karena satuannya berbeda total"]', 2,
   'H = D x wR. Untuk foton X dan gamma wR = 1, sehingga 1 Gy absorbed dose setara 1 Sv dosis ekuivalen. wR = 20 hanya berlaku untuk partikel alfa, bukan foton.', 'Kerma & Dose', 'medium'),
  ('TVL (tenth-value layer) baja untuk Ir-192 sekitar 13 mm. Jika ketebalan baja bertambah 13 mm dari teknik dasar, exposure (Ci-menit) harus dikalikan berapa agar density tetap?',
   '["x2","x3.32","x10","x100"]', 2,
   'Satu TVL menurunkan intensitas menjadi 1/10. Untuk mempertahankan density yang sama saat menambah 1 TVL ketebalan, exposure harus dikali 10. Faktor 3.32 adalah rasio TVL/HVL, bukan faktor exposure.', 'Attenuation HVL/TVL', 'medium'),
  ('Pada dose mapping, kerma (kinetic energy released per unit mass) paling tepat didefinisikan sebagai:',
   '["Energi kinetik yang dilepas foton ke partikel bermuatan per satuan massa, satuan Gy","Energi total yang terserap material per satuan massa","Jumlah foton yang menembus film per detik","Dosis ekuivalen setelah dikali weighting factor"]', 0,
   'Kerma mengukur energi kinetik yang dilepaskan foton ke partikel bermuatan per satuan massa (Gy = J/kg). Pada charged-particle equilibrium kerma udara mendekati absorbed dose udara, tetapi definisinya adalah energi yang ditransfer, bukan energi yang terserap.', 'Kerma & Dose', 'medium'),
  ('Dua sumber gamma berkontribusi ke satu titik kerja: sumber A memberi 6 mSv/jam dan sumber B memberi 4 mSv/jam di titik tersebut. Berapa laju dosis total (compositing) di titik itu?',
   '["5 mSv/jam (rata-rata kedua sumber)","2.4 mSv/jam","10 mSv/jam karena dosis bersifat aditif","Tidak bisa dijumlahkan karena sumbernya berbeda"]', 2,
   'Dosis dari beberapa sumber bersifat aditif (skalar): D_total = jumlah D_i = 6 + 4 = 10 mSv/jam. Inilah dasar multi-source compositing untuk menetapkan boundary dan stay time. Merata-ratakan (5 mSv/jam) adalah kesalahan umum.', 'Multi-Source Compositing', 'medium'),
  ('Teknik dasar memakai waktu 4 menit pada SFD 600 mm. Untuk density yang sama pada SFD 900 mm (tanpa perubahan aktivitas/ketebalan), berapa waktu pajanan baru?',
   '["6 menit","12 menit","2.7 menit","9 menit"]', 3,
   'Inverse-square: waktu baru = 4 x (900/600)^2 = 4 x (1.5)^2 = 4 x 2.25 = 9 menit. Distraktor 6 menit (4 x 1.5) keliru karena menskalakan linear, bukan kuadrat; 2.7 menit keliru karena membalik arah rasio.', 'Inverse-Square Law', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 5 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 6 — Technique Development (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Kerangka Technique Development', '{"slides":[{"heading":"Apa itu technique development","body":"Technique development adalah proses menetapkan parameter eksposur lengkap sebelum shooting: pilihan sumber/energi, SOD/SFD, OFD, IQI, geometri (single/double wall), serta target densitas atau SNR. Level II bertanggung jawab menyusun teknik ini dan men-sign-off, bukan sekadar menjalankan teknik yang sudah ada (itu ruang lingkup Level I)."},{"heading":"Input wajib","body":"Sebelum mulai: material (steel/Al), rentang ketebalan dinding nominal + reinforcement las, geometri sambungan (butt, nozzle, pipa), akses dua sisi atau satu sisi, code acceptance (ASME V Article 2, AWS D1.1 Clause 8, API 1104, ISO 17636-1 untuk film / 17636-2 untuk digital), dan media (film vs digital DR/CR)."},{"heading":"Output technique sheet","body":"Hasil akhir berupa technique sheet/exposure chart yang mencantumkan: sumber & aktivitas (atau kVp/mA untuk X-ray film), SOD, OFD, waktu eksposur, tipe IQI + essential wire/hole, sensitivitas target ~2% (2-2T), serta rentang densitas (X-ray 1.8-4.0; gamma 2.0-4.0 per ASME V, single-film viewing) atau SNR untuk digital."},{"heading":"Mengapa rentang ketebalan penting","body":"Satu shot sering menutupi rentang ketebalan (mis. las dengan reinforcement + base metal). Rentang densitas yang dapat diterima membatasi rasio ketebalan maksimum per single exposure. ASME V (T-282) mengizinkan densitas pada area of interest bervariasi -15% sampai +30% relatif densitas di badan IQI, sehingga teknik harus dipilih agar seluruh rentang ketebalan jatuh dalam jendela densitas/SNR yang sah."}]}', 460, NULL),
  (2, 'reading', 'Seleksi Sumber & Energi vs Ketebalan', '{"slides":[{"heading":"Peta sumber gamma vs ketebalan baja","body":"Se-75 (t½≈120 hari, ~0.2 MeV): baja tipis ~5-25 mm, kontras tinggi. Ir-192 (t½≈74 hari, ~0.3-0.6 MeV rata-rata): baja ~12-65 mm, workhorse pipeline. Co-60 (t½≈5.27 tahun, 1.17 & 1.33 MeV): baja tebal ~40-200 mm, penetrasi tinggi tapi kontras rendah & unsharpness besar karena ukuran sumber relatif besar."},{"heading":"X-ray vs gamma","body":"X-ray (kVp variabel) memberi kontras lebih baik dan unsharpness kecil pada ketebalan rendah-menengah, ideal untuk akses bengkel/portable hingga ~300 kV. Gamma dipilih untuk akses sulit di lapangan, sumber kompak tanpa listrik, dan ketebalan besar. Energi naik → penetrasi naik tapi subject contrast turun."},{"heading":"Trade-off energi","body":"Energi rendah = kontras subjek tinggi (sensitivitas defect baik) tetapi penetrasi terbatas & waktu eksposur panjang. Energi tinggi = penetrasi besar & waktu pendek tetapi kontras turun dan scatter naik. Pilih energi serendah mungkin yang masih menembus ketebalan maksimum dalam densitas/SNR sah — prinsip ''lowest practical energy''."},{"heading":"Decay & aktivitas efektif","body":"Aktivitas sumber meluruh: A = A0 · (1/2)^(t/t½). Ir-192 turun ~50% tiap 74 hari, jadi waktu eksposur harus dihitung ulang berkala. Technique sheet harus mencantumkan aktivitas saat ini (Ci/Bq) dan tanggal, karena output (RHM) langsung mempengaruhi waktu eksposur dan source decay tracking adalah bagian QC."}]}', 500, NULL),
  (3, 'reading', 'Strategi IQI & Sensitivitas', '{"slides":[{"heading":"Tipe IQI","body":"Wire-type per ASTM E747 / ISO 19232 (set kawat A-D dengan diameter menurun). Hole-type/plaque per ASTM E1025 dengan lubang 1T/2T/4T pada plat ber-shim. API 1104 lazim memakai hole-type; ISO/Eropa lazim wire-type. Pilihan IQI mengikuti code yang mengatur pekerjaan."},{"heading":"Penempatan (T-276)","body":"IQI ditempatkan pada sisi sumber (source side) di atas material berketebalan paling representatif; bila tidak praktis, film side diperbolehkan dengan marker ''F'' dan sensitivitas lebih ketat. IQI diletakkan di tepi area of interest, tidak menutupi las, dengan shim agar ketebalan di bawah IQI ≈ ketebalan las + reinforcement."},{"heading":"Level sensitivitas 2-2T","body":"Sensitivitas standar ~2% (essential 2-2T): IQI ber-ketebalan 2% dari ketebalan benda dengan essential hole 2T (diameter = 2× tebal plaque) harus terlihat, atau essential wire setara ~2%. Hubungan relatif: 2-1T lebih ketat (~1.4%), 2-4T lebih longgar (~2.8%). Technique harus menjamin essential wire/hole terbaca pada radiograf akhir."},{"heading":"Memilih nomor IQI dari ketebalan","body":"Dari ketebalan area of interest, code memberi tabel essential hole/wire. Contoh ASME V: pada ketebalan tertentu, IQI dipilih sehingga 2T hole terlihat. Bila rentang ketebalan lebar dalam satu film, IQI dipilih untuk ketebalan tertipis (kondisi tersulit karena densitas cenderung tertinggi) sambil memastikan ketebalan tertebal tetap di atas densitas minimum."}]}', 480, NULL),
  (4, 'reading', 'Kontrol Unsharpness Geometrik (Ug)', '{"slides":[{"heading":"Rumus inti","body":"Ug = F × OFD / SOD, dengan F = ukuran focal-spot/sumber, OFD = jarak objek-ke-film/detektor, SOD = jarak sumber-ke-objek. Ug adalah kabur tepi geometris; makin kecil Ug, makin tajam indikasi. Sumber besar (Co-60) menghasilkan Ug besar sehingga butuh SOD lebih jauh untuk kompensasi."},{"heading":"Contoh perhitungan","body":"F = 3 mm, OFD = 10 mm, SOD = 600 mm → Ug = 3 × 10 / 600 = 0.05 mm. Bila SOD diperkecil ke 300 mm: Ug = 3 × 10 / 300 = 0.10 mm (dua kali lebih buruk). Menambah SOD menurunkan Ug secara linear, tetapi waktu eksposur naik secara kuadratik (hukum kuadrat terbalik, I ∝ 1/d²)."},{"heading":"Batas Ug menurut code","body":"ASME V Article 2 (T-274.2) membatasi Ug maksimum berdasarkan ketebalan: <50 mm → Ug ≤ 0.51 mm; 50-75 mm → ≤ 0.76 mm; 75-100 mm → ≤ 1.02 mm; >100 mm → ≤ 1.78 mm. Technique sheet harus membuktikan Ug aktual ≤ batas dengan menunjukkan F, OFD, dan SOD yang dipakai."},{"heading":"Trade-off SOD vs waktu vs Ug","body":"Menaikkan SOD: Ug turun, ketajaman naik, TAPI intensitas turun (I ∝ 1/d²) → waktu eksposur naik ~(SOD baru/SOD lama)². Menurunkan OFD (film menempel objek) selalu menurunkan Ug tanpa penalti waktu, jadi minimalkan OFD dulu sebelum menambah SOD. Untuk DR/CR, SRb (basic spatial resolution) menggantikan peran Ug dalam menilai ketajaman digital."}]}', 500, NULL),
  (5, 'reading', 'Menyusun & Memvalidasi Technique Sheet', '{"slides":[{"heading":"Langkah penyusunan","body":"1) Tentukan ketebalan penetrasi total (dinding + reinforcement, single/double wall). 2) Pilih sumber/energi terendah yang menembus dengan densitas sah. 3) Set OFD minimum, hitung SOD untuk memenuhi batas Ug. 4) Hitung waktu eksposur dari aktivitas/output & SOD. 5) Pilih IQI + essential wire/hole ~2%. 6) Validasi densitas/SNR pada shot percobaan."},{"heading":"Single vs double wall","body":"Pipa diameter kecil sering pakai double-wall single-image (DWSI) atau double-wall double-image (DWDI/elliptical). Ketebalan penetrasi = jumlah dinding yang dilewati sinar, bukan hanya satu dinding — ini mengubah pilihan sumber/energi dan waktu. Geometri elips mengontrol superimposisi las pada radiograf."},{"heading":"Validasi & acceptance","body":"Shot valid bila: densitas area of interest dalam rentang code (X-ray 1.8-4.0; gamma 2.0-4.0), essential IQI terbaca, Ug ≤ batas, tidak ada artefak/scatter berlebih (cek dengan huruf timbal ''B'' di belakang film/kaset), dan identifikasi/penetrameter marker lengkap. Technique sheet yang lolos divalidasi & ditandatangani Level II menjadi acuan reproducible."},{"heading":"Adaptasi untuk digital","body":"Untuk DR/CR, technique sheet menambah: detector class, SRb target, SNR/CNR minimum, gray-level/bit depth (12-16 bit), dan parameter scanning (CR) atau frame averaging (DR). Densitas film diganti normalized SNR; IQI tetap wajib, plus duplex wire IQI untuk verifikasi SRb. Prinsip Ug → ketajaman tetap berlaku via geometri sumber-detektor."}]}', 460, NULL),
  (6, 'quiz', 'Mini-quiz — Technique Development', '{"description":"7 soal technique development: seleksi sumber/energi vs ketebalan, strategi IQI, dan kontrol unsharpness geometrik (Ug).","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 6
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 6 mini-quiz (7 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Sebuah radiograf memakai F (ukuran sumber) = 3 mm, OFD = 10 mm, dan SOD = 600 mm. Berapa unsharpness geometrik Ug?',
   '["0.05 mm","0.10 mm","0.50 mm","1.80 mm"]', 0,
   'Ug = F × OFD / SOD = 3 × 10 / 600 = 0.05 mm. Memperbesar SOD menurunkan Ug secara linear; memperkecil OFD juga menurunkan Ug.', 'Kontrol Unsharpness', 'medium'),
  ('Untuk inspeksi sambungan las baja dengan ketebalan penetrasi sekitar 120 mm di lapangan tanpa sumber listrik, sumber gamma mana yang paling tepat?',
   '["Se-75, karena energi rendah memberi kontras tinggi","Ir-192, karena merupakan workhorse pipeline","X-ray portable 160 kVp","Co-60, karena energi 1.17 & 1.33 MeV memberi penetrasi untuk baja tebal"]', 3,
   'Co-60 (1.17 & 1.33 MeV, t½≈5.27 tahun) dipilih untuk baja tebal ~40-200 mm. Se-75 (~0.2 MeV) untuk baja tipis dan Ir-192 (~12-65 mm) tidak menembus 120 mm secara memadai, dan X-ray 160 kVp jauh dari cukup serta butuh listrik.', 'Seleksi Sumber & Energi', 'medium'),
  ('Jika SOD diperkecil dari 600 mm menjadi 300 mm sementara F dan OFD tetap, apa yang terjadi pada Ug dan waktu eksposur?',
   '["Ug menjadi setengah, waktu eksposur naik ~2x","Ug menjadi dua kali, waktu eksposur turun ~4x","Ug tetap, waktu eksposur turun ~2x","Ug menjadi dua kali, waktu eksposur naik ~4x"]', 1,
   'Ug = F×OFD/SOD, jadi memperkecil SOD menjadi setengah menggandakan Ug (memburuk: 0.05→0.10 mm). Intensitas I ∝ 1/d², jadi mendekat ke setengah jarak menaikkan intensitas ~4x sehingga waktu eksposur turun ~4x.', 'Kontrol Unsharpness', 'hard'),
  ('Sensitivitas IQI standar ~2% sering dinyatakan sebagai ''essential 2-2T''. Apa maknanya pada hole-type IQI?',
   '["Densitas film harus antara 2.0 dan 2T","Plaque setebal ~2% dari ketebalan benda, dengan lubang berdiameter 2× tebal plaque (2T) yang harus terlihat","Dua kawat dengan diameter 2 mm harus terlihat","SOD harus 2× ketebalan objek"]', 1,
   'Pada hole-type per ASTM E1025, IQI essential 2-2T berarti plaque berketebalan ~2% dari ketebalan benda, dengan lubang 2T (diameter = 2× tebal plaque) yang harus terbaca pada radiograf, setara sensitivitas ~2%.', 'Strategi IQI', 'medium'),
  ('Mana langkah paling tepat untuk menurunkan Ug tanpa menambah waktu eksposur?',
   '["Menaikkan SOD","Menaikkan energi sumber","Meminimalkan OFD (menempelkan film/detektor ke objek)","Memperbesar ukuran focal-spot"]', 2,
   'Ug = F×OFD/SOD. Menurunkan OFD menurunkan Ug secara langsung tanpa mengubah intensitas, sehingga tidak ada penalti waktu. Menaikkan SOD juga menurunkan Ug tetapi menaikkan waktu eksposur (I ∝ 1/d²); memperbesar F dan menaikkan energi tidak membantu ketajaman.', 'Kontrol Unsharpness', 'medium'),
  ('Ir-192 memiliki t½≈74 hari. Mengapa technique sheet harus mencantumkan aktivitas saat ini beserta tanggalnya?',
   '["Karena energi foton Ir-192 berubah seiring waktu","Karena ukuran focal-spot mengecil saat decay","Karena aktivitas meluruh A = A0·(1/2)^(t/t½) sehingga waktu eksposur harus dihitung ulang berkala","Karena densitas film naik otomatis saat sumber meluruh"]', 2,
   'Aktivitas (output) Ir-192 turun ~50% tiap 74 hari mengikuti A = A0·(1/2)^(t/t½). Output menentukan waktu eksposur, jadi aktivitas terkini + tanggal wajib dicatat untuk source decay tracking dan perhitungan eksposur yang benar. Energi foton dan ukuran sumber tidak berubah akibat decay.', 'Seleksi Sumber & Energi', 'hard'),
  ('Pada satu single exposure yang menutupi rentang ketebalan lebar (las + base metal), bagaimana strategi memilih lokasi/nomor IQI agar seluruh area sah?',
   '["Pilih IQI untuk ketebalan tertipis (densitas cenderung tertinggi) sambil memastikan area tertebal tetap di atas densitas minimum","Pilih IQI untuk ketebalan tertebal saja dan abaikan area tipis","Tempatkan IQI di tengah las tanpa shim","Gunakan IQI film-side tanpa marker untuk semua kasus"]', 0,
   'Rentang ketebalan dibatasi jendela densitas code (-15% s.d. +30% relatif IQI). IQI dipilih untuk ketebalan representatif tersulit dan ditempatkan agar essential wire/hole terbaca, sambil memastikan area tertebal tetap di atas densitas minimum (X-ray 1.8-4.0; gamma 2.0-4.0). IQI di atas las tanpa shim dan film-side tanpa marker tidak sah.', 'Strategi IQI', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 6 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


