-- RT-L2 Module 7 — Image Quality Optimization (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi kualitas citra RT — kontras & definisi', '{"slides":[{"heading":"Dua pilar kualitas citra","body":"Radiographic sensitivity ditentukan oleh dua faktor independen: (1) kontras = beda densitas antara defect dan latar; (2) definisi (ketajaman/unsharpness). Optimasi Level II = menyeimbangkan keduanya, bukan hanya mengejar densitas. IQI 2-2T (≈2% sensitivity) hanya terbaca jika kontras DAN definisi cukup."},{"heading":"Subject contrast vs film contrast","body":"Subject contrast = perbedaan transmisi radiasi akibat beda tebal/densitas benda; meningkat dengan energi RENDAH (kVp turun, absorpsi diferensial naik). Film contrast = kemiringan kurva karakteristik (gamma/gradien) film; fine-grain film (mis. Class I/II) punya gamma tinggi tetapi speed rendah. Total contrast ≈ subject contrast x film contrast."},{"heading":"Energi vs latitude — trade-off inti","body":"kVp rendah -> kontras tinggi tetapi latitude (rentang tebal yang terekspos baik) sempit & waktu ekspos panjang. kVp tinggi -> kontras turun, latitude lebar, scatter naik. Untuk lasan profil tebal-tipis dipakai kVp lebih tinggi agar densitas tetap 1.8-4.0 (X-ray) di seluruh area of interest, lalu kompensasi kontras dengan film fine-grain."},{"heading":"Target densitas & variasi yang diizinkan","body":"ASME V Art. 2: densitas film X-ray 1.8-4.0, gamma 2.0-4.0 melalui area of interest, diukur di badan IQI. Variasi densitas yang diizinkan melalui area: -15% sampai +30% relatif terhadap densitas di badan IQI. Jika di luar rentang -> sesuaikan ekspos/diaphragm atau gunakan teknik multi-film (kombinasi film cepat + lambat dalam satu kaset)."}]}', 460, NULL),
  (2, 'reading', 'Intensifying & filter — mengendalikan radiasi yang sampai ke film', '{"slides":[{"heading":"Lead intensifying screen","body":"Lembar Pb (0.005-0.010 in / 0.13-0.25 mm) di depan & belakang film. Fungsi: (1) intensifikasi via fotoelektron sekunder -> memperpendek ekspos sekitar 2-4x untuk gamma/HV X-ray; (2) menyerap scatter berenergi rendah -> menaikkan kontras & definisi. Front screen biasanya lebih tipis dari back screen. Kontak rapat WAJIB; gap menyebabkan blur (screen unsharpness)."},{"heading":"Fluorescent vs fluorometallic","body":"Fluorescent (salt) screen memberi intensifikasi sangat besar (faktor 10-100x) sehingga ekspos sangat pendek, TETAPI graininess tinggi & definisi buruk — umumnya DILARANG untuk RT kode (ASME V) kecuali diizinkan eksplisit. Fluorometallic (Pb + fosfor) kompromi untuk material tebal. Level II harus tahu kapan screen menurunkan sensitivity di bawah ambang IQI."},{"heading":"Filter di sumber (beam hardening)","body":"Filter logam (Cu/Pb tipis) di port tabung X-ray menyerap komponen energi rendah dari spektrum -> mengeraskan berkas, menurunkan scatter, meratakan densitas pada benda dengan variasi tebal besar. Trade-off: kontras inheren sedikit turun & ekspos naik. Untuk Ir-192/Co-60 (gamma diskret) filtering sumber kurang relevan; fokus pindah ke kolimasi & masking."},{"heading":"Scatter control — masking & blocking","body":"Back-scatter diuji dengan huruf ''B'' timbal di belakang kaset: jika ''B'' muncul GELAP (densitas lebih tinggi) pada film -> back-scatter berlebih, citra ditolak. Mitigasi: lead back screen lebih tebal, masking dengan lead shot/barium putty di sekeliling part, diaphragm/kolimator membatasi berkas hanya ke area of interest."}]}', 480, NULL),
  (3, 'reading', 'Unsharpness total — geometrik, film, gerak & SRb digital', '{"slides":[{"heading":"Geometric unsharpness (Ug)","body":"Ug = F x OFD / SOD. F = ukuran focal-spot/sumber, SOD = source-to-object, OFD = object-to-film. Contoh: F=3 mm, OFD=25 mm, SOD=600 mm -> Ug = 3 x 25 / 600 = 0.125 mm. Cara turunkan: perbesar SOD (ingat I prop 1/d^2, ekspos naik kuadratik), tempelkan film serapat mungkin (OFD kecil), pilih sumber dengan F kecil (mis. Se-75 atau X-ray microfocus)."},{"heading":"Batas Ug per kode","body":"ASME V Art. 2 (T-274.2) membatasi Ug menurut tebal material: <=0.020 in (0.51 mm) untuk t<2 in; <=0.030 in untuk 2-3 in; <=0.040 in untuk 3-4 in; <=0.070 in untuk t>4 in. Level II menghitung Ug saat menetapkan SOD minimum dalam technique sheet, bukan sekadar mengikuti tabel."},{"heading":"Inherent (film) unsharpness & gerak","body":"Inherent unsharpness Uf berasal dari hamburan elektron sekunder dalam emulsi/intersep — naik dengan energi (≈0.05 mm pada ~100 kV, bisa >0.3 mm pada Co-60). Total unsharpness sering didekati U_total = (Ug^n + Uf^n)^(1/n), n≈2-3. Motion unsharpness muncul jika sumber/part bergerak saat ekspos — kritis pada real-time imaging; mitigasi dengan frame averaging atau ekspos terhenti."},{"heading":"Definisi pada sistem digital — SRb","body":"Pada CR/DR, ketajaman diukur sebagai basic spatial resolution SRb (µm) memakai duplex-wire IQI ASTM E2002 (SRb ≈ 1/2 jarak pasangan kawat pertama yang tak lagi terpisah). SRb baik (mis. 80-160 µm) sebanding resolusi film. Metrik tambahan: SNR/SNRnorm, CNR, DQE, dynamic range, kedalaman bit 12-16. ISO 17636-2 kelas A/B menetapkan SRb maksimum & SNRnorm minimum per ketebalan."}]}', 500, NULL),
  (4, 'reading', 'Processing parameters — kamar gelap film & pipeline digital', '{"slides":[{"heading":"Film processing — variabel terkontrol","body":"Time-temperature development standar: developer ~20°C (68°F), ~5 menit manual; automatic processor ~90 s pada suhu lebih tinggi. Suhu/waktu berlebih -> fog naik & kontras turun; kurang -> densitas rendah, IQI tak terbaca. Stop bath/fixer/wash harus konsisten. Kontrol fog dengan strip kendali; base+fog film bagus <0.20-0.30 densitas."},{"heading":"Artefak processing yang menyamar sebagai defect","body":"Level II wajib bedakan artefak dari indikasi nyata: water mark, streaking (agitasi buruk), pressure/crescent mark (film terlipat), static marks, drying mark. Ciri pembeda: artefak sering melewati batas geometri benda atau tak konsisten dengan posisi lasan. Bila ragu -> ulang ekspos, jangan tolak part atas dasar artefak."},{"heading":"CR scanning & DR acquisition","body":"CR: imaging plate (PSP) dipindai laser; parameter kritis = laser spot size, kecepatan scan, gain PMT, dan SAMPLING/pixel pitch (harus <= 1/2 SRb yang dituju, kriteria Nyquist). Eraser harus bersih agar tak ada ghosting. DR: integration time, frame averaging untuk naikkan SNR (SNR prop akar N frame), flat-field/offset/gain calibration & bad-pixel map WAJIB rutin."},{"heading":"Post-processing — diizinkan vs dilarang","body":"Diizinkan: windowing (brightness/contrast/level), zoom, kalibrasi pengukuran. Filter enhancement (sharpening/edge, smoothing/noise reduction) DIBATASI — ASME V & ISO 17636-2 mengharuskan filter terkualifikasi & terdokumentasi dalam prosedur karena dapat menciptakan/menghapus indikasi. Citra mentah (raw, 16-bit) harus diarsipkan utuh; hanya copy yang diproses. Verifikasi akhir tetap pakai SRb (duplex-wire) & IQI plaque/wire dalam citra."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Image Quality Optimization', '{"description":"7 soal optimasi kualitas citra RT Level II: kontras vs definisi, screen & filter, unsharpness (Ug & SRb), serta processing parameters.","questionCount":7,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 7
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 7 mini-quiz (7 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Radiographic sensitivity ditentukan oleh dua faktor utama yang independen. Faktor tersebut adalah:',
   '["Kontras dan definisi (ketajaman)","Densitas dan fog","kVp dan mA","SOD dan OFD"]', 0,
   'Sensitivity = kemampuan mendeteksi defect, ditentukan oleh kontras (beda densitas defect vs latar) DAN definisi/ketajaman (unsharpness). Keduanya independen; optimasi Level II menyeimbangkan keduanya. Densitas, kVp/mA, dan SOD/OFD adalah parameter yang mempengaruhi kontras/definisi, bukan dua pilar sensitivity itu sendiri.', 'Konsep Kualitas Citra', 'easy'),
  ('Sebuah teknik memakai sumber dengan ukuran efektif F = 3 mm, OFD = 25 mm, dan SOD = 600 mm. Berapa unsharpness geometrik (Ug)?',
   '["0.5 mm","1.25 mm","0.125 mm","0.072 mm"]', 2,
   'Ug = F x OFD / SOD = 3 x 25 / 600 = 75/600 = 0.125 mm. Untuk menurunkan Ug: perbesar SOD (tetapi ekspos naik kuadratik karena I prop 1/d^2), kecilkan OFD, atau pakai sumber dengan F lebih kecil. Distraktor 0.072 mm muncul bila keliru memakai SFD/penyebut berbeda; 0.5 dan 1.25 mm salah faktor.', 'Geometric Unsharpness', 'medium'),
  ('Mengapa fluorescent (salt) intensifying screen umumnya DILARANG untuk RT sesuai kode (mis. ASME V) kecuali diizinkan eksplisit, meski memberi intensifikasi sangat besar?',
   '["Karena meningkatkan waktu ekspos secara berlebihan","Karena menghasilkan graininess tinggi dan definisi buruk sehingga menurunkan sensitivity di bawah ambang IQI","Karena menyerap seluruh radiasi hambur sehingga kontras hilang total","Karena hanya bekerja pada sumber gamma, tidak pada X-ray"]', 1,
   'Fluorescent screen mengintensifkan 10-100x (ekspos sangat pendek), tetapi cahaya tampak yang dipancarkan menyebar dan butirannya kasar -> definisi buruk dan graininess tinggi, sehingga sensitivity turun dan IQI bisa gagal terbaca. Justru MEMPERPENDEK (bukan memperpanjang) ekspos, tidak menghapus seluruh kontras, dan tidak terbatas pada gamma.', 'Intensifying Screen', 'medium'),
  ('Pada radiografi material dengan variasi tebal yang besar, menaikkan kVp (energi) dan menambah filter di sumber bertujuan untuk:',
   '["Menaikkan subject contrast secara maksimum","Menurunkan latitude agar fokus pada satu ketebalan saja","Menghilangkan kebutuhan IQI","Menambah latitude dan meratakan densitas sehingga seluruh area of interest tetap dalam rentang densitas yang diizinkan"]', 3,
   'kVp tinggi + beam hardening (filter) memperlebar latitude dan meratakan densitas pada benda dengan variasi tebal, sehingga densitas di seluruh area of interest tetap dalam batas (X-ray 1.8-4.0). Trade-off-nya kontras inheren sedikit turun, jadi sering dikompensasi dengan film fine-grain. kVp tinggi justru MENURUNKAN subject contrast, dan IQI tetap wajib.', 'Filter & Energi', 'hard'),
  ('Pada sistem digital (CR/DR), basic spatial resolution (SRb) yang menyatakan ketajaman/definisi citra diukur menggunakan:',
   '["Duplex-wire IQI sesuai ASTM E2002","Hole-type (plaque) IQI sesuai ASTM E1025","Wire IQI sesuai ASTM E747","Lead letter ''B'' di belakang kaset"]', 0,
   'SRb (µm) diukur dengan duplex-wire IQI ASTM E2002; SRb kira-kira setengah jarak pasangan kawat pertama yang tidak lagi terpisah. Plaque (E1025) dan wire (E747) IQI mengukur kontras/sensitivity, bukan resolusi spasial. Lead letter ''B'' untuk deteksi back-scatter.', 'Digital Image Quality', 'medium'),
  ('Untuk material dengan tebal kurang dari 2 in (≈51 mm), ASME V Article 2 (T-274.2) membatasi unsharpness geometrik maksimum sebesar:',
   '["0.002 in (0.05 mm)","0.040 in (1.0 mm)","0.020 in (0.51 mm)","0.070 in (1.8 mm)"]', 2,
   'ASME V T-274.2: Ug maksimum 0.020 in untuk t<2 in; 0.030 in untuk 2-3 in; 0.040 in untuk 3-4 in; 0.070 in untuk t>4 in. Batas naik seiring ketebalan. Level II memakai batas ini untuk menghitung SOD minimum di technique sheet. 0.040 in dan 0.070 in adalah batas untuk material lebih tebal; 0.002 in terlalu ketat.', 'Kode — Batas Unsharpness', 'hard'),
  ('Selama review citra DR, seorang Level II ingin menaikkan SNR untuk membaca area dengan kontras rendah. Tindakan yang DIIZINKAN/terkualifikasi tanpa risiko menciptakan atau menghapus indikasi adalah:',
   '["Menerapkan filter edge-sharpening agresif pada citra final","Frame averaging (rata-rata banyak frame) saat akuisisi dan windowing brightness/contrast saat review","Smoothing/noise-reduction kuat lalu menyimpannya sebagai citra utama","Menghapus citra mentah (raw) dan hanya menyimpan versi terproses"]', 1,
   'Frame averaging menaikkan SNR (prop akar N frame) tanpa memanipulasi struktur citra, dan windowing (brightness/contrast/level) diizinkan. Filter enhancement seperti sharpening/smoothing dibatasi dan harus terkualifikasi & terdokumentasi karena dapat menciptakan atau menghapus indikasi. Citra mentah 16-bit WAJIB diarsipkan utuh; hanya copy yang boleh diproses.', 'Processing & Post-processing', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 7 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 8 — Defect Sizing & Characterization (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Prinsip Sizing & Magnifikasi Geometrik', '{"slides":[{"heading":"Dua tugas sizing RT","body":"Sizing = mengukur dimensi diskontinuitas dari image; characterization = mengklasifikasi jenis (porosity, slag, crack, LOF, LOP). RT secara inheren adalah proyeksi 2D dari objek 3D: panjang (length) dalam bidang film terukur dengan baik, tetapi tinggi/through-wall (kedalaman ke arah berkas) terproyeksi tumpang-tindih sehingga sulit. Level II harus paham batas keandalan tiap dimensi sebelum menulis angka di laporan."},{"heading":"Magnifikasi geometrik M","body":"Setiap citra RT diperbesar karena berkas divergen dari sumber. Faktor magnifikasi M = SFD/SOD = (SOD+OFD)/SOD, dengan SFD = source-to-film distance, SOD = source-to-object distance, OFD = object-to-film distance. Contoh: SOD=600 mm, OFD=40 mm (tebal benda + gap), maka SFD=640 mm dan M=640/600=1.067. Indikasi yang terukur 12.8 mm pada film -> ukuran nyata = 12.8/1.067 = 12.0 mm."},{"heading":"Koreksi panjang & kalibrasi skala","body":"Panjang nyata = panjang terukur di film / M. Cara praktis di lapangan: letakkan penanda timbal (lead marker) atau wire IQI dengan jarak yang diketahui pada permukaan benda (sisi yang sama dengan flaw), lalu kalibrasi skala langsung dari jarak penanda yang muncul di image -- ini otomatis mengompensasi M tanpa menghitung, asalkan penanda berada pada bidang yang sama dengan flaw. Pada DR/CR, skala dikalibrasi terhadap object pixel size, bukan detector pixel size, agar magnifikasi ikut terkoreksi."},{"heading":"Mengapa OFD harus kecil","body":"Magnifikasi M dan unsharpness geometrik Ug = F x OFD / SOD keduanya naik bila OFD besar (F = ukuran fokal-spot/sumber). Karena itu film/detektor selalu serapat mungkin ke benda. Pada konfigurasi double-wall di mana OFD tak bisa nol (dinding jauh menempel film, dinding dekat jauh dari film), dua dinding punya M berbeda -- fakta ini menjadi dasar teknik proyeksi paralaks untuk estimasi kedalaman."}]}', 460, NULL),
  (2, 'reading', 'Keterbatasan RT untuk Tinggi & Through-Wall', '{"slides":[{"heading":"Kelemahan utama RT","body":"RT unggul untuk volumetrik (porosity, slag, void) dan panjang planar, tetapi LEMAH untuk tinggi/kedalaman through-wall. Crack atau lack-of-fusion yang bidangnya tegak lurus berkas (sejajar film) hampir tak menghasilkan perubahan absorpsi (tidak ada selisih path-length) sehingga bisa terlewat sepenuhnya. Inilah alasan UT (terutama TOFD/PAUT) menjadi pilihan utama untuk through-wall sizing pada engineering critical assessment (ECA)."},{"heading":"Orientasi menentukan deteksi","body":"RT mendeteksi diskontinuitas planar hanya bila bidangnya cukup paralel dengan berkas (selisih jejak radiasi memberi kontras). Aturan praktis: planar flaw umumnya harus berada dalam ~ +/-7 derajat hingga ~20 derajat terhadap arah berkas, tergantung kontras/ketebalan/sensitivitas. Akibatnya RT bisa memberi panjang yang andal tapi tetap gagal memberi tinggi -- densitas indikasi hanya menyatakan SELISIH ketebalan material yang hilang sepanjang jejak berkas, bukan dimensi vertikal flaw secara langsung."},{"heading":"Densitas sebagai proksi kedalaman","body":"Hubungan densitas-ketebalan: perubahan densitas naik saat material yang dilalui berkas berkurang (lebih banyak material hilang -> lebih gelap), mengikuti hukum atenuasi I = I0 e^(-mu x). Selisih densitas antara indikasi dan logam dasar di sekitarnya dapat dikonversi menjadi perkiraan kehilangan material (depth/penetration loss) menggunakan kurva kalibrasi densitas-vs-ketebalan untuk material, energi, dan setup spesifik. Ini metode densitometri komparatif -- memberi estimasi, bukan pengukuran absolut."},{"heading":"Batas resolusi & ekspektasi realistis","body":"Untuk RT film konvensional, perubahan ketebalan < ~2% sering tak terdeteksi (ekuivalen sensitivitas IQI 2-2T menurut ASME V Article 2). Karena itu RT tidak dilaporkan sebagai sumber tinggi flaw untuk ECA/fitness-for-service kecuali didukung densitometri terkalibrasi atau teknik double-wall paralaks. Level II yang jujur menulis ''height not reliably sized by RT -- refer to UT'' bila memang demikian, alih-alih menebak angka."}]}', 480, NULL),
  (3, 'reading', 'Double-Wall, Paralaks & Densitometri Komparatif', '{"slides":[{"heading":"Estimasi kedalaman via paralaks (double exposure)","body":"Teknik stereo/paralaks: ambil dua eksposur dari posisi sumber yang digeser sejauh jarak diketahui (shift S), film tetap. Pergeseran bayangan indikasi (parallax shift, d) antara kedua image memberi posisi flaw dari film. Dengan geometri segitiga sebangun, jarak flaw-ke-film t = (d x SFD)/(S + d). Karena objek yang lebih dekat film bergeser lebih sedikit daripada yang lebih jauh, beda pergeseran menempatkan flaw dalam arah ketebalan."},{"heading":"Lead marker / shim untuk skala kedalaman","body":"Letakkan lead marker pada permukaan source-side dan film-side (atau shim ketebalan diketahui di sisi berlawanan). Marker dengan elevasi diketahui memberi kalibrasi pergeseran-vs-kedalaman langsung di image, mengubah paralaks kualitatif menjadi estimasi kuantitatif. Akurasi tipikal teknik paralaks RT untuk kedalaman hanya ~ +/-0.5 sampai 1 mm pada kondisi baik -- masih lebih kasar daripada UT/TOFD."},{"heading":"Densitometri komparatif terkalibrasi","body":"Langkah: (1) ukur densitas logam dasar D_base dengan densitometer; (2) ukur densitas indikasi D_flaw; (3) buat step-wedge dari material sama, radiografi pada setup identik untuk membuat kurva D-vs-thickness; (4) baca selisih ketebalan dari kurva. Estimasi loss = delta-x. Cocok untuk wall-loss/korosi dan slag, kurang andal untuk crack tipis (kontras terlalu kecil). Pastikan densitas berada dalam rentang ASME V (sinar-X 1.8-4.0, gamma 2.0-4.0) agar kurva linier."},{"heading":"Double-wall single-image (DWSI) caveat","body":"Pada pipa kecil, teknik double-wall sering dipakai: hanya dinding dekat-film yang dievaluasi (single-wall viewing) sementara dinding sumber out-of-focus. Untuk DWSI elliptical (umumnya NPS <= 3.5 in), offset source memberi dua proyeksi weld root yang terpisah -- berguna untuk lokasi, tetapi M kedua dinding berbeda; jadi sizing panjang harus pakai dinding yang menempel film dan dikoreksi M lokalnya, bukan rata-rata kedua dinding."}]}', 500, NULL),
  (4, 'reading', 'Comparator Chart, Karakterisasi & Pelaporan', '{"slides":[{"heading":"Reference radiograph untuk porosity/inklusi","body":"Untuk diskontinuitas tersebar (rounded porosity, cluster), ukuran individu kecil sulit diukur satu per satu; kode memakai reference radiograph / comparator chart (mis. ASTM E390 untuk las fusi baja, E155 untuk coran Al/Mg) yang menyandingkan image lapangan dengan standar bergambar tingkat keparahan. Penilaian = mencocokkan pola dengan severity level acceptable/unacceptable, bukan mengukur tiap pori dengan mistar -- menstandarkan akseptabilitas antar inspektor."},{"heading":"Aturan akumulasi & severity","body":"Banyak kode menilai porositas/slag berdasarkan dimensi maksimum tunggal DAN akumulasi dalam panjang las tertentu. Contoh ASME VIII / B31.x: batas rounded indication dikaitkan ke t (tebal dinding); slag/elongated indication dibatasi panjang maksimum DAN total dalam panjang las (mis. dalam 6t atau 12t). Reference radiograph membantu menilai distribusi/cluster terhadap chart acceptable vs unacceptable, bukan sekadar satu angka."},{"heading":"Characterization: membaca tanda khas","body":"Crack = garis tak teratur, bercabang, kontras tajam. LOF = garis lurus/halus di sisi bevel/fusion line. LOP = garis lurus kontinu di centerline root. Slag = membulat/memanjang ireguler, densitas sedang (lebih gelap). Porosity = bulat halus, tepi tegas (lebih gelap). Tungsten inclusion (GTAW) = TITIK TERANG/putih (radiopak) -- satu-satunya indikasi umum yang lebih terang dari logam dasar. Karakterisasi mendahului sizing karena menentukan kriteria akseptansi yang berlaku."},{"heading":"Pelaporan sizing yang benar","body":"Laporkan: jenis (characterization), lokasi (jarak dari datum + sisi/orientasi), panjang nyata (terkoreksi M), dan untuk tinggi -- nyatakan metode & ketidakpastian, atau rujuk UT bila RT tak andal. Sertakan setup (SFD/SOD/OFD, sumber, IQI/sensitivitas, densitas) agar M dan basis sizing dapat diaudit. Jangan pernah melaporkan tinggi/through-wall from single RT image tanpa kualifikasi -- itu kesalahan klasik Level II."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — Defect Sizing & Characterization', '{"description":"6 soal: sizing panjang (koreksi magnifikasi), keterbatasan tinggi/through-wall, teknik double-wall/paralaks/densitometri, dan reference radiograph/karakterisasi.","questionCount":6,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 8
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 8 mini-quiz (6 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Setup RT: SOD = 600 mm dan OFD = 40 mm. Sebuah indikasi terukur sepanjang 12.8 mm pada film. Berapa panjang nyata diskontinuitas setelah koreksi magnifikasi?',
   '["13.7 mm","12.0 mm","12.8 mm","11.3 mm"]', 1,
   'M = SFD/SOD = (SOD+OFD)/SOD = 640/600 = 1.067. Panjang nyata = panjang film / M = 12.8 / 1.067 = 12.0 mm. Magnifikasi geometrik selalu memperbesar bayangan, jadi ukuran nyata lebih kecil daripada yang terukur di film. 13.7 mm keliru mengalikan (bukan membagi) dengan M; 12.8 mm lupa mengoreksi M.', 'Defect Sizing', 'medium'),
  ('Mengapa RT konvensional dianggap LEMAH untuk mengukur tinggi (through-wall height) diskontinuitas planar dibanding UT?',
   '["RT memiliki resolusi spasial yang jauh lebih buruk daripada UT untuk semua dimensi","Densitas film tidak pernah berubah terhadap perubahan ketebalan material","RT memproyeksikan objek 3D menjadi citra 2D sehingga dimensi searah berkas tumpang-tindih, dan flaw planar yang tegak lurus berkas memberi sedikit/tanpa selisih path-length","RT hanya bisa mendeteksi diskontinuitas volumetrik dan tidak pernah mendeteksi crack"]', 2,
   'RT adalah proyeksi 2D; dimensi ke arah berkas (tinggi/through-wall) tertumpuk. Flaw planar yang bidangnya tegak lurus berkas hampir tak mengubah path-length sehingga kontras minimal. Karena itu UT/TOFD/PAUT dipakai untuk through-wall sizing pada ECA. Densitas memang berubah terhadap ketebalan (dasar densitometri), dan RT bisa mendeteksi crack bila orientasinya menguntungkan.', 'RT Limitations', 'easy'),
  ('Dalam teknik paralaks (double-exposure) untuk estimasi kedalaman flaw, apa indikator utama posisi flaw dalam arah ketebalan?',
   '["Beda pergeseran (parallax shift) bayangan flaw antara dua eksposur dengan sumber digeser sejauh jarak diketahui","Perubahan densitas total film antara dua eksposur","Panjang indikasi yang terukur pada masing-masing eksposur","Selisih waktu eksposur antara dua radiografi"]', 0,
   'Sumber digeser sejauh S; flaw yang lebih jauh dari film menghasilkan pergeseran bayangan lebih besar daripada yang dekat film. Beda parallax shift (d) inilah yang menempatkan flaw dalam arah ketebalan, mis. t = (d x SFD)/(S + d). Densitas total, panjang, dan waktu eksposur bukan dasar geometrik paralaks.', 'Height Sizing Techniques', 'hard'),
  ('Pada radiografi GTAW, sebuah indikasi muncul sebagai TITIK yang lebih TERANG (lebih putih / densitas lebih rendah) daripada logam dasar di sekitarnya. Karakterisasi paling tepat adalah:',
   '["Porosity","Lack of fusion","Slag inclusion","Inklusi tungsten"]', 3,
   'Tungsten lebih radiopak (menyerap lebih banyak radiasi) daripada baja, sehingga muncul sebagai titik terang/putih -- satu-satunya indikasi umum yang lebih terang dari logam dasar. Porosity, LOF, dan slag adalah material yang hilang/kurang padat sehingga tampak lebih GELAP dari logam dasar.', 'Characterization', 'medium'),
  ('Densitometri komparatif terkalibrasi untuk memperkirakan kehilangan ketebalan paling tepat dijalankan dengan cara:',
   '["Mengukur panjang indikasi lalu mengalikannya dengan faktor magnifikasi M","Membuat kurva densitas-vs-ketebalan dari step-wedge material sama pada setup identik, lalu membaca selisih ketebalan dari selisih densitas indikasi dan logam dasar","Membandingkan dua eksposur dengan sumber yang digeser dan mengukur pergeseran bayangan","Mencocokkan pola indikasi dengan reference radiograph severity chart"]', 1,
   'Densitometri komparatif: ukur D_base dan D_flaw dengan densitometer, lalu konversi selisih densitas ke selisih ketebalan via kurva D-vs-thickness dari step-wedge material/energi/setup yang sama. Mengalikan M adalah koreksi panjang; pergeseran sumber adalah paralaks; pencocokan reference radiograph adalah penilaian severity, bukan densitometri.', 'Densitometry', 'hard'),
  ('Apa fungsi utama reference radiograph / comparator chart (mis. ASTM E390 untuk las baja) dalam evaluasi diskontinuitas seperti cluster porosity?',
   '["Mengukur tinggi through-wall flaw secara langsung dalam satuan milimeter","Mengkalibrasi faktor magnifikasi M dari geometri eksposur","Menyediakan standar bergambar tingkat keparahan untuk dicocokkan dengan image lapangan, menstandarkan penilaian akseptabilitas antar inspektor","Menentukan waktu eksposur optimum untuk material tertentu"]', 2,
   'Reference radiograph / comparator chart (mis. ASTM E390 untuk las fusi baja, E155 untuk coran) menyandingkan image lapangan dengan gambar standar berbagai tingkat keparahan; penilaian dilakukan dengan mencocokkan pola, bukan mengukur tiap pori. Ini menstandarkan keputusan accept/reject antar inspektor. Chart tidak mengukur tinggi, tidak mengkalibrasi M, dan tidak menentukan waktu eksposur.', 'Reference Radiograph', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 8 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 9 — Procedure Development (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi Prosedur RT Tertulis', '{"slides":[{"heading":"Mengapa prosedur tertulis wajib","body":"ASME V Article 1 (T-150, Written Procedure Requirements) dan ASME VIII mensyaratkan RT dilakukan menurut prosedur tertulis yang sudah diqualifikasi dan disetujui. Tanggung jawab Level II: menulis, mendemonstrasikan, dan merevisi prosedur — bukan sekadar menjalankannya. Prosedur adalah dokumen kontraktual: tanpa prosedur valid, hasil RT tidak dapat diterima auditor/AI (Authorized Inspector)."},{"heading":"Elemen wajib prosedur (ASME V Article 2, Tabel T-221)","body":"Minimal harus mencantumkan: material & range ketebalan, geometri sambungan, jenis sumber (X-ray kV / Ir-192 / Co-60 / Se-75), ukuran focal spot/source size, SOD & OFD, jenis film/sistem digital, screen/filter, IQI (tipe & essential hole/wire), arah & jumlah eksposur, teknik (SWSI/DWSI/DWDI/panoramic), film density range (X-ray 1.8-4.0; gamma 2.0-4.0), prosesing/parameter scanning, overlap, dan kriteria penerimaan (referensi code). Tabel T-221 mencantumkan elemen ini sekaligus mengklasifikasikannya sebagai essential / nonessential."},{"heading":"Header & traceability","body":"Setiap prosedur diberi nomor unik, nomor revisi, tanggal, dan tanda tangan penulis (Level II/III) serta approver (Level III). Referensikan code construction (mis. ASME VIII Div 1) dan code metode (ASME V Article 2 atau ISO 17636-1 untuk film / 17636-2 untuk digital). Rev control mencegah penggunaan dokumen kadaluarsa — audit selalu cross-check rev number di report vs master list."},{"heading":"Prosedur generik vs spesifik","body":"Prosedur generik mencakup range luas (mis. ketebalan 6-50 mm, banyak diameter) dan memerlukan technique sheet per job. Prosedur spesifik dibuat untuk satu komponen kritis (mis. nozzle reaktor). Generik lebih efisien tetapi range variabel harus diqualifikasi di seluruh batas — IQI sensitivity harus terpenuhi pada ketebalan tertinggi DAN terendah (worst case)."}]}', 470, NULL),
  (2, 'reading', 'Essential vs Nonessential Variables', '{"slides":[{"heading":"Konsep variabel (ASME V Article 2, Tabel T-221)","body":"Essential variable = parameter yang bila diubah di luar batas prosedur memerlukan re-qualification (demonstrasi ulang). Nonessential variable = boleh berubah tanpa requalifikasi tetapi tetap harus tercatat di report/technique sheet. Klasifikasi resmi ada di Tabel T-221 ASME V Article 2. Memahami klasifikasi ini adalah inti tugas Level II: salah klasifikasi membuat prosedur invalid saat audit."},{"heading":"Contoh essential variables (RT)","body":"Perubahan yang umum essential: jenis/kelas sistem film (mis. dari kelas T3 ke kelas T2 yang lebih halus), perubahan ke detektor digital (CR/DR), naik IQI essential level, sumber radiasi (X-ray <-> gamma), arah berkas (SWSI <-> DWDI), kenaikan source/focal-spot size, penambahan/penghapusan screen, perubahan kriteria density/SNR, penurunan SOD, atau kenaikan geometric unsharpness Ug di atas batas. Ingat Ug = F x OFD / SOD — menaikkan OFD atau source size F, atau menurunkan SOD, menaikkan Ug (essential)."},{"heading":"Contoh nonessential variables","body":"Umumnya nonessential: identitas operator, nilai SOD spesifik selama masih dalam range terqualifikasi, exposure time/mA-min (selama density/IQI tercapai), aktivitas sumber dalam Ci (sepanjang Ug & density tetap dalam batas). Catatan: ''dalam range terqualifikasi'' adalah kunci — keluar dari range = berubah jadi essential. Semua nilai aktual tetap harus didokumentasikan di technique sheet."},{"heading":"Tabel range pada prosedur","body":"Prosedur menyatakan batas, bukan satu nilai: contoh SOD minimum 600 mm (untuk membatasi Ug), OFD maksimum sesuai geometri, density 1.8-4.0 (X-ray) atau 2.0-4.0 (gamma), variasi density melalui area of interest -15% s/d +30% (ASME V Article 2). Demonstrasi qualification harus membuktikan IQI sensitivity terpenuhi pada kombinasi terburuk (worst-case) dari range tersebut, bukan hanya pada satu titik nyaman."}]}', 480, NULL),
  (3, 'reading', 'Qualification by Demonstration', '{"slides":[{"heading":"Apa itu demonstrasi prosedur","body":"Sebelum dipakai produksi, prosedur diqualifikasi dengan menembak technique block / mock-up representatif (material & ketebalan sama, geometri sambungan mewakili) lalu membuktikan radiograf memenuhi semua kriteria image quality: IQI essential wire/hole terlihat, density dalam range, density variation dalam batas, tidak ada artefak yang menutup area of interest. Hasil direkam di technique sheet & disetujui Level III."},{"heading":"Pembuktian sensitivity","body":"Demonstrasi harus menunjukkan IQI yang disyaratkan terbaca. Untuk hole-type (plaque) ASTM E1025, target umum 2-2T (≈2% sensitivity): plaque setebal 2% benda uji dengan hole 2T terlihat. Untuk wire ASTM E747/ISO 19232, essential wire harus tampak. Pada digital, buktikan basic spatial resolution SRb (duplex-wire ASTM E2002) dan SNRnorm memenuhi kelas (ISO 17636-2 class A atau B) di seluruh range ketebalan."},{"heading":"Demonstrasi geometric unsharpness","body":"Ug dihitung dan dibuktikan dalam batas code: Ug = F x OFD / SOD. Contoh: F=2.4 mm, OFD=25 mm, SOD=700 mm → Ug = 2.4 x 25 / 700 = 0.086 mm. Demonstrasi memilih SOD minimum & OFD maksimum (worst case) untuk membuktikan Ug tetap acceptable; jika gagal, naikkan SOD atau pilih sumber dengan F lebih kecil (mis. Se-75, t½≈120 hari, untuk ketebalan rendah)."},{"heading":"Rekaman & re-qualification","body":"Hasil demonstrasi (radiograf master + technique sheet bertanda tangan) diarsipkan sebagai bukti qualification. Re-qualification dipicu oleh perubahan essential variable atau temuan audit. Personel yang melaksanakan demonstrasi harus qualified (Level II/III) sesuai SNT-TC-1A / written practice perusahaan. Jangan pernah memulai produksi sebelum demonstrasi lulus dan disetujui."}]}', 470, NULL),
  (4, 'reading', 'Review, Approval & Document Control', '{"slides":[{"heading":"Alur approval","body":"Penulis (Level II) → review teknis (Level III) → approval (Level III & sering customer/AI). Pada peralatan ASME, AI dapat meminta review prosedur. Prosedur baru tidak boleh aktif sebelum semua tanda tangan lengkap. Level III bertanggung jawab atas kebenaran teknis; Level II bertanggung jawab atas isi & demonstrasi."},{"heading":"Technique sheet per job","body":"Untuk prosedur generik, setiap pekerjaan butuh technique sheet yang mengisi nilai aktual (SOD, OFD, kV/Ci aktivitas, exposure, jumlah & lokasi eksposur, IQI yang dipakai, identifikasi film/marker). Technique sheet adalah anak dari prosedur induk dan harus mereferensikan nomor + rev prosedur agar traceable."},{"heading":"Konsistensi dengan code & komponen","body":"Prosedur RT harus konsisten dengan code acceptance yang berlaku (ASME VIII / B31.x, AWS D1.1 Clause 8, API 1104, ISO 10675). Kriteria penerimaan TIDAK boleh kurang ketat dari code. Jika customer spec lebih ketat, spec yang menang. Jangan campur kriteria density ASME (gamma 2.0-4.0) dengan batas ISO tanpa menyatakan code referensi yang jelas."},{"heading":"Kesalahan umum & audit findings","body":"Temuan audit tersering: rev mismatch (report kutip rev lama), IQI essential salah untuk ketebalan, range ketebalan di prosedur tak ter-demo di worst case, density variation tak dibatasi, kriteria penerimaan generik tanpa referensi paragraf code, atau perubahan ke digital dipakai tanpa requalify. Level II harus melakukan self-review sebelum submit ke Level III/AI."}]}', 430, NULL),
  (5, 'quiz', 'Mini-quiz — Procedure Development', '{"description":"8 soal pengembangan prosedur RT tertulis: elemen wajib, essential vs nonessential variable, qualification by demonstration, dan document control.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 9
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 9 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Menurut ASME V/VIII, kapan sebuah radiograf hasil RT dapat dinyatakan sah untuk penerimaan?',
   '["Bila operator memiliki sertifikat Level II yang masih berlaku","Bila dilakukan menurut prosedur tertulis yang sudah diqualifikasi dan disetujui","Bila density film berada antara 1.8 dan 4.0 saja","Bila IQI hole-type 2-2T terlihat pada radiograf"]', 1,
   'Code mensyaratkan RT dijalankan menurut prosedur tertulis yang telah diqualifikasi dan disetujui. Sertifikat operator, density, dan IQI adalah bagian dari pemenuhan, tetapi tanpa prosedur valid hasilnya tidak dapat diterima oleh AI/auditor.', 'Procedure Fundamentals', 'easy'),
  ('Sebuah prosedur RT generik mencakup ketebalan 6-50 mm. Untuk membuktikan IQI sensitivity terpenuhi saat qualification by demonstration, kombinasi mana yang harus diuji?',
   '["Hanya pada ketebalan tengah range (sekitar 28 mm) karena mewakili rata-rata","Hanya pada ketebalan terendah karena paling mudah ditembus","Pada kondisi worst-case di seluruh batas range, termasuk ketebalan tertinggi dan terendah","Pada ketebalan apa pun selama density mencapai 2.0"]', 2,
   'Prosedur generik menyatakan range, sehingga demonstrasi harus membuktikan IQI/sensitivity terpenuhi pada kombinasi terburuk di batas-batas range (ketebalan tertinggi dan terendah). Menguji hanya satu titik tengah tidak menjamin batas range terpenuhi.', 'Qualification', 'medium'),
  ('Manakah perubahan berikut yang merupakan ESSENTIAL VARIABLE dan memerlukan re-qualification prosedur RT?',
   '["Mengganti operator radiografer yang menjalankan eksposur","Mengubah waktu eksposur (mA-min) selama density dan IQI tetap terpenuhi","Mengubah aktivitas sumber (Ci) selama Ug dan density tetap dalam batas","Mengganti dari sistem film ke detektor digital (DR/CR)"]', 3,
   'Beralih dari film ke sistem digital mengubah karakter pencitraan secara fundamental dan merupakan essential variable yang memicu re-qualification. Operator, exposure time, dan aktivitas sumber adalah nonessential selama kriteria density/IQI/Ug tetap dalam range terqualifikasi.', 'Essential Variables', 'medium'),
  ('Diketahui source size F = 2.4 mm, OFD = 25 mm, SOD = 700 mm. Berapa geometric unsharpness Ug, dan tindakan apa yang tepat bila Ug melebihi batas?',
   '["Ug = 0.086 mm; bila berlebih, naikkan SOD atau pakai sumber dengan focal spot lebih kecil","Ug = 0.67 mm; bila berlebih, perkecil SOD agar berkas lebih fokus","Ug = 0.086 mm; bila berlebih, naikkan OFD agar gambar lebih tajam","Ug = 1.16 mm; bila berlebih, tambah waktu eksposur"]', 0,
   'Ug = F x OFD / SOD = 2.4 x 25 / 700 = 0.086 mm. Untuk menurunkan Ug, naikkan SOD atau perkecil source size F (atau kurangi OFD). Memperkecil SOD atau menambah OFD justru menaikkan Ug; menambah waktu eksposur hanya mempengaruhi density, bukan unsharpness.', 'Geometric Unsharpness', 'hard'),
  ('Pada prosedur RT untuk sistem digital sesuai ISO 17636-2, parameter mana yang harus dibuktikan saat demonstrasi untuk menjamin kualitas citra di seluruh range ketebalan?',
   '["Hanya waktu scanning imaging plate","Basic spatial resolution SRb (duplex-wire ASTM E2002) dan SNR ternormalisasi sesuai kelas","Hanya jumlah bit kedalaman gambar (12-16 bit)","Hanya suhu ruang prosesing"]', 1,
   'Untuk RT digital, demonstrasi harus membuktikan basic spatial resolution SRb (diukur dengan duplex-wire ASTM E2002) dan SNRnorm memenuhi kelas yang disyaratkan (ISO 17636-2 class A/B) di seluruh range. Bit depth atau waktu scan saja tidak cukup membuktikan sensitivity.', 'Digital RT Procedure', 'hard'),
  ('Apa fungsi technique sheet pada prosedur RT generik?',
   '["Menggantikan prosedur induk agar tidak perlu approval Level III","Mencatat nilai aktual per pekerjaan (SOD, OFD, eksposur, IQI) dengan referensi ke nomor & rev prosedur induk","Menyimpan kriteria penerimaan code agar tidak perlu dicantumkan di prosedur","Mendaftar seluruh personel bersertifikat di perusahaan"]', 1,
   'Technique sheet adalah turunan prosedur generik yang mengisi nilai aktual tiap job (SOD, OFD, kV/aktivitas, jumlah & lokasi eksposur, IQI yang dipakai) dan harus mereferensikan nomor + rev prosedur induk agar traceable. Ia tidak menggantikan prosedur induk maupun approval.', 'Document Control', 'medium'),
  ('Saat audit, manakah temuan yang paling tepat dikategorikan sebagai pelanggaran document control pada prosedur RT?',
   '["Report RT mengutip nomor revisi prosedur yang sudah kadaluarsa (rev mismatch)","Density film X-ray tercatat 2.5 pada area of interest","IQI hole-type 2-2T terlihat jelas pada radiograf","SOD aktual 700 mm masih berada dalam range terqualifikasi"]', 0,
   'Rev mismatch — report mengutip revisi prosedur yang sudah kadaluarsa — adalah pelanggaran document control klasik karena pekerjaan dijalankan terhadap dokumen tidak valid. Pilihan lain justru menunjukkan pemenuhan kriteria yang benar.', 'Document Control', 'easy'),
  ('Sebuah prosedur generik menetapkan kriteria penerimaan tanpa menyebut paragraf code apa pun, hanya menulis ''porositas tidak boleh berlebihan''. Mengapa ini bermasalah?',
   '["Karena kriteria penerimaan harus mereferensikan paragraf code yang berlaku dan tidak boleh kurang ketat darinya","Karena porositas tidak pernah dievaluasi dengan RT","Karena kriteria penerimaan hanya boleh ditulis oleh RSO","Karena prosedur generik dilarang memiliki kriteria penerimaan"]', 0,
   'Kriteria penerimaan dalam prosedur harus jelas mereferensikan code yang berlaku (mis. ASME VIII, AWS D1.1 Clause 8, API 1104, ISO 10675) dan tidak boleh kurang ketat dari code/spec. Kalimat kabur ''tidak berlebihan'' tidak dapat diaudit dan akan menjadi temuan.', 'Acceptance Criteria', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 9 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 10 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Dua lapis kode: technique code vs construction code', '{"slides":[{"heading":"ASME V = cara, bukan terima/tolak","body":"Kesalahan paling umum Level II pemula: mengira ASME Section V menentukan accept/reject. SALAH. ASME V Article 2 hanya mengatur BAGAIMANA membuat radiograf yang valid (technique): pemilihan sumber (T-274), penempatan IQI (T-276), kualitas citra (T-282), geometric unsharpness, densitas. ASME V TIDAK punya kriteria penerimaan cacat. Acceptance datang dari construction/referencing code."},{"heading":"Construction code = accept/reject","body":"Kriteria penerimaan ada di referencing code: ASME VIII Div 1 (UW-51 untuk RT penuh, UW-52 untuk spot RT) untuk pressure vessel; ASME B31.1 (power piping) dan B31.3 (process piping, Table 341.3.2) untuk perpipaan; AWS D1.1 Clause 8 untuk struktur baja las; API 1104 untuk pipeline. Selalu tanya: ''Code konstruksi apa yang dirujuk?'' sebelum menilai film."},{"heading":"Alur referensi nyata","body":"Contoh: bejana tekan dibangun ke ASME VIII Div 1. UW-51 mewajibkan RT 100%, dengan teknik radiograf mengikuti ASME V. Jadi: teknik = ASME V Art 2; penerimaan = UW-51 (mis. slag/indikasi memanjang dibatasi panjangnya relatif tebal T, no crack, no incomplete penetration, no incomplete fusion). Densitometer dan IQI mengikuti ASME V; ukuran indikasi dinilai terhadap UW-51. Dua dokumen, dua peran."},{"heading":"Kenapa ini penting untuk Level II","body":"Level II sign-off film. Jika menolak porositas dengan alasan ''ASME V dilanggar'', itu temuan audit (salah). ASME V hanya dilanggar bila densitas di luar rentang (mis. 1.8-4.0 untuk X-ray) atau IQI sensitivity tidak tercapai (mis. essential hole 2T pada IQI 2% tidak terlihat). Cacat dinilai SETELAH film dinyatakan valid secara teknik, terhadap construction code yang dirujuk."}]}', 460, NULL),
  (2, 'reading', 'ASME V Article 2 mendalam: persyaratan teknik', '{"slides":[{"heading":"Densitas film (T-282)","body":"Densitas melalui area of interest: X-ray 1.8-4.0; gamma (Ir-192/Co-60/Se-75) 2.0-4.0. Variasi densitas: densitas di area of interest tidak boleh lebih rendah dari -15% atau lebih tinggi dari +30% dibanding densitas yang dibaca di bawah IQI body. Bila terlampaui, butuh exposure/teknik tambahan (mis. multiple film, sectioning). Ini batas teknik, bukan batas cacat."},{"heading":"IQI: wire vs hole-type","body":"ASME V menerima wire IQI (ASTM E747 / ISO 19232) dan hole-type/plaque (ASTM E1025) dengan essential hole 1T, 2T, atau 4T. Penunjukan 2-2T: IQI bertebal 2% dari tebal material dengan essential hole 2T harus terlihat, setara ~2% sensitivity. Tabel T-276 memetakan essential wire/hole vs rentang tebal. IQI di source side bila praktis; bila film side, beri huruf ''F'' bertimbal dan gunakan baris tabel film-side (lebih ketat)."},{"heading":"Geometric unsharpness (T-274.2)","body":"Ug = F x OFD / SOD (F = ukuran focal spot/sumber, OFD = object-to-film, SOD = source-to-object). ASME V membatasi Ug maksimum berdasar tebal material: t hingga 2 in -> Ug max 0.020 in; di atas 2 hingga 3 in -> 0.030 in; di atas 3 hingga 4 in -> 0.040 in; di atas 4 in -> 0.070 in. Strategi: kecilkan F, perbesar SOD, atau minimalkan OFD. Hitung sebelum eksposur, bukan setelah film jelek."},{"heading":"Lampiran digital ASME V","body":"CR dan DR memakai Mandatory/Nonmandatory Appendix terkait pada Article 2. Metrik tambahan: SRb (basic spatial resolution, diukur dengan duplex wire ASTM E2002), SNR/SNRnorm minimum, bit depth (12-16 bit), dynamic range. DR/CR tetap wajib IQI; peran densitas film digantikan oleh kombinasi gray-value window dan SNR. Teknik digital tidak menggugurkan kewajiban acceptance code konstruksi."}]}', 500, NULL),
  (3, 'reading', 'AWS D1.1 Clause 8 dan API 1104', '{"slides":[{"heading":"AWS D1.1 Clause 8 — RT struktur","body":"D1.1 mengatur teknik DAN penerimaan dalam satu standar (struktur las baja). Kriteria penerimaan berbeda berdasarkan jenis pembebanan: tarik statis (statically loaded) lebih longgar; siklik/dinamis (cyclically loaded) lebih ketat (kelelahan/fatigue). Crack selalu ditolak. Porositas dan slag dinilai dengan tabel ukuran maksimum vs tebal dan jarak antar diskontinuitas. AWS lazim memakai hole-type IQI; penempatan dan sensitivity diatur dalam standar yang sama."},{"heading":"Statis vs siklik di D1.1","body":"Contoh: untuk sambungan tarik dinamis (cyclically loaded), slag/diskontinuitas memanjang dibatasi lebih kecil dan menuntut jarak minimum antar indikasi karena risiko fatigue. Untuk static loading batas ukuran lebih besar. Inspektor harus mengetahui apakah struktur dibebani siklik (jembatan, crane, struktur lepas pantai) atau statis (rangka gedung) sebelum menilai film."},{"heading":"API 1104 — pipeline workmanship","body":"API 1104 (las keliling pipeline) secara default memakai kriteria WORKMANSHIP: tiap jenis cacat punya batas tersendiri (IP/incomplete penetration, ICP, IF/incomplete fusion, burn-through, porositas cluster, slag/elongated slag) dinyatakan dalam panjang dan akumulasi per panjang las tertentu. Contoh prinsip: panjang individu dan akumulasi indikasi memanjang dibatasi relatif terhadap tebal dinding dan panjang las. Hole-type IQI lazim; sensitivity per wall thickness."},{"heading":"API 1104 Annex A — alternative acceptance / ECA","body":"Annex A menyediakan kriteria penerimaan alternatif berbasis Engineering Critical Assessment (ECA / fitness-for-service, fracture mechanics). Annex A dapat mengizinkan cacat lebih besar dari workmanship ASAL dibuktikan aman secara mekanika fraktur, dan umumnya dipasangkan dengan AUT (automated UT) untuk mengukur tinggi (through-wall height) cacat. Penting karena RT lemah mengukur tinggi cacat; Annex A hampir selalu butuh UT untuk dimensi tinggi."}]}', 500, NULL),
  (4, 'reading', 'ISO 17636/10675 dan strategi interpretasi cacat', '{"slides":[{"heading":"ISO 17636-1 vs -2","body":"ISO 17636-1 = RT film/konvensional; ISO 17636-2 = RT digital (CR/DR). Keduanya mendefinisikan dua kelas teknik: Class A (basic) dan Class B (improved/higher sensitivity, mis. SOD lebih besar, screen/source lebih ketat, Ug lebih kecil). Ini analog dengan ASME V Art 2 tetapi memakai satuan SI dan IQI ISO 19232 (wire) atau hole/step-hole. Class B sering disyaratkan untuk weld kritis."},{"heading":"ISO 10675 — acceptance terpisah","body":"Seperti pemisahan ASME, ISO memisahkan teknik (17636) dari penerimaan (ISO 10675-1 untuk baja, 10675-2 untuk aluminium). ISO 10675 memberi acceptance level (mis. Level 1 paling ketat, lalu 2, 3). Penunjukan tipikal: ''ISO 17636-2 Class B, ISO 10675-1 Level 1''. Inspektor membaca dua nomor: kelas teknik + level penerimaan."},{"heading":"Penerimaan jenis cacat: prinsip lintas-kode","body":"Universal: CRACK ditolak semua kode (ASME, AWS, API, ISO) tanpa kompromi. Incomplete penetration dan incomplete fusion umumnya ditolak atau sangat dibatasi. Porositas dan slag dinilai berdasar ukuran, jumlah, dan distribusi relatif tebal T. Yang berbeda hanya ANGKA batasnya per kode. Selalu kutip pasal spesifik di laporan (mis. ''reject per UW-51, crack'')."},{"heading":"Kelemahan RT dan implikasi kode","body":"RT kuat untuk panjang (length, dengan koreksi magnifikasi M = SFD/SOD) tetapi lemah untuk tinggi/through-wall. Karena itu kriteria berbasis ECA (API 1104 Annex A, atau fitness-for-service via API 579) yang membutuhkan dimensi tinggi cacat hampir selalu mensyaratkan UT/AUT. Level II harus tahu kapan RT cukup (workmanship) dan kapan harus eskalasi ke UT untuk acceptance berbasis fracture mechanics."}]}', 460, NULL),
  (5, 'quiz', 'Mini-quiz — interpretasi kode lanjut', '{"description":"8 soal: ASME V Art 2 vs construction code, AWS D1.1, API 1104 + Annex A, ISO 17636/10675, penerimaan jenis cacat.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 10
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 10 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Seorang RT Level II menemukan porositas pada radiograf bejana tekan yang dibangun ke ASME VIII Div 1. Dokumen mana yang menentukan apakah porositas itu DITERIMA atau DITOLAK?',
   '["ASME Section V Article 2","ASTM E1025","ISO 19232","ASME VIII Div 1 (UW-51)"]', 3,
   'ASME V Article 2 hanya mengatur teknik (cara membuat radiograf valid), bukan accept/reject. Kriteria penerimaan cacat datang dari construction/referencing code, dalam hal ini ASME VIII Div 1 UW-51. ASTM E1025 hanya standar hole-type IQI; ISO 19232 standar wire IQI.', 'Code Interpretation', 'medium'),
  ('Per ASME V Article 2 (T-282), berapa rentang densitas film yang dapat diterima untuk radiograf yang dibuat dengan sumber sinar-X (X-ray)?',
   '["1.8 sampai 4.0","2.0 sampai 4.0","1.5 sampai 3.5","2.5 sampai 4.5"]', 0,
   'ASME V membatasi densitas melalui area of interest 1.8-4.0 untuk sinar-X dan 2.0-4.0 untuk gamma (Ir-192/Co-60/Se-75). Ini batas teknik; bila di luar rentang, film tidak valid dan harus diulang, terlepas dari ada/tidaknya cacat.', 'ASME V', 'easy'),
  ('Sebuah radiograf dibuat dengan focal spot F = 3 mm, OFD = 15 mm, dan SOD = 600 mm. Berapa geometric unsharpness (Ug)?',
   '["1.5 mm","0.30 mm","0.075 mm","0.12 mm"]', 2,
   'Ug = F x OFD / SOD = 3 x 15 / 600 = 45/600 = 0.075 mm. Ug dikecilkan dengan focal spot lebih kecil, SOD lebih besar, atau OFD lebih kecil. ASME V membatasi Ug maksimum sesuai tebal material.', 'ASME V', 'medium'),
  ('Dalam AWS D1.1 Clause 8, faktor utama apa yang membuat kriteria penerimaan radiografi BERBEDA dari satu sambungan ke sambungan lain?',
   '["Jenis sumber radiasi yang digunakan","Apakah struktur dibebani statis atau siklik/dinamis","Merek film yang dipakai","Negara tempat inspeksi dilakukan"]', 1,
   'AWS D1.1 mengatur teknik dan penerimaan dalam satu standar, dan kriteria penerimaan diskontinuitas berbeda untuk statically loaded (lebih longgar) versus cyclically/dynamically loaded (lebih ketat, karena fatigue). Crack selalu ditolak pada kedua kasus.', 'AWS D1.1', 'medium'),
  ('API 1104 secara default menggunakan kriteria penerimaan berbasis ''workmanship''. Apa fungsi utama Annex A pada API 1104?',
   '["Menetapkan prosedur kalibrasi densitometer","Mendefinisikan ukuran focal spot maksimum","Mengatur retensi arsip radiograf digital","Memberi kriteria penerimaan alternatif berbasis Engineering Critical Assessment (ECA/fracture mechanics)"]', 3,
   'Annex A API 1104 menyediakan alternative acceptance criteria berbasis ECA (fitness-for-service / fracture mechanics), yang dapat mengizinkan cacat lebih besar dari workmanship asalkan dibuktikan aman. Karena butuh dimensi tinggi/through-wall cacat, Annex A umumnya dipasangkan dengan AUT/UT.', 'API 1104', 'hard'),
  ('Sebuah spesifikasi proyek menuliskan ''ISO 17636-2 Class B, ISO 10675-1 Level 1''. Apa arti kedua referensi tersebut?',
   '["Keduanya menentukan kriteria penerimaan cacat","Keduanya menentukan teknik radiografi","ISO 17636-2 Class B = teknik RT digital (improved/higher sensitivity); ISO 10675-1 Level 1 = level penerimaan cacat","ISO 17636-2 = penerimaan; ISO 10675-1 = teknik film"]', 2,
   'ISO 17636-2 mengatur TEKNIK RT digital (Class A basic, Class B improved/higher sensitivity). ISO 10675-1 mengatur PENERIMAAN cacat las baja (Level 1 paling ketat). Seperti pemisahan ASME V vs ASME VIII, ISO memisahkan teknik dari acceptance.', 'ISO 17636/10675', 'medium'),
  ('Mengapa kriteria penerimaan berbasis ECA (mis. API 1104 Annex A atau fitness-for-service) hampir selalu mensyaratkan UT/AUT dan tidak cukup dengan RT saja?',
   '["RT sama sekali tidak dapat mendeteksi crack","RT lemah mengukur tinggi/through-wall (height) cacat, sedangkan ECA butuh dimensi tinggi untuk perhitungan mekanika fraktur","RT tidak diizinkan dipakai pada pipeline","UT selalu lebih murah daripada RT"]', 1,
   'RT kuat untuk panjang (length, dengan koreksi magnifikasi M = SFD/SOD) tetapi lemah untuk tinggi/through-wall. ECA/fracture mechanics memerlukan dimensi tinggi cacat secara akurat, sehingga UT/AUT yang andal mengukur through-wall height hampir selalu disyaratkan. RT tetap mampu mendeteksi crack, hanya kurang andal mengukur tingginya.', 'Defect Sizing', 'hard'),
  ('Penunjukan IQI ''2-2T'' yang umum disyaratkan ASME V menunjukkan tingkat sensitivitas radiografi sekitar berapa?',
   '["0.5%","1%","2%","4%"]', 2,
   'Penunjukan 2-2T berarti IQI dengan ketebalan 2% dari tebal material dan essential hole 2T harus terlihat, setara dengan sensitivitas radiografi ~2%. Ini tingkat sensitivitas standar yang lazim disyaratkan code konstruksi.', 'ASME V', 'easy')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 10 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 11 (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Case Study 1 — Sambungan Las Pipeline Uap Panas (In-Service)', '{"slides":[{"heading":"Komponen & kondisi","body":"Pipeline transmisi uap, material A106 Gr.B, OD 273 mm (NPS 10), wall 12.7 mm, butt weld girth. Line tetap beroperasi pada ~180 derajat C (tidak bisa shutdown). Tantangan: panas permukaan, akses 360 derajat terbatas (pipe rack), dan kebutuhan inspeksi 100% per kontrak yang merujuk API 1104 (atau ASME B31.1/B31.3 untuk piping bertekanan tergantung klasifikasi line)."},{"heading":"Teknik RT dipilih","body":"Double-wall single-image (DWSI / contact technique) untuk OD 273 mm karena diameter besar (> ~89 mm / 3.5 in batas praktis DWDI elliptical). Sinar menembus dua dinding tetapi hanya dinding film-side yang dievaluasi. Sumber Ir-192 (cocok untuk 12.7 mm baja). SOD diset 600 mm; film heat-shielded dengan cassette lead-backed + insulating pad agar emulsi tidak rusak di 180 derajat C. SFD = SOD + ketebalan film-side = 600 + 12.7 = ~613 mm; magnifikasi M = SFD/SOD = 613/600 = 1.02 (minimal, panjang indikasi dapat dibaca dengan koreksi kecil)."},{"heading":"Geometric unsharpness check","body":"Ug = F x OFD / SOD. F = 3.0 mm (focal/source size Ir-192 typical), OFD = object-to-film = ketebalan dinding film-side = 12.7 mm, SOD = 600 mm. Ug = 3.0 x 12.7 / 600 = 0.064 mm. Jauh di bawah batas ASME V Article 2 (Ug maks 0.51 mm untuk t < 50 mm), jadi ketajaman geometri OK. Wire IQI ASTM E747 set B ditempatkan di source side; densitas film 2.6 (dalam rentang gamma 2.0-4.0 per ASME V T-282)."},{"heading":"Temuan & evaluasi vs code","body":"Radiograf menunjukkan indikasi linier gelap memanjang ~18 mm di root, lebar konsisten = incomplete penetration (IP) di root pass. API 1104: panjang individual IP dibatasi (umumnya tidak melebihi 25 mm) DAN ada batas akumulasi dalam tiap 300 mm las; sebagian besar acceptance juga mengharuskan cek terhadap spesifikasi owner. Indikasi 18 mm < 25 mm individual, namun untuk hot line bertekanan tinggi root integrity kritis dan spesifikasi proyek/owner di sini lebih ketat untuk IP di root. Disposisi: REJECT → REPAIR — grind root, re-weld, re-RT area perbaikan + overlap tiap sisi sesuai prosedur."}]}', 480, NULL),
  (2, 'reading', 'Case Study 2 — Pressure Vessel Kritis: Nozzle-to-Shell Set-in Weld', '{"slides":[{"heading":"Komponen & kondisi","body":"Bejana tekan reaktor, SA-516 Gr.70, shell wall 38 mm, nozzle DN 200. Sambungan nozzle-to-shell full penetration, geometri kurva ganda (compound curvature). Lethal service, sehingga ASME VIII Div.1 (UW-11 / UW-51) mensyaratkan RT penuh (Full RT) dengan acceptance ketat. Akses internal terbatas — RT panoramic tidak mungkin."},{"heading":"Teknik RT dipilih","body":"Multiple single-wall exposures (SWE) mengelilingi nozzle, sumber di luar, film di permukaan dalam yang diakses lewat manway. Untuk baja 38 mm, Ir-192 sebenarnya masih dalam rentang praktisnya; namun karena ketebalan radiografis EFEKTIF di tepi miring (compound curvature) jauh lebih besar, Co-60 (1.17 & 1.33 MeV) dipilih demi penetrasi dan throughput pada ketebalan tinggi tersebut. Hole-type IQI ASTM E1025 di shell side, esensial 2-2T (≈ 2% sensitivity)."},{"heading":"Optimasi kualitas citra","body":"Karena compound curvature, ketebalan radiografis bervariasi sepanjang area. Variasi densitas dijaga dalam -15% sampai +30% relatif terhadap densitas di lokasi IQI per ASME V Article 2; di mana batas terlampaui di tepi, dilakukan exposure tambahan dengan parameter berbeda. Densitas utama 2.8 (memenuhi gamma 2.0-4.0). Lead screen (mis. 0.125 mm) depan/belakang untuk intensifikasi & reduksi scatter."},{"heading":"Temuan & evaluasi vs code","body":"Tampak cluster indikasi membulat (rounded) di fusion line, terbesar 4.0 mm, beberapa kecil 1-2 mm. ASME VIII Div.1 (Mandatory Appendix 4, rounded indication charts) memberi batas ukuran rounded berdasarkan t; namun re-shoot pada sudut berbeda mengonfirmasi salah satu indikasi memiliki ekor linier = crack-like. Disposisi: REJECT — crack/indikasi crack-like tidak pernah acceptable. Repair: excavate (UT depth map dulu untuk memandu penggalian), re-weld, re-RT + MT/PT permukaan."}]}', 500, NULL),
  (3, 'reading', 'Case Study 3 — Sizing & Karakterisasi Cacat: Slag vs Porosity vs Crack', '{"slides":[{"heading":"Konteks sizing di lapangan","body":"Spool piping refinery, A335 P11 (1.25Cr-0.5Mo), wall 9.5 mm, RT film konvensional. Tantangan utama RT: panjang indikasi dapat dibaca dari citra (dikoreksi magnifikasi M = SFD/SOD), tetapi TINGGI / through-wall sangat sulit diukur dari RT tunggal — ini kelemahan utama RT vs UT yang menyelesaikan height dengan baik."},{"heading":"Karakterisasi via morfologi citra","body":"Slag inclusion: gelap, ireguler, sering linier mengikuti tepi groove, densitas variabel. Porosity: gelap, membulat, tepi halus, terisolasi atau cluster. Crack: garis gelap tipis tajam, sering bercabang, mengikuti arah tegangan, kontras tinggi. Tungsten inclusion (dari GTAW): justru TERANG (atenuasi tinggi karena densitas tungsten lebih besar dari baja) — kebalikan dari slag/porosity yang gelap."},{"heading":"Mengukur panjang & koreksi magnifikasi","body":"Indikasi slag terukur 14 mm di film. SFD = 700 mm, SOD = 660 mm, jadi M = SFD/SOD = 700/660 = 1.06. Panjang aktual = panjang film / M = 14 / 1.06 = 13.2 mm. Untuk through-wall: RT tunggal tidak resolutif; gunakan teknik double-wall/parallax (dua exposure dengan offset sumber) atau densitometri komparator (bandingkan densitas indikasi vs step wedge kalibrasi) untuk estimasi kedalaman kasar. Bila tinggi kritikal, sizing dialihkan ke UT (TOFD / phased array)."},{"heading":"Evaluasi vs code","body":"Slag elongated 13.2 mm pada wall 9.5 mm: ASME VIII Div.1 / B31.3 membatasi panjang indikasi memanjang (slag/IL) relatif terhadap t, dengan batas akumulasi. Panjang 13.2 mm melampaui batas individual untuk indikasi linier elongated pada t = 9.5 mm → REJECT. Disposisi REPAIR: gouge slag, re-weld, re-RT. Catatan SME: untuk kebutuhan ECA / fitness-for-service, panjang dari RT saja tidak cukup — perlu height/through-wall dari UT sebagai input ke API 579-1/ASME FFS-1."}]}', 460, NULL),
  (4, 'reading', 'Case Study 4 — Digital RT (CR) untuk Akses Sulit & Disposisi Cepat', '{"slides":[{"heading":"Komponen & justifikasi digital","body":"Tie-in las pada header tekanan, A234 WPB fitting ke pipe, wall 15 mm, lokasi elevated platform dengan window inspeksi pendek (turnaround). Dipilih Computed Radiography (CR) imaging plate: dynamic range lebar memaafkan kesalahan exposure, hasil dalam beberapa menit setelah scan (vs proses film basah yang lebih lama), arsip digital langsung."},{"heading":"Metrik kualitas digital","body":"ISO 17636-2 (RT digital, class A/B) dipakai; dipilih Class B (improved techniques, kualitas lebih tinggi) untuk service bertekanan. SRb (basic spatial resolution) diukur dengan duplex-wire IQI ASTM E2002 = 160 µm (memenuhi batas kelas). SNRnorm dicek memenuhi minimum tabel ISO untuk ketebalan/energi. IQI: wire ISO 19232 untuk sensitivitas kontras, plus duplex-wire untuk resolusi. Bit depth 16-bit memberi dynamic range besar untuk windowing."},{"heading":"Temuan & post-processing","body":"Pada windowing kontras, terlihat untaian indikasi membulat sejajar root = hollow bead / cluster porosity di root pass. Post-processing (kontras + edge enhancement) memperjelas visualisasi; PENTING: enhancement tidak boleh mengubah data kuantitatif yang dipakai untuk sizing/disposisi, hanya untuk visualisasi. Densitometri optik tidak berlaku (digital memakai gray value), evaluasi memakai grayscale + SNR."},{"heading":"Evaluasi vs code & disposisi","body":"Cluster porosity dengan pore terbesar 1.8 mm, terdistribusi sepanjang ~22 mm. ISO 10675-1 (acceptance untuk film & digital) Level 1: cluster/grup porositas dibatasi persentase luas area per panjang evaluasi. Luas cluster di sini melewati batas Level 1 → REJECT pada acceptance ketat; jika spesifikasi proyek mengizinkan Level 2 (lebih longgar) hasil bisa ACCEPT. Karena service tekanan, disposisi diputuskan bersama Engineering: di-REPAIR (re-weld root). Catatan SME: selalu konfirmasi acceptance level yang dirujuk kontrak SEBELUM disposisi."}]}', 440, NULL),
  (5, 'quiz', 'Mini-quiz — Field Inspection Case Studies', '{"description":"6 soal aplikasi: pemilihan teknik, sizing/karakterisasi, evaluasi vs code, dan disposisi accept/reject/repair.","questionCount":6,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 11
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 11 mini-quiz (6 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada inspeksi girth weld pipeline uap panas OD 273 mm (NPS 10) yang tetap beroperasi pada 180 derajat C, teknik geometri RT yang paling tepat untuk diameter besar ini adalah:',
   '["Double-wall single-image (DWSI), karena diameter besar (> ~89 mm) membuat DWDI elliptical tidak praktis","Double-wall double-image (DWDI) elliptical, wajib untuk semua diameter pipa","Single-wall single-image dari dalam pipa tanpa pelindung panas pada film","Panoramic single exposure dengan sumber di tengah pipa"]', 0,
   'Untuk pipa diameter besar (umumnya OD > ~89 mm / 3.5 in), double-wall single-image (DWSI) dipakai: sinar menembus dua dinding tetapi hanya dinding film-side yang dievaluasi. DWDI elliptical justru untuk diameter kecil di mana superimposisi dua dinding bisa dipisahkan secara elips. Panoramic memerlukan akses internal/crawler dan tidak cocok di sini, dan film tetap butuh pelindung panas pada 180 derajat C.', 'Technique Selection', 'medium'),
  ('Pada Case Study nozzle pressure vessel SA-516 Gr.70 wall 38 mm (lethal service), radiograf awal menunjukkan indikasi membulat, namun re-shoot pada sudut berbeda mengungkap salah satunya memiliki ekor linier (crack-like). Disposisi yang benar adalah:',
   '["Reject lalu repair — indikasi crack-like tidak pernah acceptable apa pun ukurannya","Accept — karena diameter terbesar hanya 4.0 mm, di bawah batas rounded indication","Accept dengan catatan, karena ASME VIII memperbolehkan crack kecil pada t tebal","Tidak perlu repair, cukup monitoring berkala in-service"]', 0,
   'Crack atau indikasi crack-like selalu rejectable di bawah ASME VIII Div.1 dan kode las pada umumnya, tanpa memandang ukuran. Re-shoot dari sudut berbeda adalah teknik yang benar untuk mengonfirmasi karakter linier suatu indikasi. Batas ukuran rounded indication (Appendix 4) tidak berlaku untuk indikasi linier/crack. Disposisi: reject lalu repair (excavate, re-weld, re-RT + MT/PT).', 'Code Interpretation', 'easy'),
  ('Sebuah indikasi slag terukur 14 mm pada film. SFD = 700 mm dan SOD = 660 mm. Berapa panjang aktual cacat setelah koreksi magnifikasi?',
   '["13.2 mm","14.8 mm","14.0 mm","12.0 mm"]', 0,
   'Magnifikasi M = SFD/SOD = 700/660 = 1.06. Panjang aktual = panjang film / M = 14 / 1.06 = 13.2 mm. Indikasi pada film selalu lebih besar dari aktual karena proyeksi divergen, sehingga panjang film harus DIBAGI M, bukan dikalikan.', 'Defect Sizing', 'medium'),
  ('Mengapa pengukuran TINGGI (through-wall height) cacat dianggap kelemahan utama RT dibanding UT, dan apa solusi yang umum dipakai di lapangan?',
   '["RT tunggal tidak resolutif untuk through-wall karena memproyeksikan volume ke citra 2D; gunakan double-wall/parallax, densitometri komparator, atau alihkan sizing ke UT (TOFD/phased array)","RT mengukur tinggi dengan sangat akurat sehingga tidak perlu solusi tambahan","RT hanya bisa mengukur tinggi tetapi tidak panjang, jadi UT dipakai untuk mengukur panjang","Solusinya selalu mengganti film dengan imaging plate digital untuk memperoleh tinggi secara otomatis"]', 0,
   'RT memproyeksikan volume cacat ke citra 2D, sehingga panjang terbaca baik (dikoreksi magnifikasi) tetapi tinggi/through-wall sangat sulit ditentukan dari satu radiograf. Solusi: double-wall/parallax (offset sumber), densitometri komparator terhadap step wedge, atau yang paling andal mengalihkan sizing ketinggian ke UT seperti TOFD/phased array. RT digital memperbaiki dynamic range tetapi tidak otomatis menyelesaikan masalah pengukuran tinggi.', 'Defect Sizing', 'hard'),
  ('Pada Case Study CR (Computed Radiography) untuk tie-in las bertekanan dengan ISO 17636-2 Class B, alat dan parameter mana yang dipakai untuk memverifikasi resolusi spasial dasar (SRb)?',
   '["Duplex-wire IQI ASTM E2002, dengan SRb dinyatakan dalam µm","Densitometer transmisi untuk membaca densitas optik 2.0-4.0","Hole-type plaque ASTM E1025 esensial 2-2T saja","Step wedge komparator untuk membaca gray value secara langsung"]', 0,
   'Pada RT digital, resolusi spasial dasar (SRb, satuan µm) diukur dengan duplex-wire IQI ASTM E2002. Densitometer dan densitas optik adalah konsep film, bukan digital (digital memakai gray value/SNR). Hole-type 2-2T mengukur sensitivitas kontras, bukan resolusi spasial. ISO 17636-2 Class B menuntut kualitas lebih tinggi termasuk batas SRb dan SNRnorm.', 'Digital RT', 'medium'),
  ('Pada Case Study CR, ditemukan cluster porosity dan disposisi diputuskan bersama Engineering. Catatan SME yang paling tepat sebelum melakukan disposisi accept/reject adalah:',
   '["Konfirmasi acceptance level kontrak yang dirujuk (mis. ISO 10675-1 Level 1 vs Level 2) sebelum memutuskan, karena hasil bisa berbeda untuk indikasi yang sama","Selalu pakai Level 1 paling ketat untuk semua proyek tanpa kecuali","Gunakan post-processing enhancement untuk mengubah data kuantitatif agar cacat lolos","Disposisi cukup berdasarkan penilaian visual inspector tanpa merujuk kode mana pun"]', 0,
   'Kriteria penerimaan bergantung pada acceptance level yang ditetapkan kontrak/spesifikasi (mis. ISO 10675-1 Level 1 lebih ketat dari Level 2), sehingga indikasi yang sama bisa reject pada satu level dan accept pada level lain. Inspector harus mengonfirmasi level yang berlaku sebelum disposisi. Post-processing hanya untuk visualisasi dan tidak boleh mengubah data kuantitatif; disposisi tidak pernah hanya berdasarkan opini tanpa kode.', 'Code Interpretation', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 11 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


-- ============================================================
-- SNS NDT — RT-L2 content (AUTO-GENERATED from authoring workflow)
-- Run AFTER seed_elearning_level2_all_methods.sql (modules must exist).
-- Steps: ON CONFLICT DO NOTHING (safe, never deletes user progress).
-- Quiz questions: DELETE+INSERT per quiz step (idempotent).
