-- RT-L2 Module 12 — Quality Control & Audit (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Mengapa QC harian wajib di RT', '{"slides":[{"heading":"QC = jaminan data valid","body":"Quality Control (QC) memastikan setiap radiograf yang di-sign Level II benar-benar valid. Tanpa QC, density bisa di luar batas, IQI tidak sensitif, atau sumber sudah terlalu lemah — semua membuat indikasi cacat tidak terlihat (false accept). QC bukan birokrasi: ini garis pertahanan terakhir sebelum cacat lolos ke lapangan."},{"heading":"Daily QC checklist","body":"Sebelum eksposur pertama setiap hari: cek survey meter & dosimeter berfungsi (battery, response check), verifikasi crank-out / guide tube exposure device beroperasi normal, cek kondisi film/IP & cassette (light leak, scratch), verifikasi suhu & konsentrasi developer (untuk film basah), dan catat aktivitas sumber terkini hasil decay tracking. Semua dicatat di logbook bertanggal."},{"heading":"Frekuensi pemeriksaan","body":"Berbeda interval per item: survey meter & dosimeter — cek fungsi harian + kalibrasi tahunan; densitometer — verifikasi harian dengan calibrated step wedge, kalibrasi formal tahunan; processor (film basah) — kontrol harian density via control strip; source decay — di-update setiap eksposur (perhitungan) + verifikasi fisik berkala. Level II bertanggung jawab memastikan interval dipatuhi."},{"heading":"Peran Level II vs RSO","body":"Level II melakukan QC teknis kualitas citra (density, IQI, SRb, densitometer). RSO bertanggung jawab atas QC keselamatan radiasi (kalibrasi survey meter, leak test sumber, audit dosis pekerja). Keduanya co-work tetapi tugas RSO butuh lisensi terpisah. Jangan campur tanggung jawab — Level II tidak boleh sign-off leak test sumber."}]}', 440, NULL),
  (2, 'reading', 'Source decay tracking — perhitungan A=A0·e^(-0.693t/t½)', '{"slides":[{"heading":"Mengapa decay harus dilacak","body":"Aktivitas sumber radioaktif turun terus-menerus. Jika operator memakai waktu eksposur lama (dari tabel awal) padahal sumber sudah meluruh, hasilnya underexposure — density di bawah minimum (X-ray <1.8, gamma <2.0 per ASME V) dan cacat tidak terlihat. Decay tracking memastikan waktu eksposur selalu dikoreksi terhadap aktivitas aktual."},{"heading":"Rumus peluruhan","body":"A = A0 · e^(-0.693·t / t½). A0 = aktivitas awal (Ci atau Bq), t = waktu berlalu, t½ = waktu paruh, 0.693 = ln(2). Half-life yang dipakai: Ir-192 ≈ 74 hari, Se-75 ≈ 120 hari, Co-60 ≈ 5.27 tahun. Karena t½ Ir-192 paling pendek di antara ketiganya, decay Ir-192 paling kritis untuk dilacak — aktivitasnya turun ~1% per hari."},{"heading":"Worked example — Ir-192","body":"Sumber Ir-192 dikalibrasi 100 Ci. Berapa aktivitas setelah 30 hari? A = 100 · e^(-0.693·30/74) = 100 · e^(-0.2809) = 100 · 0.7551 = 75.5 Ci. Setelah 74 hari (= 1 half-life): A = 100 · e^(-0.693) = 100 · 0.5 = 50 Ci (tepat separuh, sesuai definisi half-life). Aktivitas yang turun ke ~75% dalam sebulan menjelaskan kenapa waktu eksposur harus dinaikkan tiap minggu."},{"heading":"Koreksi waktu eksposur","body":"Waktu eksposur baru = waktu lama · (A_lama / A_baru). Contoh: jika dengan 100 Ci butuh 60 detik, maka dengan 75.5 Ci butuh 60 · (100/75.5) = 79.5 detik (≈80 s). Banyak source projector punya decay chart/slide-rule, tetapi Level II harus mampu verifikasi manual. Catat aktivitas terhitung di logbook setiap eksposur sebagai audit trail."}]}', 520, NULL),
  (3, 'reading', 'Kalibrasi densitometer & monthly density check', '{"slides":[{"heading":"Densitometer & step wedge","body":"Densitometer mengukur optical density film. Verifikasi harian: nol-kan pada area tanpa film (clear base), lalu baca calibrated step wedge (NIST-traceable). Setiap step punya nilai density tersertifikat — pembacaan harus dalam toleransi (umumnya ±0.05 D). Jika di luar toleransi, instrumen tidak boleh dipakai sampai dikalibrasi ulang. Kalibrasi formal: tahunan oleh lab terkalibrasi."},{"heading":"Batas density ASME V","body":"Density area of interest: X-ray 1.8–4.0; gamma 2.0–4.0. Density variation yang diperbolehkan melalui area of interest: -15% / +30% dari density yang terbaca di sebelah benda IQI (untuk single-film viewing). Monthly density check mendokumentasikan bahwa teknik & processor masih menghasilkan density dalam rentang ini secara konsisten."},{"heading":"Processor control (film basah)","body":"Untuk pemrosesan film, control strip harian memantau base+fog, speed index, dan contrast index. Tren density yang turun menandakan developer lemah/dingin atau terkontaminasi. Plot pada control chart — bila melewati control limit, hentikan dan ganti kimia. Monthly review meng-aggregate tren harian untuk mendeteksi drift perlahan sebelum film tertolak massal."},{"heading":"CR/DR digital equivalent","body":"Pada CR/DR, parameter setara: SNR (signal-to-noise ratio), grayscale value, dan basic spatial resolution (SRb). Kalibrasi flat-field & detector dilakukan berkala. Data mentah digital 16-bit harus disimpan (bukan hanya JPEG/8-bit terkompresi) untuk audit & reprocessing. Density konvensional digantikan oleh gray-level window pada workstation."}]}', 460, NULL),
  (4, 'reading', 'Verifikasi IQI/SRb & rekaman audit', '{"slides":[{"heading":"IQI — bukti sensitivitas","body":"Image Quality Indicator membuktikan radiograf cukup sensitif. Wire IQI per ASTM E747, hole-type (plaque) per ASTM E1025. Essential wire/hole harus terlihat pada radiograf di area yang diwakili. Setiap shift, verifikasi set IQI lengkap & tidak rusak (kawat tidak putus, plaque tidak korosi). IQI salah pilih atau tidak terlihat = sensitivitas tidak terbukti = radiograf di-reject."},{"heading":"SRb — duplex wire (E2002)","body":"Untuk sistem digital (CR/DR), basic spatial resolution diverifikasi dengan duplex-wire IQI per ASTM E2002. Hasilnya menentukan SRb (mm) yang harus memenuhi batas kelas sistem. SRb dicek saat kualifikasi sistem dan diverifikasi berkala — bukti bahwa unsharpness total sistem (termasuk geometric unsharpness Ug = F·OFD/SOD) masih dalam batas untuk mendeteksi cacat target."},{"heading":"Audit records & retention","body":"Rekaman wajib: logbook QC harian, sertifikat kalibrasi densitometer/survey meter, decay log sumber, control chart processor, technique sheet per joint, dan radiograf + report. Retensi mengikuti code & client (sering 5 tahun atau seumur asset; raw 16-bit digital disimpan). Audit trail harus utuh: siapa, kapan, parameter apa — agar setiap penerimaan bisa ditelusuri."},{"heading":"Audit internal & eksternal","body":"Audit internal berkala (mis. kuartalan) memverifikasi kepatuhan prosedur, kelengkapan rekaman, dan validitas kalibrasi. Audit eksternal oleh client/badan akreditasi (mis. compliance ISO 17636) memeriksa sistem mutu menyeluruh. Temuan (non-conformance) wajib di-corrective action dan ditutup dengan bukti. Level II sering menjadi titik kontak teknis saat audit."}]}', 480, NULL),
  (5, 'quiz', 'Mini-quiz — Quality Control & Audit', '{"description":"8 soal: source decay calc, densitometer, density ASME V, IQI/SRb, audit & peran Level II vs RSO.","questionCount":8,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 12
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 12 mini-quiz (8 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Sumber Ir-192 dikalibrasi pada 100 Ci. Berapa aktivitasnya setelah 30 hari (t½ Ir-192 ≈ 74 hari)?',
   '["50.0 Ci","75.5 Ci","85.6 Ci","28.1 Ci"]', 1,
   'A = A0·e^(-0.693t/t½) = 100·e^(-0.693·30/74) = 100·e^(-0.2809) = 100·0.7551 ≈ 75.5 Ci. (50 Ci hanya tercapai pada 1 half-life = 74 hari, bukan 30 hari.)', 'Source Decay', 'medium'),
  ('Tepat setelah satu waktu paruh (1 half-life) berlalu, berapa aktivitas sumber dibanding aktivitas awal?',
   '["Sepertiga (33%) dari aktivitas awal","Tetap sama (100%)","Separuh (50%) dari aktivitas awal","Nol (sumber habis)"]', 2,
   'Definisi half-life: setelah t = t½, A = A0·e^(-0.693) = A0·0.5. Aktivitas turun tepat menjadi separuh. Sumber tidak pernah benar-benar habis seketika; ia meluruh secara eksponensial.', 'Source Decay', 'easy'),
  ('Dengan sumber 100 Ci waktu eksposur 60 detik. Setelah sumber meluruh ke 75.5 Ci, berapa kira-kira waktu eksposur baru untuk density yang sama?',
   '["≈45 detik","≈60 detik (tidak berubah)","≈120 detik","≈80 detik"]', 3,
   'Waktu eksposur baru = waktu lama · (A_lama/A_baru) = 60 · (100/75.5) = 60 · 1.325 ≈ 79.5 ≈ 80 detik. Aktivitas turun → waktu eksposur harus dinaikkan agar density tetap dalam batas.', 'Source Decay', 'hard'),
  ('Menurut ASME V, rentang density (optical density) yang dapat diterima pada area of interest untuk radiografi GAMMA adalah:',
   '["1.8 – 4.0","2.0 – 4.0","1.0 – 2.5","0.5 – 1.8"]', 1,
   'ASME V: gamma 2.0–4.0; X-ray 1.8–4.0. Density minimum gamma ditetapkan lebih tinggi (2.0) dibanding X-ray (1.8). Pilihan 1.8–4.0 adalah batas untuk X-ray, bukan gamma.', 'Density Control', 'medium'),
  ('Bagaimana cara yang benar memverifikasi densitometer setiap hari sebelum dipakai?',
   '["Membandingkan dua film acak satu sama lain","Cukup mengganti baterai dan menyalakannya","Membaca calibrated step wedge (NIST-traceable) dan membandingkan dengan nilai tersertifikat dalam toleransi","Mengukur ketebalan benda uji dengan caliper"]', 2,
   'Verifikasi harian densitometer dilakukan dengan calibrated/NIST-traceable step wedge: setiap step punya nilai density tersertifikat dan pembacaan harus dalam toleransi (umumnya ±0.05 D). Kalibrasi formal dilakukan tahunan oleh lab terkalibrasi.', 'Densitometer Calibration', 'medium'),
  ('Standar mana yang dipakai untuk verifikasi basic spatial resolution (SRb) pada sistem radiografi digital (CR/DR)?',
   '["ASTM E747 — wire IQI","ASTM E1025 — hole-type/plaque IQI","ASME VIII Division 1","ASTM E2002 — duplex-wire IQI"]', 3,
   'SRb pada sistem digital diverifikasi dengan duplex-wire IQI per ASTM E2002. E747 = wire IQI dan E1025 = hole-type IQI (keduanya untuk sensitivitas, bukan SRb); ASME VIII adalah code konstruksi pressure vessel, bukan standar IQI.', 'IQI & SRb', 'hard'),
  ('Manakah kombinasi tanggung jawab yang TEPAT antara Level II dan RSO dalam QC?',
   '["Level II menangani QC kualitas citra (density, IQI, densitometer); RSO menangani leak test sumber & kalibrasi survey meter keselamatan","Level II melakukan leak test sumber dan sign-off keselamatan radiasi","RSO yang menentukan waktu eksposur dan membaca radiograf","Level II dan RSO punya tugas identik tanpa pembagian"]', 0,
   'Level II bertanggung jawab QC teknis kualitas citra. Tugas keselamatan radiasi seperti leak test sumber dan kalibrasi survey meter adalah domain RSO yang butuh lisensi terpisah. Level II tidak boleh sign-off leak test sumber.', 'Audit & Roles', 'easy'),
  ('Berapa density variation yang diperbolehkan melalui area of interest menurut ASME V (single-film viewing)?',
   '["±5% dari density minimum","-15% / +30% dari density yang terbaca di sebelah IQI","-30% / +15% dari density di lokasi IQI","±50% bebas selama dalam 1.8–4.0"]', 1,
   'ASME V mengizinkan density variation -15% / +30% relatif terhadap density yang terbaca di sebelah benda IQI untuk single-film viewing. Ini memastikan keseragaman sensitivitas di seluruh area of interest. Tanda dan besarannya tidak boleh dibalik (-30%/+15% salah).', 'Density Control', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 12 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 13 — Reporting & Archive Management (5 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Anatomi laporan RT yang sah', '{"slides":[{"heading":"Mengapa laporan = produk akhir RT","body":"Bagi klien dan auditor, deliverable RT bukan radiograf-nya melainkan LAPORAN yang menyatakan accept/reject beserta bukti. Laporan RT Level II adalah dokumen quality record yang menjadi dasar keputusan rekayasa (use-as-is/perbaiki/scrap) dan bukti compliance saat audit ASME, third-party, atau client. Karena itu laporan harus traceable, lengkap, dan ditandatangani personel bersertifikat sesuai written practice (SNT-TC-1A / CP-189). Laporan yang ambigu atau tidak lengkap dapat menjadi temuan/NCR (non-conformance) meski radiografnya sempurna — bukti teknis yang baik tetap perlu dokumentasi yang sah."},{"heading":"Elemen wajib laporan (per ASME V Art 2 / ISO 17636)","body":"Minimal harus memuat: identifikasi proyek/klien/PO, identifikasi benda uji & weld (weld map / joint ID), material & ketebalan nominal, prosedur & revisi yang dipakai, sumber/peralatan (mis. Ir-192 t½≈74 hari, atau X-ray kVp/mA) + nomor seri & tanggal kalibrasi, teknik (SWSI/DWSI/DWDI/panoramic, SFD/SOD), parameter eksposur, IQI yang dipakai + sensitivitas tercapai (wire E747 essential / hole-type E1025 2-2T) atau SRb (duplex E2002) untuk digital, density terbaca (film) atau SNR (digital), kriteria penerimaan (kode + acceptance level), hasil per joint, serta nama/level/tanda tangan & tanggal personel."},{"heading":"Density & SRb harus tercatat sebagai bukti kualitas","body":"Untuk film, laporan mencantumkan density area of interest yang harus berada dalam rentang ASME V Art 2: sinar-X 1.8-4.0, gamma 2.0-4.0, dengan variasi density yang diizinkan -15%/+30% terhadap density yang terbaca di lokasi IQI. Untuk digital (DR/CR), pengganti density adalah SNR/SNRnorm dan basic spatial resolution (SRb, µm, dibaca via duplex-wire E2002) — bukan density optik. Mencantumkan angka aktual (mis. ''density 2.6, IQI hole-type 2-2T terbaca'') memberi bukti objektif bahwa radiograf memenuhi syarat dan keputusan accept/reject berbasis citra yang valid."},{"heading":"Disposisi & rujukan kode yang eksplisit","body":"Setiap indikasi yang dilaporkan harus dirujuk ke klausa acceptance yang tepat: ASME VIII / B31 untuk pressure equipment, AWS D1.1 Clause 8 untuk struktural, API 1104 untuk pipeline, atau ISO 10675 acceptance level. Ingat acceptance level kontrak menentukan hasil — indikasi sama bisa accept di ISO 10675-1 Level 2 (lebih longgar) tetapi reject di Level 1 (lebih ketat). Crack / lack of fusion / incomplete penetration umumnya rejectable hampir tanpa memandang ukuran. Hasil ditulis tegas: ACC / REJ / REPAIR, bukan deskripsi mengambang."}]}', 460, NULL),
  (2, 'reading', 'Arsip digital & integritas citra', '{"slides":[{"heading":"Apa yang diarsipkan: raw full bit-depth wajib disimpan","body":"Pada RT digital, yang diarsip bukan hanya citra tampilan, tetapi DATA MENTAH (raw) full bit-depth. Citra DR/CR umumnya 12-16 bit (4096-65536 gray level); raw 16-bit wajib dipertahankan karena windowing/enhancement hanyalah lapisan tampilan — auditor harus bisa kembali ke data asli untuk mereproduksi keputusan. Menyimpan hanya hasil enhancement (mis. JPEG 8-bit) adalah pelanggaran integritas: data kuantitatif hilang, SNR tidak dapat diukur ulang, dan keputusan tidak dapat diverifikasi ulang."},{"heading":"Format & metadata (DICONDE)","body":"Standar de-facto arsip RT digital industri adalah DICONDE (Digital Imaging and Communication in Nondestructive Evaluation, ASTM E2339) — adaptasi DICOM medis untuk NDE. DICONDE membungkus citra + metadata terstruktur (operator, peralatan, parameter eksposur, prosedur, timestamp, kalibrasi) dalam satu file sehingga citra tidak pernah terpisah dari konteksnya. Ini mencegah ''citra yatim'' tanpa identitas dan mempermudah audit trail otomatis. Format proprietary vendor sebaiknya dapat diekspor ke format terbuka/terdokumentasi agar tidak terkunci vendor (vendor lock-in)."},{"heading":"Integritas: hash, write-once, dan larangan editing","body":"Integritas arsip dijaga dengan: checksum/hash (mis. SHA-256) per file untuk mendeteksi perubahan, media/penyimpanan write-once atau WORM, dan kontrol akses berbasis peran (role-based). Post-processing untuk interpretasi tidak boleh menghapus atau menutupi indikasi; parameter pemrosesan harus terdokumentasi & reproducible (ASME V, ISO 17636-2). Setiap koreksi laporan dilakukan via revisi terkontrol (versi baru + alasan), BUKAN menimpa file asli. Prinsipnya: data asli abadi, perubahan selalu meninggalkan jejak."},{"heading":"Backup, redundansi & keterbacaan jangka panjang","body":"Karena retention bisa bertahun-tahun (lihat step berikut), arsip butuh strategi 3-2-1 (3 salinan, 2 jenis media berbeda, 1 off-site) dan migrasi media berkala agar tidak korup/usang. Risiko nyata: media optik/HDD degradasi, format/software obsolet, dan kehilangan kunci dekripsi. Inspektur Level II ikut memastikan citra lama masih dapat dibuka dengan software yang tersedia. Untuk film konvensional, arsip fisik butuh kontrol suhu/kelembapan & perlindungan dari cahaya agar tidak fading."}]}', 480, NULL),
  (3, 'reading', 'Retensi & traceability (mata rantai bukti)', '{"slides":[{"heading":"Berapa lama disimpan: kode + kontrak","body":"Periode retensi ditentukan oleh kode DAN persyaratan klien — mana yang lebih lama berlaku. Kode konstruksi umumnya mewajibkan radiograf & record disimpan sampai penerbitan sertifikat/Manufacturer''s Data Report, lalu retensi lanjutan sesuai kode/edisi, sementara banyak klien pressure equipment / pipeline minta retensi sepanjang usia aset (lifetime) — bisa puluhan tahun. Aturan praktis Level II: JANGAN PERNAH membuang radiograf/record tanpa otorisasi tertulis dan tanpa memverifikasi periode retensi yang berlaku."},{"heading":"Traceability: dari heat number ke radiograf","body":"Traceability berarti setiap radiograf dapat ditelusuri kembali ke joint fisik, ke welder/WPS, ke material (heat/lot number), dan ke instrumen yang dipakai. Mekanismenya: weld map / isometric drawing yang menomori tiap joint, penanda timbal (lead markers) pada film yang mencantumkan joint ID + tanggal + orientasi, location markers untuk menjamin coverage, dan log book yang menautkan nomor radiograf ke nomor joint. Tanpa traceability, sebuah indikasi tidak bisa dikaitkan ke lokasi nyata — laporan kehilangan nilai hukum & teknisnya."},{"heading":"Audit trail: who-what-when tidak boleh putus","body":"Audit trail adalah catatan kronologis tak-terputus: siapa mengambil eksposur, siapa menafsir, siapa menyetujui, kapan, dengan peralatan/kalibrasi apa, dan setiap perubahan/revisi laporan beserta alasannya. Pada sistem digital ini idealnya otomatis (log sistem + timestamp + user ID). Audit trail menjawab pertanyaan auditor: ''Buktikan keputusan accept ini dibuat oleh Level II bersertifikat, dengan radiograf yang memenuhi density/SRb, terhadap acceptance level yang benar.'' Mata rantai bukti yang putus = temuan audit (finding)."}]}', 440, NULL),
  (4, 'reading', 'NCR, koreksi & kesiapan audit', '{"slides":[{"heading":"Menangani reject: NCR & alur repair","body":"Saat sebuah joint reject, Level II menerbitkan/mendukung Non-Conformance Report (NCR) yang menautkan radiograf, indikasi, klausa acceptance yang dilanggar, dan disposisi (repair / reject / use-as-is via engineering). Setelah repair, weld di-RT ulang (re-shoot) dan radiograf repair diberi penanda ''R1'', ''R2'' dst untuk membedakan dari shoot awal. Riwayat repair tidak boleh dihapus — justru disimpan sebagai bagian audit trail. Batas jumlah repair pada lokasi sama dapat diatur kode/prosedur."},{"heading":"Koreksi laporan dilakukan secara terkontrol","body":"Bila laporan keliru (mis. salah joint ID, salah density), koreksi TIDAK dilakukan dengan menimpa diam-diam. Terbitkan revisi: naikkan nomor revisi, catat apa yang diubah, alasan, oleh siapa, kapan, dan simpan versi lama. Pada record kertas, koreksi memakai single-line strike-through + paraf + tanggal (tidak menghapus/tipp-ex) sesuai Good Documentation Practice. Prinsip ALCOA: data harus Attributable, Legible, Contemporaneous, Original, Accurate — relevan untuk record QA RT."},{"heading":"Peran Level II dalam audit & data review","body":"Level II co-works dengan QA/QC dan auditor: menyiapkan paket dokumen (prosedur + sertifikat personel + record kalibrasi sumber/densitometer + radiograf + laporan), melakukan film/data review (verifikasi density/SRb, IQI, coverage, marker), dan menjawab pertanyaan teknis. Catatan penting: tugas RSO (lisensi, dose record petugas — batas okupasi 20 mSv/thn rata-rata 5 thn, izin sumber radioaktif) TERPISAH dan butuh lisensi RSO sendiri — Level II hanya mendukung, bukan menggantikan. Kesiapan audit = arsip rapi, traceable, dan retensi terjaga setiap saat, bukan dadakan."}]}', 420, NULL),
  (5, 'quiz', 'Mini-quiz — Reporting & Archive Management', '{"description":"9 soal: elemen wajib laporan RT, density/SRb sebagai bukti, arsip digital (raw 16-bit, DICONDE, integritas), retensi & traceability, audit trail, marker/coverage, serta NCR/koreksi terkontrol.","questionCount":9,"passingScore":75}', 680, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 13
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 13 mini-quiz (9 questions, step 5)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 13 AND ls."orderIndex" = 5 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Mengapa laporan (report), bukan radiografnya sendiri, dianggap deliverable/produk akhir RT bagi klien dan auditor?',
   '["Karena laporan adalah quality record bertanda tangan personel bersertifikat yang menyatakan accept/reject beserta bukti, menjadi dasar keputusan rekayasa serta compliance audit","Karena radiograf tidak punya nilai teknis sama sekali setelah eksposur selesai","Karena klien tidak pernah diizinkan melihat radiograf asli","Karena laporan menggantikan kebutuhan akan prosedur dan kriteria penerimaan"]', 0,
   'Radiograf adalah bukti pendukung, tetapi keputusan accept/reject dan compliance dibuktikan melalui laporan yang ditandatangani personel bersertifikat. Laporan inilah quality record yang dipakai untuk keputusan rekayasa (use-as-is/perbaiki/scrap) dan saat audit. Radiograf tetap punya nilai teknis dan tetap diarsip; laporan tidak menggantikan prosedur maupun kriteria penerimaan.', 'Pelaporan RT', 'easy'),
  ('Manakah yang BUKAN merupakan elemen wajib pada laporan RT menurut ASME V Article 2 / ISO 17636?',
   '["IQI yang dipakai dan sensitivitas yang tercapai (mis. wire E747 essential atau hole-type E1025 2-2T)","Nomor seri & tanggal kalibrasi peralatan/sumber yang digunakan","Opini pribadi inspektur tentang etos kerja welder tanpa rujukan kode atau acceptance level","Kriteria penerimaan (kode + acceptance level) dan hasil accept/reject per joint"]', 2,
   'Laporan harus berisi data objektif dan traceable: identifikasi benda uji, prosedur, peralatan/sumber + kalibrasi, teknik & parameter, IQI/sensitivitas atau SRb, density/SNR, kriteria penerimaan, dan hasil per joint dengan tanda tangan bersertifikat. Opini subjektif tanpa rujukan kode bukan elemen laporan yang sah dan justru melemahkan nilai dokumen.', 'Pelaporan RT', 'easy'),
  ('Pada laporan RT film, density area of interest harus dicatat. Berapa rentang density yang benar menurut ASME V Article 2 dan berapa variasi density yang diizinkan terhadap lokasi IQI?',
   '["Keduanya 1.0-2.0; variasi bebas selama IQI terbaca","Sinar-X 2.0-4.0 dan gamma 1.8-4.0; variasi -30%/+15%","Sinar-X 1.8-4.0 dan gamma 2.0-4.0; variasi density -15%/+30% terhadap density di lokasi IQI","Density tidak relevan untuk film; cukup catat SNR dan SRb"]', 2,
   'ASME V Art 2 menetapkan density area of interest: sinar-X 1.8-4.0 dan gamma 2.0-4.0, dengan variasi density yang diizinkan -15%/+30% terhadap density yang terbaca di lokasi IQI. Mencantumkan angka density aktual memberi bukti objektif kualitas radiograf. SNR/SRb adalah pengganti density untuk RT digital, bukan untuk film. Opsi yang menukar rentang X-ray/gamma atau membalik variasi (-30%/+15%) adalah distraktor klasik.', 'Bukti kualitas', 'medium'),
  ('Untuk RT digital (DR/CR), data apa yang WAJIB diarsipkan dan mengapa menyimpan hanya hasil enhancement 8-bit dianggap pelanggaran integritas?',
   '["Cukup simpan JPEG 8-bit hasil windowing karena ukurannya kecil dan sudah cukup untuk audit","Wajib simpan hanya screenshot layar operator saat interpretasi","Cukup simpan parameter eksposur tanpa citra apa pun","Wajib simpan data mentah (raw) full bit-depth 16-bit; enhancement hanya lapisan tampilan, sehingga data kuantitatif harus dipertahankan agar keputusan dapat direproduksi auditor"]', 3,
   'Citra digital 12-16 bit (4096-65536 gray level) menyimpan informasi kuantitatif; raw 16-bit wajib dipertahankan karena windowing/enhancement hanyalah tampilan. Menyimpan hanya JPEG 8-bit menghilangkan data, membuat SNR tak terukur ulang dan keputusan tak dapat diverifikasi — pelanggaran integritas. Parameter saja atau screenshot tidak menggantikan data citra mentah.', 'Arsip digital', 'medium'),
  ('Apa fungsi utama DICONDE (ASTM E2339) dalam pengarsipan RT digital?',
   '["Sebuah kode acceptance level baru yang menggantikan ISO 10675","Algoritma enhancement otomatis yang menghapus noise dari radiograf","Standar format yang membungkus citra bersama metadata terstruktur (operator, peralatan, parameter, timestamp, kalibrasi) agar citra tidak pernah terpisah dari konteksnya","Protokol enkripsi yang membuat citra tidak bisa dibuka oleh auditor"]', 2,
   'DICONDE (adaptasi DICOM medis untuk NDE, ASTM E2339) adalah standar yang menyatukan citra + metadata terstruktur dalam satu file, mencegah ''citra yatim'' tanpa identitas dan mendukung audit trail otomatis. Ia bukan acceptance level, bukan algoritma enhancement, dan tujuannya justru memudahkan akses/audit, bukan mengunci citra.', 'Arsip digital', 'medium'),
  ('Saat sebuah laporan RT yang sudah diterbitkan ternyata keliru (salah joint ID), tindakan koreksi yang benar adalah:',
   '["Menimpa file/laporan asli secara diam-diam agar tidak ada yang tahu ada kesalahan","Menghapus laporan lama sepenuhnya lalu membuat laporan baru tanpa referensi apa pun","Menggunakan tipp-ex/correction fluid agar terlihat rapi","Menerbitkan revisi terkontrol (nomor revisi naik, catat apa yang diubah, alasan, oleh siapa, kapan) dan menyimpan versi lama; pada kertas pakai single-line strike-through + paraf + tanggal"]', 3,
   'Koreksi harus terkontrol dan meninggalkan jejak (prinsip ALCOA & Good Documentation Practice): terbitkan revisi dengan riwayat perubahan, simpan versi lama, dan pada record kertas gunakan single-line strike-through + paraf + tanggal. Menimpa diam-diam, menghapus total, atau memakai tipp-ex menghancurkan audit trail dan integritas data.', 'Koreksi & NCR', 'medium'),
  ('Berapa lama radiograf dan record RT harus disimpan (retensi), dan apa aturan praktis bagi Level II?',
   '["Selalu tepat 1 tahun, lalu boleh dibuang oleh siapa saja","Ditentukan oleh kode DAN persyaratan klien — mana yang lebih lama; jangan pernah membuang record tanpa otorisasi tertulis dan tanpa memverifikasi periode retensi yang berlaku","Tidak ada aturan retensi; record boleh dibuang segera setelah laporan ditandatangani","Hanya klien yang menyimpan record; kontraktor RT tidak menyimpan apa pun"]', 1,
   'Periode retensi ditentukan kode konstruksi (mis. ASME) dan kontrak klien, dengan periode yang lebih panjang yang berlaku — banyak aset pressure/pipeline menuntut retensi seumur hidup aset (puluhan tahun). Aturan praktis Level II: jangan pernah membuang radiograf/record tanpa otorisasi tertulis dan verifikasi retensi. Periode 1 tahun tetap atau ''tanpa aturan'' keliru.', 'Retensi', 'medium'),
  ('Pada film RT, lead markers (joint ID + tanggal + orientasi) dan location markers terutama berfungsi untuk:',
   '["Meningkatkan density film sehingga IQI lebih mudah terbaca","Menjamin traceability tiap radiograf ke joint fisik serta membuktikan coverage area yang diperiksa","Menggantikan kebutuhan IQI dalam penilaian kualitas citra","Mengurangi dosis radiasi yang diterima operator selama eksposur"]', 1,
   'Lead markers menautkan radiograf ke joint/tanggal/orientasi (traceability), sedangkan location markers (ditempatkan pada benda uji, bukan film) membuktikan bahwa seluruh panjang yang disyaratkan benar-benar tercakup (coverage) tanpa gap atau overlap yang tidak terdokumentasi. Marker tidak mengubah density, tidak menggantikan IQI, dan tidak terkait proteksi radiasi.', 'Traceability & audit', 'medium'),
  ('Dalam konteks audit RT, apa yang dimaksud traceability dan audit trail, dan mengapa keduanya kritis?',
   '["Traceability = kecepatan scanning CR; audit trail = jumlah frame averaging — keduanya hanya parameter teknis citra","Traceability hanya berlaku untuk RT digital, audit trail hanya untuk RT film","Keduanya adalah tugas eksklusif RSO dan tidak ada kaitannya dengan Level II","Traceability = kemampuan menelusuri tiap radiograf ke joint fisik, welder/WPS, heat number, dan instrumen; audit trail = catatan kronologis tak-terputus who-what-when termasuk revisi; tanpa keduanya laporan kehilangan nilai hukum & teknis"]', 3,
   'Traceability menautkan tiap radiograf ke joint fisik, welder/WPS, material (heat/lot), dan instrumen — diwujudkan lewat weld map, lead markers (joint ID/tanggal/orientasi), location markers, dan log book. Audit trail adalah rekaman kronologis tak-terputus (siapa shoot/interpret/approve, kapan, peralatan/kalibrasi, dan setiap revisi + alasan). Mata rantai yang putus menjadi temuan audit. Keduanya berlaku untuk film maupun digital dan merupakan bagian tugas Level II, terpisah dari tugas RSO.', 'Traceability & audit', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 13 AND ls."orderIndex" = 5 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 14 — RSO Awareness (non-RSO duties) (6 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Peran Level II vs RSO — batas tanggung jawab', '{"slides":[{"heading":"Level II co-work, bukan menggantikan RSO","body":"RT Level II bekerja BERSAMA RSO (Radiation Safety Officer / Petugas Proteksi Radiasi - PPR), bukan menggantikannya. Level II wajib paham prinsip proteksi radiasi (ALARA, dose limit, survey, boundary) agar bisa bekerja aman dan mengisi log, TAPI tugas berlisensi RSO (manajemen program proteksi, izin BAPETEN, kalibrasi resmi, audit regulasi) adalah jabatan terpisah dengan lisensi/SIB (Surat Izin Bekerja) tersendiri."},{"heading":"Yang BOLEH dilakukan Level II","body":"Mengoperasikan kamera gamma/X-ray sesuai prosedur, memakai dosimeter (TLD/OSL badge + pocket/electronic dosimeter + alarming ratemeter), melakukan survey area kerja sebelum/saat/sesudah exposure, menegakkan boundary, mencatat dosis di logbook, dan menghentikan pekerjaan bila ada anomali radiasi."},{"heading":"Yang menjadi DOMAIN RSO (terpisah)","body":"Penyusunan & pengesahan program proteksi radiasi, pengurusan izin pemanfaatan sumber ke regulator (BAPETEN di Indonesia / NRC sebagai analog), kalibrasi resmi survey meter, leak test sumber terjadwal, investigasi insiden formal, pelaporan ke regulator, dan training/otorisasi pekerja radiasi. Level II MENDUKUNG tugas ini, tidak menandatanganinya."},{"heading":"Regulatory understanding minimum","body":"Level II harus tahu acuan: dose limit pekerja 20 mSv/tahun (ICRP, rata-rata 5 tahun; maks 50 mSv di satu tahun mana pun), publik 1 mSv/tahun, boundary restricted/controlled area 2 mR/h (0,02 mSv/h), high-radiation area 100 mR/h. Pengetahuan ini menjaga Level II tetap compliant tanpa harus memegang lisensi RSO."}]}', 460, NULL),
  (2, 'reading', 'ALARA & prinsip time-distance-shielding', '{"slides":[{"heading":"ALARA — As Low As Reasonably Achievable","body":"Filosofi inti proteksi radiasi: tekan dosis serendah mungkin secara wajar dengan mempertimbangkan faktor ekonomi & sosial. Bukan sekadar ''di bawah limit'' — tapi berupaya aktif meminimalkan. Tiga pilar praktis: WAKTU, JARAK, PERISAI (time-distance-shielding)."},{"heading":"WAKTU — dosis proporsional waktu paparan","body":"Dosis total = laju dosis x waktu. Mengurangi waktu di dekat sumber menjadi separuh = dosis separuh. Praktik: rencanakan setup sebelum sumber di-crank out, latih gerakan, jangan berlama-lama di restricted area. Crank-out hanya saat film/detektor benar-benar siap."},{"heading":"JARAK — inverse-square law I ∝ 1/d²","body":"Intensitas turun dengan kuadrat jarak. Menggandakan jarak (d) = intensitas menjadi 1/4. Contoh: pada 1 m laju 100 mR/h, maka pada 2 m menjadi 25 mR/h, pada 4 m menjadi 6,25 mR/h. JARAK adalah pelindung paling murah & efektif — selalu maksimalkan, gunakan crank/remote sepanjang mungkin."},{"heading":"PERISAI — HVL & TVL","body":"HVL (Half-Value Layer) = tebal perisai yang menurunkan intensitas menjadi 50%. TVL (Tenth-Value Layer) = menjadi 10% (≈3,3 HVL). Untuk Ir-192 dalam timbal HVL ≈ 4,8 mm, untuk Co-60 (energi lebih tinggi → butuh perisai lebih tebal) HVL ≈ 12 mm. Collimator mengarahkan dan membatasi berkas sehingga dosis di sekeliling turun."}]}', 480, NULL),
  (3, 'reading', 'Survey meter, dosimetri & boundary area', '{"slides":[{"heading":"Survey meter (ratemeter)","body":"Mengukur laju dosis (mR/h atau µSv/h) secara real-time. WAJIB diperiksa: baterai, kalibrasi masih berlaku (sticker), dan response/battery check dengan check source sebelum kerja. Survey dilakukan SEBELUM masuk area, MENGELILINGI boundary saat exposure, dan SETELAH retract untuk memastikan sumber kembali ke posisi shielded (full retract)."},{"heading":"Dosimetri personal — tiga lapis","body":"1) TLD/OSL badge = catatan dosis legal kumulatif (dibaca berkala oleh lab, bukan real-time). 2) Pocket/electronic dosimeter = pembacaan dosis langsung di lapangan. 3) Alarming ratemeter = alarm audio bila laju dosis melebihi ambang. Ketiganya saling melengkapi; jangan pernah masuk area tanpa monitoring aktif."},{"heading":"Boundary & klasifikasi area","body":"Restricted/controlled area boundary ditetapkan di garis 2 mR/h (0,02 mSv/h) — diberi barrier, rope, dan tanda radiasi. High-radiation area = ≥100 mR/h, butuh kontrol akses ketat. Boundary dihitung dari laju dosis hasil survey + inverse-square, lalu diverifikasi dengan survey aktual saat sumber out. Tidak boleh ada personel tak berkepentingan di dalam boundary."},{"heading":"Survey adalah verifikasi, bukan asumsi","body":"Jangan pernah mengandalkan posisi indikator ''safe'' pada kamera saja. Survey meter harus mengonfirmasi laju dosis turun ke background saat sumber diasumsikan ter-retract. Banyak insiden source-stuck terdeteksi justru karena survey rutin pasca-exposure — bukan dari mekanisme/indikator kamera."}]}', 500, NULL),
  (4, 'reading', 'Decay sumber & implikasi waktu paparan', '{"slides":[{"heading":"Peluruhan sumber A = A0·e^(-0,693·t/t½)","body":"Aktivitas sumber menurun eksponensial. Half-life: Ir-192 ≈ 74 hari, Co-60 ≈ 5,27 tahun, Se-75 ≈ 120 hari. Ir-192 ''habis'' relatif cepat sehingga waktu eksposur memanjang seiring usia sumber — ini berpengaruh pada perencanaan dosis (waktu lebih lama = manajemen ALARA lebih ketat)."},{"heading":"Output / RHM (laju dosis per Ci pada 1 m)","body":"RHM (roentgen per hour at 1 m per Ci): Ir-192 ≈ 0,48-0,59, Co-60 ≈ 1,3-1,4, Se-75 ≈ 0,2. Laju dosis pada 1 m ≈ RHM x aktivitas (Ci). Contoh Ir-192 50 Ci: ≈ 0,5 x 50 = 25 R/h pada 1 m — sangat berbahaya; itulah sebabnya boundary & jarak menjadi kritikal."},{"heading":"Hubungan decay → boundary","body":"Karena aktivitas berubah seiring waktu, laju dosis dan jarak boundary juga berubah. Level II harus survey ulang dan menghitung boundary berdasarkan aktivitas SAAT INI, bukan aktivitas nominal sumber baru. Source decay chart/kurva membantu estimasi, tetapi survey aktual tetap penentu akhir."},{"heading":"Se-75 untuk akses & material tipis","body":"Se-75 energi lebih rendah (output ≈0,2 RHM), cocok untuk material tipis & memberi kontras baik; boundary lebih kecil pada aktivitas setara → kadang dipilih untuk pekerjaan di ruang sempit demi ALARA. Co-60 energi tinggi untuk material tebal tapi butuh shielding & boundary jauh lebih besar."}]}', 440, NULL),
  (5, 'reading', 'Respon darurat: source-stuck & eskalasi ke RSO', '{"slides":[{"heading":"Skenario source-stuck (sumber tidak ter-retract)","body":"Tanda: setelah crank-in, survey meter MASIH membaca laju dosis tinggi di sekitar guide tube/kamera, dan alarm ratemeter berbunyi. JANGAN dekati sumber. Tetapkan ulang boundary yang diperluas, larang akses, dan mulai protokol darurat. Ini adalah situasi paling berbahaya dalam radiografi industri."},{"heading":"Langkah segera Level II","body":"1) Jangan panik, jangan sentuh/mendekat. 2) Tingkatkan jarak (inverse-square = pelindung tercepat). 3) Survey dan perluas boundary sampai <2 mR/h. 4) Isolasi area, pasang barrier & tanda. 5) Hentikan semua aktivitas. 6) SEGERA hubungi RSO — penanganan recovery sumber adalah tugas RSO/qualified, BUKAN Level II sendiri."},{"heading":"Mengapa eskalasi ke RSO wajib","body":"Recovery sumber stuck butuh peralatan khusus (shielded container, remote tools), perhitungan dosis ketat, dan otorisasi regulator. RSO memegang lisensi & prosedur kedaruratan resmi serta wajib lapor ke BAPETEN/regulator. Level II yang mencoba recovery sendiri melanggar batas peran dan berisiko over-exposure fatal."},{"heading":"Dokumentasi insiden & dosis","body":"Catat: waktu kejadian, pembacaan survey, dosis personal (pocket/electronic + TLD untuk konfirmasi lab), jarak & tindakan yang diambil. Data ini diserahkan ke RSO untuk laporan formal & investigasi. Disiplin pencatatan dosis melindungi pekerja secara legal dan mendukung audit trail proteksi radiasi."}]}', 480, NULL),
  (6, 'quiz', 'Mini-quiz — RSO Awareness (non-RSO duties)', '{"description":"6 soal: peran Level II vs RSO, dose limit, time-distance-shielding (inverse-square), survey/dosimetri, boundary area, decay & respon source-stuck.","questionCount":6,"passingScore":75}', 660, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 14
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 14 mini-quiz (6 questions, step 6)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 14 AND ls."orderIndex" = 6 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Manakah pernyataan yang TEPAT tentang hubungan RT Level II dengan RSO?',
   '["Level II bekerja sama dengan RSO dan memahami proteksi radiasi, tetapi tugas berlisensi RSO terpisah","Level II menggantikan RSO ketika RSO tidak hadir di lokasi","Level II otomatis memegang lisensi RSO setelah lulus sertifikasi Level II","Level II tidak perlu memahami proteksi radiasi karena itu sepenuhnya tugas RSO"]', 0,
   'Level II co-work dengan RSO: wajib paham ALARA, dose limit, survey, dan boundary agar aman, tetapi tugas berlisensi RSO (program proteksi, izin regulator, recovery sumber, pelaporan formal) adalah jabatan terpisah dengan lisensi/SIB tersendiri. Sertifikasi Level II tidak memberikan lisensi RSO.', 'Peran & Regulasi', 'easy'),
  ('Berdasarkan acuan ICRP, batas dosis okupasional untuk pekerja radiasi adalah:',
   '["1 mSv/tahun, sama dengan limit publik","50 mSv/tahun setiap tahun tanpa di-rata-rata","20 mSv/tahun (rata-rata 5 tahun) dengan maksimum 50 mSv di satu tahun mana pun","100 mSv/tahun untuk semua kondisi kerja rutin"]', 2,
   'ICRP menetapkan dose limit okupasional 20 mSv/tahun di-rata-rata selama 5 tahun, dengan batas tidak melebihi 50 mSv pada satu tahun mana pun. Limit untuk publik jauh lebih rendah, yaitu 1 mSv/tahun.', 'Dose Limit', 'medium'),
  ('Pada jarak 1 m laju dosis terukur 100 mR/h. Berdasarkan inverse-square law, berapa laju dosis pada jarak 4 m?',
   '["50 mR/h","25 mR/h","12,5 mR/h","6,25 mR/h"]', 3,
   'I ∝ 1/d². Pada 4 m, faktor = 1/4² = 1/16. Maka 100 mR/h ÷ 16 = 6,25 mR/h. Inilah sebabnya memaksimalkan jarak adalah pelindung paling efektif dan murah.', 'Time-Distance-Shielding', 'medium'),
  ('Saat exposure, boundary restricted/controlled area umumnya ditetapkan pada garis laju dosis berapa?',
   '["2 mR/h (0,02 mSv/h)","100 mR/h (1 mSv/h)","0,1 mR/h, sama dengan background","1000 mR/h"]', 0,
   'Boundary restricted/controlled area ditetapkan pada 2 mR/h (0,02 mSv/h) dan diberi barrier serta tanda radiasi. Area dengan laju ≥100 mR/h diklasifikasikan sebagai high-radiation area dengan kontrol akses lebih ketat.', 'Boundary Area', 'easy'),
  ('Tiga lapis monitoring personal pada radiografer yang benar adalah:',
   '["Survey meter, film badge X-ray, dan IQI","TLD/OSL badge, pocket/electronic dosimeter, dan alarming ratemeter","Hanya TLD/OSL badge karena sudah mencatat dosis legal kumulatif","Collimator, guide tube, dan check source"]', 1,
   'Monitoring personal terdiri dari tiga lapis komplementer: TLD/OSL badge (dosis legal kumulatif dibaca lab), pocket/electronic dosimeter (pembacaan langsung di lapangan), dan alarming ratemeter (alarm bila laju dosis melebihi ambang). IQI dan collimator adalah perangkat radiografi/kualitas citra, bukan dosimetri personal.', 'Dosimetri', 'medium'),
  ('Setelah crank-in, survey meter MASIH membaca laju dosis tinggi di sekitar guide tube dan alarm berbunyi (source-stuck). Tindakan Level II yang BENAR adalah:',
   '["Segera mendekat dan menarik sumber dengan tangan agar pekerjaan cepat selesai","Mengabaikannya karena indikator kamera menunjukkan posisi safe","Menjauh untuk menambah jarak, perluas boundary, isolasi area, dan SEGERA hubungi RSO","Melanjutkan exposure berikutnya sambil menunggu pembacaan turun dengan sendirinya"]', 2,
   'Pada source-stuck: jangan mendekat, maksimalkan jarak (inverse-square sebagai pelindung tercepat), survey & perluas boundary hingga <2 mR/h, isolasi area, hentikan aktivitas, dan segera eskalasi ke RSO. Recovery sumber adalah tugas RSO/qualified dengan peralatan khusus, bukan Level II sendiri. Jangan pernah mengandalkan indikator kamera saja.', 'Respon Darurat', 'hard')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 14 AND ls."orderIndex" = 6 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 15 — Recap & Practice Exam (4 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'reading', 'Recap A — Digital RT, real-time & dosis', '{"slides":[{"heading":"DR vs CR vs film","body":"DR (Digital Radiography): flat panel detector menghasilkan citra langsung, review real-time, throughput tinggi, biaya peralatan tinggi (~$50k+). CR (Computed Radiography): imaging plate (photostimulable phosphor / storage phosphor) di-scan di reader terpisah; menjadi jembatan transisi dari film dengan biaya lebih rendah. Film: dynamic range terbatas dibanding digital namun masih banyak dipakai. Kunci kualitas digital: retain data raw 16-bit untuk audit dan re-evaluasi (jangan simpan hanya hasil kompresi)."},{"heading":"Real-time imaging & frame averaging","body":"Real-time radioscopy dipakai untuk inspeksi online dan analisis gerak. Frame averaging menjumlahkan banyak frame untuk menekan random noise sehingga SNR naik kira-kira sebanding akar dari jumlah frame (mis. 4 frame -> SNR ~2x). Trade-off: averaging banyak frame memperlambat respon, sehingga objek bergerak menjadi blur. Geometri tetap tunduk pada Ug = F x OFD / SOD."},{"heading":"Unsharpness geometris & inverse-square","body":"Geometric/penumbra unsharpness Ug = F x OFD / SOD, dengan F = focal/source size, OFD = jarak objek ke film/detektor, SOD = jarak sumber ke objek. Untuk menurunkan Ug: perkecil F, rapatkan OFD (objek dekat detektor), dan perbesar SOD. Intensitas radiasi mengikuti hukum inverse-square: I sebanding 1/d^2 — menggandakan jarak menjadikan intensitas seperempatnya."},{"heading":"Decay sumber & exposure","body":"Aktivitas meluruh: A = A0 x e^(-0.693 t / t-setengah), dengan 0.693 = ln 2; aktivitas dinyatakan dalam Ci atau Bq. Half-life: Ir-192 ~74 hari, Co-60 ~5.27 tahun, Se-75 ~120 hari. Output RHM (R/jam per Ci pada 1 m): Ir-192 ~0.48-0.59, Co-60 ~1.3-1.4, Se-75 ~0.2. Karena Ir-192 meluruh relatif cepat, waktu pajan harus dinaikkan saat sumber menua agar densitas film tetap konsisten (energi foton tidak berubah, hanya aktivitas yang turun)."}]}', 480, NULL),
  (2, 'reading', 'Recap B — Teknik, kualitas citra & sizing', '{"slides":[{"heading":"Technique development & seleksi sumber","body":"Pemilihan sumber bergantung rentang tebal & material: X-ray untuk tipis sampai sedang (kontras terkendali, energi diatur kVp), Se-75 untuk tebal tipis-menengah (energi rendah, kontras baik), Ir-192 untuk tebal menengah, Co-60 untuk tebal sangat besar (energi foton tinggi, daya tembus besar). Penetrameter/IQI dipilih sesuai tebal: wire IQI (ASTM E747) atau hole-type/plaque (ASTM E1025); basic spatial resolution detektor digital (SRb) diukur dengan duplex-wire IQI ASTM E2002."},{"heading":"Densitas film & kualitas citra (ASME V)","body":"Densitas film ASME V: sinar-X 1.8-4.0, gamma 2.0-4.0. Variasi densitas melalui area of interest dibatasi -15% sampai +30% relatif terhadap densitas pada body area of interest di dekat IQI. Untuk RT digital, kontrol kualitas berbasis SNR, kontras, dan basic spatial resolution; gunakan filter, screen, dan parameter processing untuk optimasi tanpa membuang detail diagnostik. IQI sensitivity tetap wajib divisualisasikan untuk membuktikan kualitas citra."},{"heading":"Defect sizing & karakterisasi","body":"Panjang cacat diukur dari proyeksi pada citra; tinggi/through-wall diperkirakan dari perubahan densitas/grayscale dan teknik proyeksi (mis. multi-angle). Comparator chart dan IQI sensitivity membantu memastikan cacat sekecil yang disyaratkan masih terdeteksi. Bedakan indikasi linear (crack, lack of fusion, incomplete penetration) yang umumnya planar dan paling kritis, vs rounded (porosity, beberapa inclusion) karena kriteria penerimaannya berbeda per code."},{"heading":"Procedure development","body":"Prosedur tertulis Level II mencakup: scope, sumber & energi, geometri (SOD/OFD), IQI & sensitivity yang disyaratkan, film/detektor & processing, teknik (SWSI/DWSI/DWDI/panoramic), kriteria penerimaan per code, serta demonstrasi/kualifikasi. Prosedur harus dapat diaudit dan direproduksi oleh inspektor lain yang kompeten — bukan sekadar mengandalkan praktik terbaik tak tertulis."}]}', 460, NULL),
  (3, 'reading', 'Recap C — Code, QC, reporting & RSO awareness', '{"slides":[{"heading":"Interpretasi code","body":"ASME V Art 2 (teknik & IQI) dipasangkan dengan code konstruksi/acceptance: ASME VIII / B31 (pressure equipment & piping), AWS D1.1 Clause 8 (sambungan las struktural), API 1104 (pipeline), serta ISO 17636 (teknik RT) dan ISO 10675 (acceptance levels). Pahami perbedaan kriteria: API 1104 acceptance berbasis tebal dinding pipa; AWS D1.1 membedakan beban statik vs dinamik (siklik)."},{"heading":"Quality Control & audit","body":"QC harian: cek densitometer/step-wedge, kondisi sumber & kolimator, kalibrasi/fungsi survey meter. Berkala (mis. bulanan): density check, pemantauan decay sumber dengan memperbarui kurva A vs waktu (A = A0 e^(-0.693 t/t-setengah)). Semua dicatat untuk jejak audit. Penyimpangan ditindaklanjuti dengan corrective action sebelum produksi dilanjutkan."},{"heading":"Reporting & archive","body":"Laporan RT berisi identifikasi joint, teknik, IQI sensitivity, hasil interpretasi, dan disposisi (accept/reject/repair). Arsip digital retain data raw 16-bit, metadata, dan rekaman kalibrasi sesuai retensi code & klien. Audit trail memastikan setiap citra dapat ditelusuri ke sumber, operator, prosedur, dan tanggal."},{"heading":"RSO awareness (tugas non-RSO)","body":"Level II bekerja sama dengan RSO; tugas RSO (perizinan, kepatuhan regulasi, leak test sumber, penunjukan resmi) membutuhkan lisensi/penunjukan terpisah. Prinsip ALARA. Batas dosis okupasi 20 mSv/tahun (ICRP, dirata-rata 5 tahun; maks 50 mSv pada satu tahun); publik 1 mSv/tahun. Proteksi: time-distance-shielding, HVL/TVL. Monitoring: dosimeter pasif (TLD/OSL) + pocket/electronic dosimeter + ratemeter beralarm. Boundary restricted area 2 mR/jam (0.02 mSv/jam); high-radiation area 100 mR/jam."}]}', 460, NULL),
  (4, 'quiz', 'Practice Exam — RT Level II (30 soal)', '{"description":"Ujian latihan komprehensif mencakup modul 1-14 RT Level II: DR/CR & real-time, exposure & decay, dosis & proteksi radiasi, technique development, image quality, defect sizing, procedure, code interpretation, QC, serta reporting & archive.","questionCount":30,"passingScore":75}', 720, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 15
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 15 mini-quiz (30 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 15 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Rumus geometric unsharpness (Ug) yang benar adalah:',
   '["Ug = F x OFD / SOD","Ug = F x SOD / OFD","Ug = SOD x OFD / F","Ug = F + OFD - SOD"]', 0,
   'Ug = F x OFD / SOD, dengan F = ukuran focal/source, OFD = jarak objek ke film/detektor, SOD = jarak sumber ke objek.', 'Technique Development', 'easy'),
  ('Untuk menurunkan geometric unsharpness (Ug), langkah yang TEPAT adalah:',
   '["Memperbesar focal size","Memperbesar OFD","Memperbesar SOD","Memperkecil SOD"]', 2,
   'Ug = F x OFD / SOD. Memperbesar SOD menurunkan Ug. Memperbesar F atau OFD, atau memperkecil SOD, justru menaikkan Ug.', 'Technique Development', 'medium'),
  ('Intensitas radiasi terhadap jarak mengikuti hukum inverse-square. Jika jarak digandakan, intensitas menjadi:',
   '["Dua kali lipat","Setengahnya","Seperempatnya","Tetap sama"]', 2,
   'I sebanding 1/d^2. Menggandakan jarak (2d) membuat intensitas menjadi 1/(2^2) = 1/4 dari semula.', 'Radiation Safety', 'easy'),
  ('Half-life Ir-192 mendekati:',
   '["74 hari","120 hari","5.27 tahun","30 hari"]', 0,
   'Ir-192 memiliki half-life sekitar 74 hari. Se-75 ~120 hari dan Co-60 ~5.27 tahun.', 'Source & Decay', 'easy'),
  ('Persamaan peluruhan aktivitas sumber radioaktif adalah:',
   '["A = A0 x (1 - 0.693 t)","A = A0 x e^(+0.693 t / t-setengah)","A = A0 x e^(-0.693 t / t-setengah)","A = A0 / (0.693 x t)"]', 2,
   'A = A0 x e^(-0.693 t / t-setengah). Eksponen negatif menandakan peluruhan; 0.693 = ln 2. Peluruhan bersifat eksponensial, bukan linear.', 'Source & Decay', 'medium'),
  ('Mengapa waktu pajan (exposure) untuk kamera Ir-192 perlu dinaikkan seiring waktu tanpa mengganti sumber?',
   '["Karena half-life Ir-192 sangat panjang","Karena energi foton meningkat saat sumber menua","Karena aktivitas sumber meluruh sehingga output (laju dosis) berkurang","Karena densitas film naik dengan sendirinya"]', 2,
   'Aktivitas Ir-192 meluruh relatif cepat (t-setengah ~74 hari), sehingga laju dosis berkurang dan waktu pajan harus dinaikkan agar densitas film tetap konsisten. Energi foton tidak berubah.', 'Source & Decay', 'medium'),
  ('Output RHM (R/jam per Ci pada 1 m) yang paling tinggi di antara sumber berikut dimiliki oleh:',
   '["Co-60 (~1.3-1.4)","Ir-192 (~0.48-0.59)","Se-75 (~0.2)","Ketiganya sama"]', 0,
   'Co-60 memiliki RHM tertinggi (~1.3-1.4 R/jam per Ci pada 1 m), diikuti Ir-192 (~0.48-0.59), lalu Se-75 (~0.2).', 'Source & Decay', 'medium'),
  ('Rentang densitas film yang disyaratkan ASME V untuk radiografi gamma adalah:',
   '["1.5 - 3.0","1.8 - 4.0","2.0 - 4.0","2.5 - 5.0"]', 2,
   'ASME V: densitas gamma 2.0-4.0, sedangkan sinar-X 1.8-4.0.', 'Image Quality', 'easy'),
  ('Batas variasi densitas yang diizinkan ASME V melalui area of interest adalah:',
   '["-30% / +15%","-10% / +10%","-20% / +20%","-15% / +30%"]', 3,
   'ASME V mengizinkan variasi densitas -15% sampai +30% relatif terhadap densitas pada body area of interest di dekat IQI.', 'Image Quality', 'medium'),
  ('Perbedaan utama DR (Digital Radiography) dibanding CR (Computed Radiography) adalah:',
   '["DR menghasilkan citra langsung dari flat panel detector tanpa langkah scan terpisah","DR memakai imaging plate yang harus di-scan di reader terpisah","CR menghasilkan citra real-time langsung dari panel","DR hanya dapat memakai film"]', 0,
   'DR menggunakan flat panel detector yang menghasilkan citra langsung/real-time. CR memakai imaging plate (photostimulable phosphor) yang harus di-scan di reader terpisah.', 'Digital RT', 'easy'),
  ('Pada inspeksi digital, teknik frame averaging terutama berfungsi untuk:',
   '["Menaikkan energi foton sumber","Menurunkan SOD secara otomatis","Menekan random noise dan menaikkan SNR","Menggantikan fungsi IQI"]', 2,
   'Frame averaging menjumlahkan banyak frame sehingga random noise tertekan dan SNR meningkat (kira-kira sebanding akar jumlah frame).', 'Real-time Imaging', 'medium'),
  ('Kelemahan frame averaging dengan jumlah frame sangat banyak pada real-time imaging objek bergerak adalah:',
   '["SNR menurun drastis","Respon menjadi lambat sehingga objek bergerak menjadi kabur (motion blur)","Energi sumber ikut meningkat","IQI tidak lagi terbaca"]', 1,
   'Averaging banyak frame memperlambat respon; untuk objek bergerak hal ini menimbulkan motion blur, sehingga jumlah frame harus dikompromikan.', 'Real-time Imaging', 'hard'),
  ('Standar yang digunakan untuk mengukur basic spatial resolution (SRb) detektor digital dengan duplex wire adalah:',
   '["ASTM E747","ASTM E1025","ASTM E94","ASTM E2002"]', 3,
   'ASTM E2002 (duplex wire IQI) dipakai untuk mengukur basic spatial resolution (SRb). E747 = wire IQI, E1025 = hole-type IQI, E94 = guide RT.', 'Image Quality', 'hard'),
  ('IQI tipe hole-type (plaque) mengacu pada standar ASTM:',
   '["E2002","E94","E1025","E747"]', 2,
   'Hole-type (plaque) IQI mengacu ASTM E1025, sedangkan wire IQI mengacu E747 dan duplex-wire SRb mengacu E2002.', 'Image Quality', 'easy'),
  ('Untuk material dengan tebal sangat besar, sumber gamma yang paling sesuai karena energi foton tinggi adalah:',
   '["X-ray 100 kV","Se-75","Ir-192","Co-60"]', 3,
   'Co-60 memiliki energi foton paling tinggi sehingga cocok untuk tebal sangat besar; Se-75 dan Ir-192 untuk rentang tebal yang lebih kecil.', 'Technique Development', 'medium'),
  ('Indikasi radiografi yang bersifat LINEAR dan umumnya paling kritis adalah:',
   '["Crack / lack of fusion","Porosity tersebar","Slag inclusion membulat","Rounded indication kecil"]', 0,
   'Crack dan lack of fusion adalah indikasi linear/planar yang umumnya paling kritis; porosity dan banyak inclusion bersifat rounded.', 'Defect Sizing', 'easy'),
  ('Dalam defect sizing, perkiraan tinggi/through-wall sebuah cacat pada radiografi paling tepat dievaluasi dari:',
   '["Panjang proyeksi pada citra saja","Nomor seri IQI yang dipakai","Perubahan densitas/grayscale dan teknik proyeksi","Tanggal kalibrasi sumber"]', 2,
   'Tinggi/through-wall diperkirakan dari variasi densitas/grayscale dan teknik proyeksi (mis. multi-angle); panjang diukur dari proyeksi pada citra. RT memang lemah dalam menentukan through-wall dibanding UT.', 'Defect Sizing', 'hard'),
  ('Code yang khusus mengatur radiografi sambungan las pipeline dengan acceptance berbasis tebal dinding pipa adalah:',
