FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (1, 'quiz', 'FINAL ASSESSMENT — RT Level II', '{"description":"Ujian sertifikasi RT Level II — 60 soal · 120 menit · minimal 80% lulus.","questionCount":60,"passingScore":80}', 7200, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 16
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 16 mini-quiz (60 questions, step 1)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 16 AND ls."orderIndex" = 1 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Pada Digital Radiography (DR), detektor flat panel jenis ''direct'' menggunakan lapisan fotokonduktor yang umum berupa:',
   '["Cesium iodide (CsI)","Gadolinium oxysulfide (GdOS)","Amorphous silicon (a-Si)","Amorphous selenium (a-Se)"]', 3,
   'DR direct memakai fotokonduktor amorphous selenium (a-Se) yang langsung mengubah sinar-X menjadi muatan listrik tanpa tahap konversi cahaya. DR indirect memakai sintilator (CsI/GdOS) di atas array a-Si TFT.', 'DR', 'medium'),
  ('Pada DR indirect, urutan konversi sinyal yang benar adalah:',
   '["Sinar-X → muatan listrik langsung","Sinar-X → cahaya tampak (sintilator CsI) → muatan listrik (array a-Si)","Sinar-X → panas → muatan listrik","Sinar-X → laser → cahaya"]', 1,
   'DR indirect: sintilator (mis. CsI atau CsI+a-Si) mengubah sinar-X menjadi cahaya tampak, lalu fotodioda array amorphous silicon mengubah cahaya menjadi muatan listrik. Direct (a-Se) melewati tahap cahaya.', 'DR', 'medium'),
  ('Pada Computed Radiography (CR), media perekam citra adalah:',
   '["Film perak halida konvensional","Flat panel a-Si","Tabung intensifier","Imaging plate berbahan photostimulable phosphor (PSP)"]', 3,
   'CR menggunakan imaging plate fosfor photostimulable (PSP/storage phosphor). Energi sinar-X tersimpan dalam plate, lalu dibaca dengan laser scanner yang merangsang emisi cahaya (photostimulated luminescence).', 'CR', 'easy'),
  ('Proses pembacaan imaging plate CR setelah eksposur dilakukan dengan:',
   '["Pemanasan plate dalam oven","Pencelupan dalam developer kimia","Pemindaian laser yang merangsang pelepasan energi tersimpan menjadi cahaya","Penyinaran ulang dengan sinar-X dosis rendah"]', 2,
   'Reader CR memindai imaging plate dengan laser merah; energi laten yang tersimpan dilepas sebagai cahaya biru (photostimulated luminescence) yang ditangkap PMT dan didigitalkan. Plate lalu dihapus dengan cahaya terang untuk dipakai ulang.', 'CR', 'medium'),
  ('Keunggulan utama radiografi digital (DR/CR) dibanding film konvensional terkait pasca-pemrosesan adalah:',
   '["Tidak memerlukan IQI","Rentang dinamis lebar dan citra dapat diolah (windowing, kontras) tanpa eksposur ulang","Tidak terpengaruh geometric unsharpness","Menghilangkan kebutuhan kalibrasi sumber"]', 1,
   'Sistem digital memiliki rentang dinamis lebar (12–16 bit) sehingga satu eksposur dapat menampilkan ketebalan beragam, dan citra dapat di-window/diolah secara perangkat lunak tanpa eksposur ulang. IQI tetap wajib dan Ug tetap berlaku.', 'Citra Digital', 'easy'),
  ('Kedalaman bit umum sistem radiografi digital industri adalah:',
   '["1–2 bit","8 bit saja","32–64 bit","12–16 bit"]', 3,
   'Detektor radiografi digital industri biasanya mengakuisisi 12–16 bit per piksel (4096–65536 tingkat keabuan), memberi rentang dinamis jauh lebih lebar daripada film.', 'Citra Digital', 'easy'),
  ('Parameter SNR (Signal-to-Noise Ratio) yang dinormalisasi terhadap ukuran piksel pada radiografi digital disebut:',
   '["DQE","SNRnorm (SNR ternormalisasi)","MTF","CNR mentah"]', 1,
   'SNRnorm menormalisasi SNR terukur terhadap dimensi basic spatial resolution/ukuran piksel (mengacu pada SRb), sehingga sistem dengan resolusi berbeda dapat dibandingkan secara setara — kriteria penting pada ISO 17636-2.', 'Citra Digital', 'hard'),
  ('DQE (Detective Quantum Efficiency) pada detektor digital menggambarkan:',
   '["Kecepatan baca detektor","Jumlah piksel cacat","Lebar berkas radiasi","Efisiensi detektor mengubah kuanta sinar-X menjadi sinyal berkualitas (rasio SNR keluaran²/masukan²)"]', 3,
   'DQE mengukur seberapa efisien detektor memanfaatkan kuanta sinar-X yang datang untuk menghasilkan citra, dinyatakan sebagai rasio (SNR keluaran)²/(SNR masukan)². DQE tinggi berarti citra baik pada dosis lebih rendah.', 'Citra Digital', 'hard'),
  ('Pada real-time radiography (RTR)/fluoroskopi, peningkatan kualitas citra dari frame tunggal yang ber-noise umumnya dicapai dengan:',
   '["Menaikkan kV hingga maksimum","Mengurangi waktu eksposur","Frame averaging/integration (penjumlahan beberapa frame)","Mematikan IQI"]', 2,
   'Frame averaging menjumlahkan/merata-ratakan beberapa frame untuk menekan noise acak dan meningkatkan SNR pada citra real-time. Noise acak berkurang sebanding akar jumlah frame.', 'Real-time Imaging', 'medium'),
  ('Keterbatasan utama real-time radiography (RTR) dibanding radiografi film/digital statis adalah:',
   '["Tidak bisa mendeteksi porositas","Resolusi spasial dan kontras umumnya lebih rendah sehingga diskontinuitas halus lebih sulit terlihat","Tidak memerlukan operator tersertifikasi","Hanya berlaku untuk aluminium"]', 1,
   'Sistem real-time (image intensifier/fluoroskopi) umumnya memiliki resolusi spasial dan kontras lebih rendah daripada citra statis, sehingga cacat kecil/halus bisa terlewat; kelebihannya adalah inspeksi dinamis dan cepat.', 'Real-time Imaging', 'medium'),
  ('Sumber gamma Ir-192 memiliki waktu paruh kira-kira:',
   '["74 hari","120 hari","5,27 tahun","30 tahun"]', 0,
   'Ir-192 memiliki waktu paruh ≈74 hari. Se-75 ≈120 hari, Co-60 ≈5,27 tahun.', 'Sumber Radiasi', 'easy'),
  ('Energi gamma rata-rata Co-60 (dua garis utama) adalah:',
   '["0,32 dan 0,47 MeV","0,08 dan 0,40 MeV","1,17 dan 1,33 MeV","2,50 dan 3,00 MeV"]', 2,
   'Co-60 memancarkan dua foton gamma 1,17 MeV dan 1,33 MeV (rata-rata ~1,25 MeV), energi tinggi yang cocok untuk baja tebal. Ir-192 berenergi lebih rendah, Se-75 lebih rendah lagi.', 'Sumber Radiasi', 'medium'),
  ('Sumber gamma yang paling tepat untuk radiografi baja tipis (≈3–20 mm) karena energinya relatif rendah dan kontras baik adalah:',
   '["Co-60","Se-75","Cs-137","Ra-226"]', 1,
   'Se-75 (energi rata-rata ~0,2 MeV) memberi kontras lebih baik pada baja tipis–sedang dibanding Ir-192/Co-60. Co-60 berenergi tinggi untuk baja tebal.', 'Sumber Radiasi', 'medium'),
  ('Sebuah sumber Ir-192 awalnya 100 Ci. Setelah 74 hari aktivitasnya menjadi kira-kira:',
   '["100 Ci","75 Ci","50 Ci","25 Ci"]', 2,
   'Setelah satu waktu paruh (74 hari untuk Ir-192), aktivitas turun menjadi separuh: 100 → 50 Ci. Gunakan A = A0·e^(-0,693·t/t½).', 'Perhitungan Dosis', 'easy'),
  ('Sumber Ir-192 awalnya 100 Ci. Berapa aktivitasnya setelah 30 hari (t½ = 74 hari)?',
   '["≈88 Ci","≈63 Ci","≈50 Ci","≈75 Ci"]', 3,
   'A = 100·e^(-0,693·30/74) = 100·e^(-0,281) ≈ 100·0,755 ≈ 75 Ci.', 'Perhitungan Dosis', 'hard'),
  ('Sebuah eksposur memerlukan 4 menit pada saat aktivitas sumber 100 Ci. Bila aktivitas turun menjadi 50 Ci (faktor lain tetap), waktu eksposur baru menjadi:',
   '["2 menit","4 menit","8 menit","16 menit"]', 2,
   'Waktu eksposur berbanding terbalik dengan aktivitas: t_baru = t_lama × A_lama/A_baru = 4 × 100/50 = 8 menit.', 'Perhitungan Dosis', 'medium'),
  ('Laju dosis 100 mR/jam terukur pada jarak 1 m dari sumber. Berdasarkan hukum kuadrat terbalik, laju dosis pada jarak 3 m adalah:',
   '["≈50 mR/jam","≈33 mR/jam","≈11 mR/jam","≈3 mR/jam"]', 2,
   'I ∝ 1/d². I₂ = 100 × (1/3)² = 100/9 ≈ 11 mR/jam.', 'Perhitungan Dosis', 'medium'),
  ('Sebuah teknik memberi densitas memadai dengan waktu eksposur 2 menit pada SOD 600 mm. Bila SOD diubah menjadi 900 mm (faktor lain tetap), waktu eksposur baru menjadi:',
   '["1,33 menit","3,00 menit","4,50 menit","6,00 menit"]', 2,
   'Intensitas turun dengan kuadrat jarak, jadi waktu naik dengan kuadrat jarak: t₂ = t₁×(d₂/d₁)² = 2×(900/600)² = 2×2,25 = 4,5 menit.', 'Perhitungan Dosis', 'hard'),
  ('Rumus geometric unsharpness (Ug) yang benar adalah:',
   '["Ug = F × SOD / OFD","Ug = F × OFD / SOD","Ug = SOD × OFD / F","Ug = F + OFD − SOD"]', 1,
   'Ug = F × OFD / SOD, dengan F = ukuran focal spot/sumber, OFD = jarak objek ke film/detektor, SOD = jarak sumber ke objek.', 'Pengembangan Teknik', 'easy'),
  ('Dengan F = 3 mm, OFD = 12 mm, dan SOD = 600 mm, nilai Ug adalah:',
   '["0,15 mm","0,30 mm","0,60 mm","0,06 mm"]', 3,
   'Ug = F×OFD/SOD = 3×12/600 = 36/600 = 0,06 mm.', 'Pengembangan Teknik', 'medium'),
  ('Untuk mengurangi geometric unsharpness (Ug) tanpa mengubah sumber, tindakan yang tepat adalah:',
   '["Memperbesar OFD","Memperbesar ukuran focal spot","Menambah SOD (memindahkan sumber lebih jauh)","Menurunkan kV"]', 2,
   'Karena Ug = F×OFD/SOD, menambah SOD menurunkan Ug. Memperbesar OFD atau focal spot justru menaikkan Ug; kV tidak mempengaruhi Ug.', 'Pengembangan Teknik', 'medium'),
  ('Pada teknik double-wall single-image (DWSI) untuk pipa berdiameter besar, yang diradiografi adalah:',
   '["Kedua dinding ditampilkan superimpose","Hanya dinding yang dekat detektor (dinding sumber dikaburkan dan diabaikan)","Hanya bagian luar pipa","Tidak ada dinding yang dievaluasi"]', 1,
   'Pada DWSI, sinar menembus kedua dinding tetapi hanya dinding sisi detektor yang dievaluasi tajam; dinding sisi sumber sengaja diproyeksikan kabur/di luar area evaluasi. Cocok untuk pipa diameter besar.', 'Pengembangan Teknik', 'medium'),
  ('Teknik double-wall double-image (DWDI) elliptical paling sesuai untuk:',
   '["Pelat datar tebal","Coran besar","Pipa diameter kecil (umumnya ≤89 mm) dengan dua dinding tampil sebagai elips","Sambungan paku keling"]', 2,
   'DWDI elliptical dipakai pada pipa diameter kecil; berkas diofset sehingga kedua dinding las tampil terpisah sebagai elips, memungkinkan evaluasi keduanya dalam satu citra. Biasanya dibatasi untuk OD kecil.', 'Pengembangan Teknik', 'medium'),
  ('IQI tipe lubang (hole-type, ASTM E1025) dengan sensitivitas 2-2T berarti:',
   '["Tebal plak 2% ketebalan benda dan lubang berdiameter 2× tebal plak yang harus terlihat","Dua plak ditumpuk","Tebal 2 mm dan lubang 2 mm","Sensitivitas 22%"]', 0,
   'Level 2-2T: plak IQI bertebal 2% dari ketebalan yang diradiografi dan lubang berdiameter 2T (dua kali tebal plak) harus terlihat — kira-kira setara sensitivitas radiografi 2%.', 'IQI', 'hard'),
  ('Standar IQI kawat (wire-type) untuk radiografi mengacu pada:',
   '["ASTM E747","ASTM E1025","ASTM E2002","ASTM E94"]', 0,
   'IQI tipe kawat mengacu ASTM E747. IQI tipe lubang/plak mengacu E1025, sedangkan duplex wire (resolusi) mengacu E2002.', 'IQI', 'medium'),
  ('Duplex wire IQI (ASTM E2002) digunakan untuk mengukur:',
   '["Densitas film","Aktivitas sumber","Ketebalan benda uji","Resolusi spasial dasar/unsharpness sistem (basic spatial resolution, SRb)"]', 3,
   'Duplex wire IQI menilai resolusi spasial dasar/ketajaman sistem (SRb) — pasangan kawat yang masih dapat dibedakan menunjukkan unsharpness total sistem; krusial pada radiografi digital ISO 17636-2.', 'IQI', 'hard'),
  ('Penempatan IQI yang lebih disukai pada radiografi adalah pada sisi sumber (source side) karena:',
   '["Lebih mudah dijangkau","Menghemat film","Mewakili kondisi terburuk geometric unsharpness dan ketebalan total","Meniadakan kebutuhan densitas"]', 2,
   'IQI sisi sumber mewakili kondisi paling tidak menguntungkan (unsharpness dan ketebalan penuh). Bila IQI ditempatkan di sisi film, biasanya diberi tanda huruf ''F'' dan sensitivitas yang lebih ketat diperlukan.', 'IQI', 'medium'),
  ('Menurut ASME Section V, rentang densitas film yang dapat diterima untuk radiografi sinar-X (X-ray) adalah:',
   '["1,0–2,0","1,8–4,0","2,0–4,0","0,5–1,5"]', 1,
   'ASME V: densitas film X-ray 1,8–4,0; untuk gamma 2,0–4,0. Densitas di luar rentang ini ditolak.', 'Optimasi Kualitas Citra', 'medium'),
  ('Menurut ASME Section V, densitas minimum untuk radiografi sumber gamma adalah:',
   '["1,5","1,8","2,0","2,5"]', 2,
   'ASME V menetapkan densitas film gamma minimum 2,0 (maksimum 4,0); untuk X-ray minimum 1,8.', 'Optimasi Kualitas Citra', 'medium'),
  ('ASME Section V membatasi variasi densitas melalui area badan IQI/area of interest sebesar:',
   '["±5%","−50% hingga +50%","0% (harus seragam mutlak)","−15% hingga +30% dari densitas di badan IQI"]', 3,
   'ASME V mengizinkan densitas pada area of interest bervariasi tidak lebih dari −15% sampai +30% relatif terhadap densitas yang terbaca melalui badan IQI.', 'Optimasi Kualitas Citra', 'hard'),
  ('Untuk meningkatkan kontras radiografik pada radiografi film, tindakan yang umumnya efektif adalah:',
   '["Menaikkan kV setinggi mungkin","Menurunkan kV (energi efektif lebih rendah) selama penetrasi masih memadai","Menambah jarak film","Memperbesar focal spot"]', 1,
   'Kontras subjek meningkat saat energi efektif (kV) lebih rendah karena perbedaan penyerapan antar ketebalan lebih besar, selama penetrasi tetap cukup. kV terlalu tinggi menurunkan kontras.', 'Optimasi Kualitas Citra', 'medium'),
  ('Penggunaan lead intensifying screen pada radiografi berfungsi untuk:',
   '["Menambah blur citra","Menurunkan densitas","Memperkuat efek foto pada film dan menyaring radiasi hambur sehingga citra lebih tajam","Menggantikan IQI"]', 2,
   'Lead screen memancarkan elektron yang memperkuat aksi film (mengurangi waktu eksposur) sekaligus menyerap radiasi hambur berenergi rendah, meningkatkan ketajaman dan kontras.', 'Optimasi Kualitas Citra', 'medium'),
  ('Unsharpness total (Ut) sistem radiografi merupakan kombinasi dari:',
   '["Hanya geometric unsharpness","Hanya densitas film","Aktivitas sumber dan kV","Geometric unsharpness dan inherent/detector unsharpness (digabung secara kuadratik)"]', 3,
   'Ut menggabungkan ketidaktajaman geometris (Ug) dan inherent/film/detector unsharpness (Uf/Ud), biasanya Ut ≈ (Ug^n + Uf^n)^(1/n). Keduanya harus diminimalkan untuk ketajaman optimal.', 'Optimasi Kualitas Citra', 'hard'),
  ('Keterbatasan mendasar RT dalam menentukan ukuran cacat adalah:',
   '["Tidak dapat mendeteksi porositas","Buruk dalam pengukuran dimensi melintang dinding/ketinggian (through-wall/height) cacat planar","Tidak dapat mendeteksi inklusi terak","Hanya bekerja pada aluminium"]', 1,
   'RT memberi proyeksi 2D sehingga lemah dalam menentukan tinggi/through-wall cacat planar (mis. crack, lack of fusion). UT (terutama TOFD/phased array) lebih unggul untuk height sizing.', 'Sizing & Keterbatasan RT', 'medium'),
  ('Cacat planar (mis. lack of fusion atau crack) sulit terdeteksi RT bila:',
   '["Bidang cacat sejajar (paralel) terhadap arah berkas radiasi","Bidang cacat tegak lurus berkas","Cacat berisi udara","Cacat berukuran besar"]', 0,
   'RT mendeteksi cacat melalui perbedaan ketebalan/penyerapan sepanjang arah berkas. Cacat planar yang bidangnya hampir sejajar berkas memberi perubahan absorpsi sangat kecil sehingga mudah terlewat; peluang deteksi tertinggi bila bidang cacat sejajar berkas. Orientasi sumber sering disesuaikan untuk cacat planar.', 'Sizing & Keterbatasan RT', 'hard'),
  ('Pada radiograf, indikasi gelap membulat tersebar dengan tepi halus paling mungkin merupakan:',
   '["Crack","Porositas","Incomplete penetration","Undercut"]', 1,
   'Porositas tampak sebagai bintik gelap membulat (rongga gas) dengan tepi halus dan tersebar/berkelompok. Crack tampak garis gelap tak teratur; IP tampak garis gelap lurus di akar.', 'Sizing & Keterbatasan RT', 'easy'),
  ('Indikasi terang (lebih putih dari logam las) pada radiograf umumnya menandakan:',
   '["Rongga gas/porositas","Lack of fusion","Crack","Inklusi material berdensitas lebih tinggi (mis. tungsten)"]', 3,
   'Inklusi berdensitas lebih tinggi seperti tungsten (dari proses GTAW) menyerap lebih banyak radiasi sehingga tampak terang/putih. Rongga dan cacat berisi udara tampak lebih gelap.', 'Sizing & Keterbatasan RT', 'medium'),
  ('Indikasi garis gelap lurus dan kontinu tepat di tengah lebar las akar pada pipa kemungkinan adalah:',
   '["Excess penetration","Incomplete/lack of penetration (IP/LOP)","Porositas tersebar","Tungsten inclusion"]', 1,
   'Incomplete/lack of penetration tampak sebagai garis gelap lurus, sempit, dan terdefinisi tajam di sepanjang centerline akar las, menunjukkan logam las tidak mengisi akar sepenuhnya.', 'Sizing & Keterbatasan RT', 'medium'),
  ('Bila RT meragukan untuk menentukan tinggi (through-wall extent) sebuah indikasi planar pada las kritis, metode pelengkap yang direkomendasikan adalah:',
   '["MT pada permukaan saja","PT","UT (mis. TOFD atau phased array) untuk height sizing","Mengulang RT dengan kV lebih tinggi"]', 2,
   'Karena RT lemah dalam through-wall sizing, UT — terutama TOFD/phased array — dipakai untuk mengukur tinggi/kedalaman cacat planar secara akurat sebagai pelengkap.', 'Sizing & Keterbatasan RT', 'easy'),
  ('Dalam pengembangan prosedur RT (ASME V), salah satu variabel esensial yang bila berubah memerlukan kualifikasi ulang/revisi prosedur adalah:',
   '["Nama radiografer","Perubahan jenis/kelas film atau detektor di luar yang dikualifikasi","Suhu ruangan kantor","Warna kotak penyimpanan film"]', 1,
   'Variabel esensial (mis. jenis/kelas film atau sistem detektor, sumber/energi, geometri, screen) mempengaruhi hasil dan bila berubah di luar rentang yang dikualifikasi mengharuskan prosedur direvisi/dikualifikasi ulang.', 'Pengembangan Prosedur', 'medium'),
  ('Sebuah prosedur RT yang terdokumentasi minimal harus mencakup, kecuali:',
   '["Teknik (SWSI/DWSI/DWDI), sumber, dan rentang ketebalan","Persyaratan IQI dan densitas","Kriteria penerimaan yang diacu (code)","Harga jual jasa radiografi"]', 3,
   'Prosedur RT memuat ruang lingkup, teknik, peralatan/sumber, geometri, IQI, densitas, pemrosesan, dan kriteria penerimaan code. Harga jual bukan elemen teknis prosedur.', 'Pengembangan Prosedur', 'easy'),
  ('Tujuan penempatan blok penanda lokasi (location markers) yang terproyeksi pada film, menurut ASME V, adalah:',
   '["Mengganti IQI","Menambah densitas","Memberikan rujukan posisi yang dapat ditelusuri antara film dan benda uji","Menandai tanggal kedaluwarsa film"]', 2,
   'Location markers (ditempatkan pada benda, bukan hanya pada film) memberikan ketertelusuran posisi agar setiap indikasi dapat dipetakan kembali ke lokasi fisik pada benda uji.', 'Pengembangan Prosedur', 'medium'),
  ('Artikel pada ASME Section V yang mengatur metode pemeriksaan radiografi adalah:',
   '["Article 1","Article 2","Article 6","Article 23"]', 1,
   'ASME Section V Article 2 mengatur Radiographic Examination (teknik, IQI, densitas, geometri). Article 6 adalah PT, Article 23 berisi standar SE/SD yang diadopsi.', 'Interpretasi Code', 'easy'),
  ('Kriteria penerimaan (acceptance) untuk hasil radiografi pada bejana tekan dengan ASME biasanya dirujuk ke:',
   '["ASME Section V Article 2","ASME Section VIII (untuk bejana) atau B31 (untuk pipa)","ASTM E747","ISO 9712"]', 1,
   'ASME V menetapkan cara/teknik pemeriksaan, sedangkan kriteria penerimaan ada di code konstruksi: Section VIII untuk bejana tekan, B31.x untuk pipa proses. Standar dan code teknik dipisahkan dari kriteria penerimaan.', 'Interpretasi Code', 'medium'),
  ('Klausa/Clause yang mengatur RT pada AWS D1.1 (Structural Welding Code – Steel) adalah:',
   '["Clause 2","Clause 4","Clause 8 (Inspection — RT, sebelumnya Clause 6)","Clause 12"]', 2,
   'Inspeksi termasuk persyaratan RT pada AWS D1.1 berada di klausa Inspection (Clause 8 pada edisi terkini, sebelumnya Clause 6). Klausa ini memuat kriteria penerimaan RT untuk struktur statis dan siklik.', 'Interpretasi Code', 'medium'),
  ('Standar yang khusus mengatur radiografi las pengelasan pipeline dengan kriteria penerimaan berbasis workmanship dan opsi alternatif (Annex A, ECA) adalah:',
   '["API 1104","ASME B16.5","ISO 9712","ASTM E1025"]', 0,
   'API 1104 mengatur pengelasan pipeline dan menyediakan kriteria penerimaan radiografi workmanship serta Annex A untuk alternative acceptance criteria (engineering critical assessment/fitness-for-service).', 'Interpretasi Code', 'medium'),
  ('Standar internasional untuk teknik radiografi las dengan film (ISO) dan kriteria penerimaannya masing-masing adalah:',
   '["ISO 17636-1 (teknik film) dan ISO 10675-1 (kriteria penerimaan)","ISO 9712 dan ISO 9001","ASTM E94 dan E747","ISO 17636-2 dan ISO 5817 saja"]', 0,
   'ISO 17636-1 mengatur teknik RT film untuk las, ISO 17636-2 untuk teknik digital, dan ISO 10675-1 memberi level penerimaan untuk las baja. ISO 9712 adalah kualifikasi personel.', 'Interpretasi Code', 'hard'),
  ('Pada ISO 17636-2 (radiografi digital las), klasifikasi teknik ''Class B'' dibanding ''Class A'' berarti:',
   '["Teknik dasar dengan sensitivitas lebih rendah","Hanya untuk aluminium","Teknik dengan persyaratan kualitas citra lebih tinggi (improved technique)","Tidak memerlukan IQI"]', 2,
   'Class A adalah teknik dasar, Class B adalah teknik yang lebih baik (improved) dengan persyaratan lebih ketat (mis. SOD, SRb, SNR) untuk sensitivitas deteksi lebih tinggi.', 'Interpretasi Code', 'hard'),
  ('Batas dosis efektif tahunan untuk pekerja radiasi (occupational) menurut praktik ICRP/regulasi umum adalah:',
   '["1 mSv/tahun","20 mSv/tahun (rata-rata, maks 50 mSv satu tahun)","100 mSv/tahun","500 mSv/tahun"]', 1,
   'Batas okupasional umumnya 20 mSv/tahun dirata-rata 5 tahun, dengan maksimum 50 mSv pada satu tahun mana pun. Batas publik 1 mSv/tahun.', 'RSO Awareness', 'easy'),
  ('Batas dosis tahunan untuk anggota masyarakat umum (public) adalah:',
   '["20 mSv/tahun","5 mSv/tahun","1 mSv/tahun","50 mSv/tahun"]', 2,
   'Batas dosis efektif publik adalah 1 mSv/tahun. Batas pekerja radiasi 20 mSv/tahun.', 'RSO Awareness', 'easy'),
  ('Batas laju dosis yang mendefinisikan ''high radiation area'' (area radiasi tinggi) adalah:',
   '["2 mR/jam","5 mR/jam","100 mR/jam","1000 mR/jam"]', 2,
   'Restricted/controlled boundary umumnya ditetapkan pada 2 mR/jam, sedangkan high radiation area didefinisikan mulai 100 mR/jam. Batas-batas ini dipakai untuk pemasangan barikade dan tanda.', 'RSO Awareness', 'medium'),
  ('Prinsip ALARA dalam proteksi radiasi mengandalkan tiga faktor utama:',
   '["Waktu, jarak, dan perisai (shielding)","kV, mA, dan waktu","Suhu, tekanan, dan kelembaban","Film, screen, dan developer"]', 0,
   'ALARA (As Low As Reasonably Achievable) menekan dosis dengan mengurangi waktu paparan, menambah jarak (kuadrat terbalik), dan menggunakan perisai (shielding).', 'RSO Awareness', 'easy'),
  ('Survey meter (laju dosis) berbeda dengan dosimeter personal karena:',
   '["Survey meter mengukur laju dosis seketika di suatu titik; dosimeter merekam dosis kumulatif yang diterima personel","Keduanya identik","Dosimeter hanya untuk sinar-X","Survey meter mengukur aktivitas sumber"]', 0,
   'Survey meter membaca laju dosis (mis. mR/jam) di lokasi untuk menetapkan barikade; dosimeter personal (mis. TLD/OSL, pen dosimeter) merekam dosis kumulatif individu untuk pemantauan kepatuhan batas.', 'RSO Awareness', 'medium'),
  ('Sebelum mengeluarkan/menarik sumber gamma dari kamera eksposur (crank-out), radiografer wajib:',
   '["Mematikan survey meter agar tidak menguras baterai","Melepas dosimeter personal","Memastikan survey meter berfungsi, area dibarikade, dan melakukan survey saat sumber keluar dan setelah ditarik","Menambah aktivitas sumber"]', 2,
   'Praktik wajib: survey meter terkalibrasi/berfungsi, area dibarikade pada batas dosis yang sesuai, dan survey dilakukan saat sumber terpapar serta setelah ditarik untuk memastikan sumber kembali ke posisi terlindung (guard tube aman).', 'RSO Awareness', 'medium'),
  ('Dalam QC/audit program RT, kalibrasi densitometer terhadap step wedge comparison film bersertifikat bertujuan untuk:',
   '["Menambah kontras film","Mengganti IQI","Mengurangi waktu eksposur","Memverifikasi akurasi pengukuran densitas dan konsistensi proses sehingga hasil tertelusur"]', 3,
   'Kalibrasi densitometer terhadap step wedge bersertifikat memastikan pembacaan densitas akurat dan tertelusur, bagian penting QC agar penerimaan/penolakan berbasis densitas valid.', 'QC & Audit', 'medium'),
  ('Pada audit sistem mutu RT, ketidaksesuaian (nonconformance) berupa prosedur RT yang tidak mencantumkan kriteria penerimaan code akan dikategorikan sebagai:',
   '["Observasi minor tanpa tindakan","Temuan yang memerlukan corrective action karena prosedur tidak lengkap/tidak memenuhi persyaratan","Hal yang dapat diabaikan","Pujian"]', 1,
   'Prosedur tanpa kriteria penerimaan tidak memenuhi persyaratan code dan menimbulkan risiko evaluasi tidak konsisten; auditor menerbitkan temuan (NCR) yang menuntut corrective action.', 'QC & Audit', 'medium'),
  ('Penilaian kondisi base fog/film fog yang berlebihan pada QC film menunjukkan:',
   '["Film terlalu tajam","Sumber terlalu lemah","Densitas selalu terlalu rendah","Kemungkinan film kedaluwarsa, paparan cahaya/panas, atau kontaminasi developer yang menurunkan kontras"]', 3,
   'Fog tinggi (kerudung) menurunkan kontras dan dapat menyembunyikan indikasi; penyebabnya antara lain film kedaluwarsa/penyimpanan buruk, bocor cahaya, panas, atau pemrosesan/developer terkontaminasi. QC membatasi fog maksimum.', 'QC & Audit', 'hard'),
  ('Sebuah laporan radiografi yang lengkap harus mencakup informasi berikut, kecuali:',
   '["Identifikasi benda/las, teknik & parameter (sumber, kV/Ci, SFD), IQI & densitas","Indikasi yang ditemukan, lokasi, dan keputusan terima/tolak terhadap code","Identitas dan kualifikasi personel serta tanggal","Merek mobil radiografer"]', 3,
   'Laporan RT memuat identifikasi benda, teknik/parameter, IQI dan densitas, hasil interpretasi indikasi beserta lokasi, kriteria penerimaan, serta personel/tanggal. Merek kendaraan tidak relevan.', 'Reporting & Arsip', 'easy'),
  ('Pada radiografi digital, format dan metadata penyimpanan citra yang disarankan untuk ketertelusuran dan interoperabilitas jangka panjang adalah:',
   '["JPEG kompresi tinggi tanpa metadata","Screenshot layar (PNG)","DICONDE (DICOM for NDE) yang menyertakan metadata akuisisi","Format proprietary tanpa dokumentasi"]', 2,
   'DICONDE (berbasis DICOM untuk NDE) menyimpan citra beserta metadata akuisisi (teknik, kalibrasi, identitas) sehingga arsip tertelusur dan interoperabel. JPEG lossy/screenshot tidak menjaga integritas data kuantitatif.', 'Reporting & Arsip', 'hard'),
  ('Saat menulis interpretasi, seorang RT Level II harus memastikan bahwa keputusan terima/tolak:',
   '["Didasarkan pada opini pribadi","Mengacu secara spesifik pada kriteria penerimaan code/spesifikasi yang berlaku","Mengabaikan ukuran indikasi","Sama untuk semua jenis konstruksi"]', 1,
   'Keputusan evaluasi harus tertelusur ke kriteria penerimaan code/spesifikasi yang berlaku (mis. ASME VIII, B31, AWS D1.1, API 1104), bukan opini; ukuran, jenis, dan akumulasi indikasi dinilai sesuai aturan tersebut.', 'Reporting & Arsip', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 16 AND ls."orderIndex" = 1 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;

-- RT-L2 Module 1 (1 steps)
INSERT INTO "LessonSteps" ("ModuleId", "orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
SELECT m.id, s."orderIndex", s.kind::lesson_step_kind, s.title, s."contentJson"::jsonb, s."durationSeconds", s."simulationRef"
FROM "Modules" m JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  (4, 'quiz', 'Mini-quiz — RT-L2 scope', '{"description":"5 soal scope Level II RT (kewenangan Level I vs II, technique development, RSO terpisah, batas peran sizing).","questionCount":5,"passingScore":75}', 600, NULL)
) AS s("orderIndex", kind, title, "contentJson", "durationSeconds", "simulationRef")
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 1
ON CONFLICT ("ModuleId", "orderIndex") DO NOTHING;
-- RT-L2 Module 1 mini-quiz (5 questions, step 4)
DELETE FROM "QuizQuestions" WHERE "LessonStepId" IN (SELECT ls.id FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id WHERE lp.code = 'RT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz');
INSERT INTO "QuizQuestions" ("LessonStepId", question, options, "correctAnswer", explanation, category, method, level, difficulty)
SELECT ls.id, qq.question, qq.options::jsonb, qq."correctAnswer", qq.explanation, qq.category, 'RT', 'Level II', qq.difficulty
FROM "LessonSteps" ls JOIN "Modules" m ON ls."ModuleId" = m.id JOIN "LearningPaths" lp ON m."LearningPathId" = lp.id
CROSS JOIN (VALUES
  ('Menurut SNT-TC-1A / ASNT CP-105, apa perbedaan kewenangan utama antara RT Level I dan RT Level II?',
   '["Level I melakukan eksposur dan processing sesuai instruksi tertulis, sedangkan Level II mengembangkan teknik, menginterpretasi radiograf, dan melakukan accept/reject serta sign-off","Level I boleh menulis prosedur dan menerima/menolak hasil, sedangkan Level II hanya menjalankan eksposur","Level I dan Level II memiliki kewenangan identik; perbedaannya hanya pada masa kerja","Level II hanya boleh bekerja di bawah pengawasan Level I yang lebih senior"]', 0,
   'Per SNT-TC-1A/ASNT CP-105, Level I melaksanakan setup, eksposur, dan processing sesuai instruksi tertulis serta mencatat hasil, tetapi tidak melakukan interpretasi akhir atau accept/reject mandiri. Level II berwenang menyusun/mengembangkan teknik, menginterpretasi radiograf terhadap kode, melakukan evaluasi accept/reject, dan menandatangani (sign-off) laporan. Jadi sign-off dan interpretasi adalah wewenang Level II, bukan Level I.', 'Scope Level II', 'easy'),
  ('Manakah yang merupakan tanggung jawab TAMBAHAN seorang RT Level II dibanding Level I?',
   '["Hanya memuat dan memproses film sesuai instruksi","Mengkalibrasi survey meter milik instansi pengawas radiasi nasional","Menentukan batas dosis pekerja radiasi tahunan untuk seluruh fasilitas","Mengembangkan/memvalidasi teknik radiografi, melakukan kualifikasi peralatan, menginterpretasi citra, dan memberi sign-off hasil"]', 3,
   'Level II menambah tanggung jawab di atas Level I: technique development (memilih/memvalidasi parameter eksposur, geometri, IQI), equipment qualification, image interpretation terhadap kriteria kode, serta sign-off/penerimaan hasil. Penetapan batas dosis tahunan (mis. okupasi 20 mSv/tahun) dan kalibrasi instrumen pengawas adalah ranah regulasi/RSO, bukan tugas teknis Level II. Sekadar memuat dan memproses film tanpa interpretasi adalah lingkup Level I.', 'Scope Level II', 'medium'),
  ('Dalam pengembangan teknik (technique development) RT, mengapa ini menjadi domain Level II dan bukan Level I?',
   '["Karena penyusunan teknik menuntut penilaian terhadap geometri (mis. Ug = F x OFD / SOD), pemilihan sumber/kV, IQI, dan pembuktian sensitivitas yang memerlukan kompetensi interpretasi dan pengetahuan kode setara Level II","Karena Level I tidak diizinkan menyentuh peralatan radiografi sama sekali","Karena Level I hanya bekerja dengan metode digital, bukan film","Karena pengembangan teknik adalah tugas eksklusif RSO"]', 0,
   'Technique development menuntut keputusan tentang geometri (SOD/OFD dan unsharpness geometris Ug = F x OFD / SOD), pemilihan energi/sumber, jenis dan penempatan IQI, serta pembuktian bahwa sensitivitas dan kualitas citra memenuhi kode — semuanya memerlukan kemampuan interpretasi dan pemahaman kode khas Level II. Level I menjalankan teknik yang sudah ditetapkan. RSO mengurus keselamatan radiasi, bukan teknik inspeksi; dan Level I tetap boleh mengoperasikan peralatan sesuai instruksi.', 'Technique development', 'medium'),
  ('Bagaimana hubungan antara peran RT Level II dan peran Radiation Safety Officer (RSO)?',
   '["Level II secara otomatis merangkap sebagai RSO untuk setiap pekerjaan radiografi","Level I yang menjadi RSO, sedangkan Level II hanya menginterpretasi citra","RSO adalah peran/penunjukan keselamatan radiasi yang TERPISAH; sertifikasi Level II tidak dengan sendirinya memberikan kewenangan RSO","RSO berada di bawah perintah teknis Level II di lapangan"]', 2,
   'RSO adalah penunjukan terpisah yang bertanggung jawab atas program keselamatan radiasi (ALARA time-distance-shielding, batas dosis okupasi 20 mSv/tahun & publik 1 mSv/tahun, kontrol area restricted 2 mR/jam & high-radiation 100 mR/jam, perizinan, dosimetri). Sertifikasi NDT Level II menyangkut kompetensi teknik/interpretasi, bukan kewenangan keselamatan radiasi. Seseorang bisa memegang keduanya, tetapi keduanya tidak otomatis menyertakan satu sama lain dan tidak saling membawahi.', 'RSO terpisah', 'hard'),
  ('Sebuah weld butt dengan toe crack ditemukan pada radiograf. Manajer meminta RT Level II melaporkan tinggi (through-wall height) retak tersebut untuk penilaian engineering critical assessment (ECA). Tindakan yang paling tepat bagi Level II adalah:',
   '["Mengukur langsung tinggi retak dari satu radiograf tunggal dan melaporkannya sebagai dimensi through-wall yang akurat","Menjelaskan bahwa RT lemah dalam sizing through-wall/height dan merekomendasikan metode pelengkap (mis. UT/double-wall technique) untuk pengukuran tinggi cacat yang andal","Menolak melaporkan apa pun karena sizing cacat sepenuhnya di luar kewenangan Level II","Memperkirakan tinggi retak dari densitas film (1,8-4,0) karena densitas berbanding lurus dengan kedalaman cacat"]', 1,
   'RT pada dasarnya memproyeksikan volume ke bidang 2D sehingga buruk untuk mengukur dimensi through-wall/height, terutama cacat planar seperti crack. Level II yang kompeten mengenali keterbatasan metode dan merekomendasikan teknik pelengkap untuk sizing tinggi: ultrasonic testing (UT) atau, untuk perkiraan kedalaman, double-wall/parallax (double exposure) RT — bukan satu radiograf tunggal. Densitas film (rentang X-ray 1,8-4,0) menyatakan tingkat penghitaman/eksposur, BUKAN kedalaman cacat, jadi tidak boleh dipakai untuk sizing. Menolak total juga salah: Level II tetap melaporkan keberadaan/karakter cacat, hanya saja sizing through-wall dirujuk ke metode yang sesuai.', 'Batas metode & sizing', 'medium')
) AS qq(question, options, "correctAnswer", explanation, category, difficulty)
WHERE lp.code = 'RT-L2' AND m."orderIndex" = 1 AND ls."orderIndex" = 4 AND ls.kind = 'quiz'
ON CONFLICT DO NOTHING;


